  function log(message, type = '') {
    message = localizeMessage(message);
    const time = new Date().toLocaleTimeString(locale(), {hour:'2-digit', minute:'2-digit', second:'2-digit'});
    if (logBox) {
      const row = document.createElement('div');
      row.className = type ? `hk-log-${type}` : '';
      row.textContent = `[${time}] ${message}`;
      logBox.prepend(row);
      while (logBox.children.length > 80) logBox.lastElementChild.remove();
    }
    if (statusLine) statusLine.textContent = message;
  }

  function headersToObject(headers) {
    const result = {};
    try { new Headers(headers || {}).forEach((value, key) => result[key] = value); } catch (_) {}
    return result;
  }

  function captureAuthorization(url, headers) {
    if (!url) return false;
    const resolvedUrl = new URL(url, location.href);
    // The shared catalog has its own bearer token. Never let that request
    // replace the captured Hamster King API address and game authorization.
    if (resolvedUrl.origin === new URL(LICENSE_URL).origin) return false;
    const auth = Object.entries(headers || {}).find(([key]) => key.toLowerCase() === 'authorization');
    if (!auth?.[1]) return false;
    const previousAuthorization = String(apiHeaders.Authorization || '');
    apiBase = resolvedUrl.origin;
    apiHeaders = {Authorization: auth[1], Accept: 'application/json, text/plain, */*', 'Content-Type': 'application/json'};
    authUpdatedAt = Date.now();
    if (previousAuthorization !== String(apiHeaders.Authorization || '') && licenseState?.publicCollectorAuthSync) {
      setTimeout(() => { maybeSyncPublicCollectorAuthorization().catch(() => {}); }, 0);
    }
    return true;
  }

  function jwtPayload(token) {
    try {
      const encoded = String(token || '').replace(/^Bearer\s+/i,'').split('.')[1];
      if (!encoded) return null;
      const padded = encoded.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(encoded.length/4)*4,'=');
      return JSON.parse(atob(padded));
    } catch (_) { return null; }
  }

  function jwtExpiration(token) {
    return Number(jwtPayload(token)?.exp || 0) * 1000;
  }

  function gameBearerPlayerId(token) {
    const payload = jwtPayload(token) || {};
    return clean(payload.id ?? payload.player_id ?? payload.playerId ?? payload.user_id ?? payload.sub ?? '');
  }

  function sameGameJwt(currentToken, candidateToken) {
    const current = jwtPayload(currentToken);
    const candidate = jwtPayload(candidateToken);
    if (!current || !candidate) return false;
    const currentId = gameBearerPlayerId(currentToken);
    const candidateId = gameBearerPlayerId(candidateToken);
    if (currentId && candidateId) return currentId === candidateId;
    const stableClaims = ['sub','iss','aud'];
    let compared = 0;
    for (const claim of stableClaims) {
      if (current[claim] == null || candidate[claim] == null) continue;
      compared += 1;
      if (JSON.stringify(current[claim]) !== JSON.stringify(candidate[claim])) return false;
    }
    return compared > 0;
  }

  function currentGameBearer() {
    return String(apiHeaders.Authorization || '').replace(/^Bearer\s+/i,'').trim();
  }

  function refreshStoredGameAuthorization() {
    let newest = '', newestExpiration = 0;
    const pattern = /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g;
    const currentAuthorization = apiHeaders.Authorization || '';
    for (const storage of [sessionStorage, localStorage]) {
      try {
        for (let index = 0; index < storage.length; index += 1) {
          const raw = String(storage.getItem(storage.key(index)) || '');
          if (!raw || raw.length > 1_000_000) continue;
          for (const token of raw.match(pattern) || []) {
            if (currentAuthorization && !sameGameJwt(currentAuthorization, token)) continue;
            const expiration = jwtExpiration(token);
            if (expiration > newestExpiration && expiration > Date.now() + 5000) {
              newest = token; newestExpiration = expiration;
            }
          }
        }
      } catch (_) {}
    }
    if (!newest) return false;
    const authorization = `Bearer ${newest}`;
    if (apiHeaders.Authorization === authorization) return false;
    apiHeaders = {...apiHeaders, Authorization:authorization, Accept:'application/json, text/plain, */*', 'Content-Type':'application/json'};
    authUpdatedAt = Date.now();
    setHealth('auth', true, 'токен восстановлен из браузера');
    recordDiagnostic('auth-restored',{fingerprint:diagnosticFingerprint(newest), expiresAt:newestExpiration});
    return true;
  }

  function authParamsFromUrl(url, source = 'network-url') {
    try {
      const parsed = new URL(String(url || ''), location.href);
      if (parsed.pathname !== '/auth/create') return null;
      const authType = clean(parsed.searchParams.get('auth_type') || parsed.searchParams.get('authType'));
      const authData = clean(parsed.searchParams.get('auth_data') || parsed.searchParams.get('authData'));
      const platform = clean(parsed.searchParams.get('platform'));
      if (!authType || !authData || !platform) return null;
      return {authType, authData, platform, source};
    } catch (_) { return null; }
  }

  function authParamsFromBody(body, source = 'network-body') {
    if (body == null) return null;
    let value = body;
    try {
      if (typeof FormData !== 'undefined' && body instanceof FormData) {
        value = Object.fromEntries(body.entries());
      } else if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
        value = Object.fromEntries(body.entries());
      } else if (typeof body === 'string') {
        try { value = JSON.parse(body); }
        catch (_) { value = Object.fromEntries(new URLSearchParams(body).entries()); }
      }
    } catch (_) { return null; }
    if (!value || typeof value !== 'object') return null;
    const authType = clean(value.auth_type ?? value.authType);
    const authData = clean(value.auth_data ?? value.authData);
    const platform = clean(value.platform);
    if (!authType || !authData || !platform) return null;
    return {authType, authData, platform, source};
  }

  function captureNativeGameAuthParams(url, body = null, source = 'network') {
    let path = '';
    try { path = new URL(String(url || ''), location.href).pathname; } catch (_) {}
    if (path !== '/auth/create') return false;
    const params = authParamsFromUrl(url, `${source}-url`) || authParamsFromBody(body, `${source}-body`);
    if (!params) return false;
    observedNativeGameAuthParams = params;
    return true;
  }

  function captureNativeGameAuthToken(documentValue) {
    const token = clean(documentValue?.token);
    if (!token || jwtExpiration(token) <= Date.now() + 5000) return false;
    observedNativeGameToken = token;
    return true;
  }

  function readNativeGameAuthParams() {
    if (observedNativeGameAuthParams?.authType && observedNativeGameAuthParams?.authData && observedNativeGameAuthParams?.platform) {
      return {...observedNativeGameAuthParams};
    }

    try {
      const webApp = window.Telegram?.WebApp;
      const initData = String(webApp?.initData || '');
      if (webApp && webApp.platform && webApp.platform !== 'unknown' && initData) {
        return {authType:'MiniApp', authData:initData.replaceAll('&','%26'), platform:'TG', source:'telegram-passive'};
      }
    } catch (_) {}

    try {
      const stored = JSON.parse(localStorage.getItem('auth-data') || 'null');
      const authType = clean(stored?.params?.auth_type);
      const authData = clean(stored?.params?.auth_data);
      const platform = clean(stored?.params?.platform || 'WEB');
      const remembered = clean(localStorage.getItem('remember-me'));
      if (authType && authData && remembered === authType) {
        return {authType, authData, platform, source:'browser-storage-passive'};
      }
    } catch (_) {}

    try {
      const entries = performance.getEntriesByType('resource').slice().reverse();
      for (const entry of entries) {
        const params = authParamsFromUrl(entry?.name, 'performance-passive');
        if (!params) continue;
        observedNativeGameAuthParams = params;
        return {...params};
      }
    } catch (_) {}

    return null;
  }

  function publicCollectorServerPost(url, payload, timeoutMs = 12000) {
    // AUTH_BRIDGE_XHR_TRANSPORT_R1
    // Deliberately independent from the game fetch/runner path.
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('POST', url, true);
      xhr.timeout = Math.max(1000, Number(timeoutMs) || 12000);
      xhr.setRequestHeader('Content-Type', 'application/json');
      xhr.setRequestHeader('Authorization', 'Bearer ' + String(licenseState.token || ''));
      xhr.onload = () => {
        let body = null;
        try { body = JSON.parse(xhr.responseText || '{}'); } catch (_) {}
        resolve({ok:xhr.status >= 200 && xhr.status < 300, status:xhr.status, body});
      };
      xhr.onerror = () => reject(new Error('network_error'));
      xhr.ontimeout = () => reject(new Error('timeout'));
      xhr.send(JSON.stringify(payload || {}));
    });
  }

  async function maybeSyncPublicCollectorAuthorization(token = currentGameBearer() || observedNativeGameToken) {
    token = clean(token);
    if (!licenseState.allowed || !licenseState.publicCollectorAuthSync || !licenseState.token || !token) return false;
    const expiresAt = jwtExpiration(token);
    if (expiresAt && expiresAt <= Date.now() + 5000) return false;
    const fingerprint = diagnosticFingerprint(token);
    if (fingerprint && fingerprint === publicCollectorAuthLastFingerprint) return true;
    if (publicCollectorAuthSyncPromise) return publicCollectorAuthSyncPromise;
    publicCollectorAuthSyncPromise = (async () => {
      const params = readNativeGameAuthParams();
      if (!params?.authType || !params?.authData || !params?.platform) {
        recordDiagnostic('collector-auth-sync-skipped',{reason:'bootstrap-unavailable'});
        return false;
      }
      try {
        const result = await publicCollectorServerPost(
          PUBLIC_COLLECTOR_AUTH_SYNC_URL,
          {
            game_token:token,
            auth_type:params.authType,
            auth_data:params.authData,
            platform:params.platform
          },
          15000
        );
        const documentValue=result.body;
        if (!result.ok || !documentValue?.accepted) {
          recordDiagnostic('collector-auth-sync-failed',{status:result.status});
          return false;
        }
        publicCollectorAuthLastFingerprint=fingerprint;
        recordDiagnostic('collector-auth-sync-ok',{expiresAt:expiresAt||null,authType:params.authType,platform:params.platform});
        return true;
      } catch (error) {
        recordDiagnostic('collector-auth-sync-network-error',{error:error?.message || error});
        return false;
      }
    })();
    try { return await publicCollectorAuthSyncPromise; }
    finally { publicCollectorAuthSyncPromise=null; }
  }


  let publicCollectorActivityPromise=null;
  let publicCollectorActivityLastActive=null;
  let publicCollectorActivityLastSentAt=0;

  async function syncPublicCollectorActivity(active,reason='',force=false) {
    active=!!active;
    if(!licenseState.allowed||!licenseState.token||!licenseState.publicCollectorAuthSync)return false;
    const now=Date.now();
    if(!force&&publicCollectorActivityLastActive===active&&now-publicCollectorActivityLastSentAt<15000)return true;
    if(publicCollectorActivityPromise&&!force)return publicCollectorActivityPromise;
    publicCollectorActivityPromise=(async()=>{
      try{
        const result=await publicCollectorServerPost(
          PUBLIC_COLLECTOR_ACTIVITY_URL,
          {active,ttl_seconds:PUBLIC_COLLECTOR_ACTIVITY_TTL_SECONDS,reason:String(reason||'').slice(0,120)},
          8000
        );
        if(!result.ok||!result.body?.ok){
          recordDiagnostic('collector-activity-sync-failed',{status:result.status,active});
          return false;
        }
        publicCollectorActivityLastActive=active;
        publicCollectorActivityLastSentAt=Date.now();
        recordDiagnostic('collector-activity-sync-ok',{active,leaseUntil:Number(result.body?.lease_until||0),reason:String(reason||'').slice(0,80)});
        return true;
      }catch(error){
        recordDiagnostic('collector-activity-sync-network-error',{active,error:error?.message||error});
        return false;
      }finally{
        publicCollectorActivityPromise=null;
      }
    })();
    return publicCollectorActivityPromise;
  }

  function notePublicCollectorRunnerActivity(state=hkRunner.state) {
    const runnerActive=['running','paused','stopping'].includes(String(state?.status||''));
    const active=runnerActive||autoRoutineLeaseHold;
    if(active){
      const reason=autoRoutineLeaseHold ? 'auto-routine' : String(state?.title||'automation');
      void syncPublicCollectorActivity(true,reason,false);
    }else if(publicCollectorActivityLastActive===true){
      void syncPublicCollectorActivity(false,String(state?.title||'idle'),true);
    }
  }

  async function refreshGoogleAuthData(params) {
    // TECHNICAL_PASSIVE_AUTH_BRIDGE_R1: never prompt or refresh Google auth.
    return params || null;
  }

  async function checkGameBearer(token) {
    // TECHNICAL_PASSIVE_AUTH_BRIDGE_R1: local expiry check only; no /auth/check.
    return !!token && jwtExpiration(token) > Date.now() + 5000;
  }

  async function createFreshGameAuthorization(reason = 'refresh', expectedToken = '') {
    // TECHNICAL_PASSIVE_AUTH_BRIDGE_R1: native game exclusively owns /auth/create.
    recordDiagnostic('auth-create-blocked-passive-only',{reason});
    return '';
  }

  async function ensureGameAuthorization(force = false, reason = 'runtime') {
    // AUTH_PASSIVE_SAFETY_R1
    // Never create or refresh a game session from the userscript. The native
    // game owns /auth/create. We only consume a bearer already issued by it.
    restoreGameApiBaseFromPerformance();
    if (!apiBase) apiBase = GAME_API_FALLBACK;
    refreshStoredGameAuthorization();
    const token = currentGameBearer();
    const ok = !!token && jwtExpiration(token) > Date.now() + 5000;
    setHealth('auth', ok, ok ? 'авторизация активна' : 'ожидаю вход игры');
    return ok;
  }

  function restoreGameApiBaseFromPerformance() {
    if (apiBase) return true;
    try {
      const entries = performance.getEntriesByType('resource').slice().reverse();
      const useful = new Set(['/player/me','/shop/view','/items','/business_items','/events','/client_config']);
      for (const entry of entries) {
        const url = new URL(String(entry?.name || ''), location.href);
        if (url.origin === new URL(LICENSE_URL).origin) continue;
        if (!useful.has(url.pathname) && !url.pathname.startsWith('/localization/')) continue;
        apiBase = url.origin;
        return true;
      }
    } catch (_) {}
    return false;
  }

  async function bootstrapLateGameConnection() {
    if (playerDocument && apiBase && apiHeaders.Authorization) { setHealth('game', true, 'игра подключена'); return true; }
    const authorized = await ensureGameAuthorization(false, 'late-bootstrap');
    if (!apiBase || !authorized) { setHealth('game', false, 'нет подключения к игре'); return false; }
    try {
      const documentValue = await apiJson('/player/me', 'POST', null, true, 0, 10000);
      acceptPlayerState(`${apiBase}/player/me`, apiHeaders, documentValue, false);
      setHealth('game', true, 'игра отвечает');
      return true;
    } catch (error) {
      recordDiagnostic('late-bootstrap-failed',{error:error?.message || error});
      setHealth('game', false, 'игра не отвечает');
      console.warn('[HK] late connection bootstrap failed', error);
      return false;
    }
  }

  function acceptPlayerState(url, headers, documentValue, partial = false) {
    if (!documentValue || typeof documentValue !== 'object') return;
    if (!captureAuthorization(url, headers)) return;
    // /player/me with `arguments` returns only the requested sections. Keep
    // the rest of the last full response (advertisement, currencies, pits,
    // etc.) instead of replacing it with that partial document.
    setHealth('game', true, 'данные игрока получены');
    setHealth('auth', true, 'игровая сессия активна');
    playerDocument = partial && playerDocument ? {
      ...playerDocument,
      ...documentValue,
      ...(playerDocument.player || documentValue.player ? {player:{...(playerDocument.player || {}), ...(documentValue.player || {})}} : {}),
      ...(playerDocument.data || documentValue.data ? {data:{...(playerDocument.data || {}), ...(documentValue.data || {})}} : {})
    } : documentValue;
    if (partial) hkStateStore.merge(documentValue, 'player/me-partial');
    else hkStateStore.replace(playerDocument, 'player/me');
    playerDocument = hkStateStore.snapshot || playerDocument;
    if(hkBusinessUiVisible()) refreshBusinessData();
    const player = playerDocument.player || {};
    log(`Подключено${player.nickname ? `: ${player.nickname}` : ''}`);
    // Checking access is required to unlock the panel. This does not scan
    // districts or submit any map data; those actions remain manual.
    checkLicense(player);
    scheduleClanShopActualFactsSync();
    // Never scan or upload map areas automatically. The player must explicitly
    // press "Считать карты аккаунта" in the Maps tab for that operation.
  }

  function getDeviceId() {
    const stored = load().deviceId;
    if (stored) return stored;
    const value = (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}_${Math.random()}_${Math.random()}`).replace(/[^A-Za-z0-9_-]/g, '');
    save({deviceId:value});
    return value;
  }

  function playerIdentity(player) {
    return clean(player?.id ?? player?.player_id ?? player?.uuid ?? player?.nickname ?? '');
  }

  function licenseReason(code) {
    return ({not_allowed:'ID не добавлен владельцем', blocked:'Лицензия заблокирована', expired:'Срок лицензии истёк',
      device_limit:'Достигнут лимит устройств', origin_not_allowed:'Домен игры не разрешён', invalid_identity:'Не удалось определить аккаунт',
      update_required:'Требуется обязательное обновление'}[code] || code || 'Проверка не пройдена');
  }

  function updateLicenseUI() {
    setHealth('license', !!licenseState.allowed, licenseState.allowed ? 'доступ разрешён' : (licenseState.checked ? licenseState.reason : 'ожидание'));
    if (!panel) return;
    const gate = root.querySelector('#hk-license-gate');
    const updateBox = root.querySelector('#hk-update-banner');
    const update = licenseState.update;
    if (updateBox && update?.available && update?.download_url) {
      const latest=escapeHtml(update.latest_version || '?');
      updateBox.style.display='block';
      updateBox.className=`hk-update${update.required ? ' required' : ''}`;
      updateBox.innerHTML=`<b>${either('Доступно обновление','Update available')} ${latest}</b>${update.notes ? `<small>${escapeHtml(update.notes).replace(/\n/g,'<br>')}</small>` : ''}<button id="hk-install-update" class="hk-primary">${either('Установить обновление','Install update')}</button>`;
      updateBox.querySelector('#hk-install-update').onclick=()=>{
        const notes=clean(update.notes || '');
        const heading=either(`Изменения версии ${latest}:`,`Changes in version ${latest}:`);
        const instruction=either('После открытия файла нажмите значок расширений Safari возле адресной строки → Userscripts → Install/Update.',
          'After the file opens, tap the Safari extensions icon beside the address bar → Userscripts → Install/Update.');
        alert(`${heading}${notes ? `\n\n${notes}` : ''}\n\n${instruction}`);
        window.open(String(update.download_url),'_blank','noopener');
      };
    } else if (updateBox) {
      updateBox.style.display='none'; updateBox.innerHTML='';
    }
    if (licenseState.allowed) {
      panel.classList.remove('hk-locked');
      if (gate) { gate.className = 'hk-license ok'; gate.textContent = `${localizeMessage('Доступ разрешён')} · ID: ${licenseState.playerId}`; }
    } else {
      panel.classList.add('hk-locked');
      if (gate) { gate.className = `hk-license ${licenseState.checked ? 'bad' : ''}`; gate.innerHTML = `${escapeHtml(localizeMessage(licenseState.reason))}${licenseState.playerId ? `<br><b>ID: ${escapeHtml(licenseState.playerId)}</b><br><small>${escapeHtml(localizeMessage('Добавьте этот ID в панели владельца'))}</small>` : ''}`; }
      pitRunning = false; fairStop = true;
    }
    updateWatermark();
  }

  function watermarkCode() {
    const stored = clean(load().watermarkCode);
    if (/^[A-Z0-9]{6}$/.test(stored)) return stored;
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    const bytes = new Uint8Array(6); crypto.getRandomValues(bytes);
    const code = [...bytes].map(value => alphabet[value % alphabet.length]).join('');
    save({watermarkCode:code});
    return code;
  }

  function updateWatermark() {
    const layer = root?.querySelector('#hk-watermark');
    if (!layer) return;
    const playerId = clean(licenseState.playerId || playerIdentity(playerDocument?.player || {})) || 'NO-ID';
    const stamp = new Date().toLocaleString(locale(), {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
    const label = `HK · ID ${playerId} · ${stamp} · ${watermarkCode()}`;
    layer.innerHTML = Array.from({length:12}, () => `<span>${escapeHtml(label)}</span>`).join('');
    const phase = Math.floor(Date.now() / 30000) % 4;
    layer.style.transform = `translate(${phase * 7 - 10}px,${(phase % 3) * 9 - 8}px)`;
  }

  async function checkLicense(player, force = false) {
    const playerId = playerIdentity(player);
    if (!playerId) {
      licenseState = {checked:true, allowed:false, playerId:'', reason:'Не удалось определить ID игрового аккаунта'};
      setHealth('license', false, 'не найден ID');
      updateLicenseUI(); return false;
    }
    if (!force && licenseState.allowed && licenseState.playerId === playerId && Date.now() - lastLicenseCheck < LICENSE_RECHECK_MS) return true;
    if (licenseCheckPromise) return licenseCheckPromise;
    const backgroundCheck = licenseState.allowed && licenseState.playerId === playerId;
    if (!backgroundCheck) {
      licenseState = {checked:false, allowed:false, playerId, reason:'Проверяю лицензию…'};
      updateLicenseUI();
    }
    licenseCheckPromise = (async () => {
      let lastError = null;
      for (let attempt = 0; attempt <= SERVER_REQUEST_RETRY_DELAYS_MS.length; attempt += 1) {
        try {
          const response = await new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.open('POST', LICENSE_URL, true);
            xhr.timeout = 12000;
            xhr.setRequestHeader('Content-Type', 'application/json');
            xhr.onload = () => {
              let body = {}; try { body = JSON.parse(xhr.responseText || '{}'); } catch (_) {}
              resolve({ok:xhr.status >= 200 && xhr.status < 300, status:xhr.status, body});
            };
            xhr.onerror = () => reject(new Error('network_error'));
            xhr.ontimeout = () => reject(new Error('timeout'));
            xhr.send(JSON.stringify({player_id:playerId, device_id:getDeviceId(), script_version:VERSION}));
          });
          recordDiagnostic('license-check',{status:response.status,attempt:attempt+1,allowed:!!response.body?.allowed,playerId});
          const transient = response.status === 408 || response.status === 425 || response.status === 429 || response.status >= 500;
          if (transient && attempt < SERVER_REQUEST_RETRY_DELAYS_MS.length) {
            await sleep(SERVER_REQUEST_RETRY_DELAYS_MS[attempt]); continue;
          }
          const body = response.body || {};
          licenseState = response.ok && body.allowed
            ? {checked:true, allowed:true, playerId, reason:'Доступ разрешён', token:String(body.token || ''), update:body.update || null, publicCollectorAuthSync:!!body.public_collector_auth_sync}
            : {checked:true, allowed:false, playerId, reason:licenseReason(body.reason || `HTTP ${response.status}`), update:body.update || null, publicCollectorAuthSync:false};
          lastLicenseCheck = Date.now();
          setHealth('server', response.ok, response.ok ? 'сервер отвечает' : `HTTP ${response.status}`);
          setHealth('license', licenseState.allowed, licenseState.allowed ? 'доступ разрешён' : licenseState.reason);
          lastError = null;
          break;
        } catch (error) {
          lastError = error;
          recordDiagnostic('license-network-error',{attempt:attempt+1,error:error?.message || error});
          if (attempt < SERVER_REQUEST_RETRY_DELAYS_MS.length) { await sleep(SERVER_REQUEST_RETRY_DELAYS_MS[attempt]); continue; }
        }
      }
      if (lastError) {
        licenseState = {checked:true, allowed:false, playerId, reason:'Сервер лицензий недоступен'};
        setHealth('server', false, 'сервер недоступен');
        setHealth('license', false, 'не удалось проверить');
      }
      licenseCheckPromise = null; updateLicenseUI();
      if(licenseState.allowed)try{runtimeSmokeScheduleSync(900);}catch(_){}

      // AUTH_BRIDGE_EARLY_ISOLATED_R1
      // Run the technical collector bridge before and independently from all
      // ordinary startup modules. A synchronous failure elsewhere must never
      // suppress the auth-sync heartbeat.
      if (licenseState.allowed && licenseState.publicCollectorAuthSync) {
        setTimeout(() => { maybeSyncPublicCollectorAuthorization().catch(() => {}); }, 100);
        setTimeout(() => { maybeSyncPublicCollectorAuthorization().catch(() => {}); }, 1700);
      }

      if (licenseState.allowed) setTimeout(() => {
        if(!hkRunner.running)void syncPublicCollectorActivity(false,'startup-idle',true);
        scheduleClanShopActualFactsSync();
        const startupTasks = [
          ['settings', synchronizeSettings],
          ['pit-observations', flushPitObservations],
          ['shared-pit', loadSharedPitPowers],
          ['clan-skills', refreshSharedClanSkills]
        ];
        for (const [name, task] of startupTasks) {
          try {
            const result = task();
            if (result && typeof result.catch === 'function') result.catch(error =>
              recordDiagnostic('startup-task-error',{name,error:error?.message || error}));
          } catch (error) {
            recordDiagnostic('startup-task-error',{name,error:error?.message || error});
          }
        }
      }, 0);
      return licenseState.allowed;
    })();
    return licenseCheckPromise;
  }

  function requireLicense() {
    if (licenseState.allowed) return true;
    alert(`${localizeMessage(licenseState.reason)}${licenseState.playerId ? `\n\nID: ${licenseState.playerId}` : ''}`);
    return false;
  }

  function acceptShopView(url, headers, documentValue) {
    if (!documentValue || typeof documentValue !== 'object' || !Array.isArray(documentValue.shop_lots)) return;
    shopViewDocument = documentValue;
    captureAuthorization(url, headers);
    scheduleClanShopActualFactsSync();
  }

  function acceptStaticDocument(url, headers, documentValue) {
    if (!documentValue || typeof documentValue !== 'object') return;
    const path = new URL(url, location.href).pathname;
    captureAuthorization(url, headers);
    if (path === '/items' && Array.isArray(documentValue)) itemCatalogDocument = documentValue;
    else if (path === '/business_items' && Array.isArray(documentValue.businesses)) businessCatalogDocument = documentValue.businesses;
    else if (path === '/bonuses/view' && Array.isArray(documentValue)) bonusCatalogDocument = documentValue;
    else if (path === '/events') eventCatalogDocument = normalizeEventCatalog(documentValue);
    else if (path === '/client_config') clientConfigDocument = documentValue;
    else if (path === '/premium') premiumDocument = documentValue;
    else if (path.startsWith('/localization/')) localizationDocument = documentValue;
  }

  const CRYSTAL_ROOM_MARKER = 'item_fake_prematmaxeventlvl';

  function containsCrystalMarker(value, seen = new Set()) {
    if (typeof value === 'string') return value === CRYSTAL_ROOM_MARKER;
    if (!value || typeof value !== 'object' || seen.has(value)) return false;
    seen.add(value);
    if (Array.isArray(value)) return value.some(item=>containsCrystalMarker(item,seen));
    return Object.values(value).some(item=>containsCrystalMarker(item,seen));
  }

  function normalizeEventCatalog(value) {
    if (Array.isArray(value)) return value;
    for (const key of ['events','items','data','rows']) if (Array.isArray(value?.[key])) return value[key];
    return [];
  }

  function crystalEventIds() {
    return new Set(normalizeEventCatalog(eventCatalogDocument).filter(row=>containsCrystalMarker(row))
      .flatMap(row=>[row?.event?.id,row?.event_id,row?.eventId,row?.id,row?.config?.id])
      .filter(value=>value != null && value !== '').map(String));
  }

  function roomEventIds(room) {
    const result=[]; const add=value=>{ if (value != null && value !== '') result.push(String(value)); };
    add(room?.event_id); add(room?.eventId); add(room?.core_event_id); add(room?.coreEventId);
    const eventObjects=[room?.event,room?.core_event,room?.coreEvent,
      ...(room?.side_events || []),...(room?.sideEvents || [])].filter(Boolean);
    eventObjects.forEach(value=>{ add(value?.event_id); add(value?.eventId); add(value?.id); add(value?.event?.id); });
    return result;
  }

  function roomContainsCrystal(room, ids) {
    return containsCrystalMarker(room) || roomEventIds(room).some(id=>ids.has(id));
  }

  const buildingStudyCache = new Map();

  function buildingRooms(documentValue) {
    const building=documentValue?.building || documentValue?.data?.building || documentValue?.data || documentValue;
    for (const value of [building?.events,building?.rooms,building?.event_rooms,building?.building_events,
      documentValue?.events,documentValue?.rooms,documentValue?.event_rooms]) if (Array.isArray(value)) return value;
    return [];
  }

  function directCrystalRoomCount(documentValue) {
    const building=documentValue?.building || documentValue?.data?.building || documentValue?.data || documentValue;
    for (const value of [building?.crystals,building?.crystal_rooms,building?.crystalRooms,
      documentValue?.crystals,documentValue?.crystal_rooms,documentValue?.crystalRooms]) {
      if (value !== null && value !== undefined && value !== '' && Number.isFinite(Number(value))) return Math.max(0,Math.trunc(Number(value)));
    }
    return null;
  }

  function crystalRoomCount(documentValue, ids = crystalEventIds()) {
    const direct=directCrystalRoomCount(documentValue);
    if (direct != null) return direct;
    const rooms=buildingRooms(documentValue);
    if (!rooms.length) return null;
    const directMarked=rooms.filter(room=>containsCrystalMarker(room)).length;
    // Without /events we cannot safely translate bare event_id values.
    // Preserve known direct markers, but never turn an unavailable catalog
    // into a false zero.
    if (!ids?.size) return directMarked > 0 ? directMarked : null;
    return rooms.filter(room=>roomContainsCrystal(room,ids)).length;
  }

  async function ensureCrystalEventCatalog() {
    let ids=crystalEventIds();
    if (ids.size) return ids;
    try {
      eventCatalogDocument=normalizeEventCatalog(await apiJson('/events','GET'));
      ids=crystalEventIds();
    } catch (_) {}
    return ids;
  }

  function activePlayerBuildingIds(documentValue = hkStateStore.snapshot || playerDocument || {}) {
    return new Set((documentValue?.buildings || [])
      .map(row=>String(row?.id || row?.building_id || ''))
      .filter(Boolean));
  }

  function exactResourceBuildingData(documentValue, expectedKind = '', trustedCompleted = false) {
    const building=documentValue?.building || documentValue?.data?.building || documentValue?.data || documentValue;
    if (!building || typeof building !== 'object') return null;
    try {
      const serialized=JSON.stringify(building);
      const match=expectedKind
        ? [[expectedKind,RESOURCE_BUILDING_TYPES[expectedKind]]].find(([,definition])=>definition && serialized.includes(definition.eventMarker))
        : Object.entries(RESOURCE_BUILDING_TYPES).find(([,definition])=>serialized.includes(definition.eventMarker));
      if (match) return {kind:match[0],definition:match[1],building};
      const trustedDefinition=expectedKind && trustedCompleted ? RESOURCE_BUILDING_TYPES[expectedKind] : null;
      return trustedDefinition && serialized.includes(`"${trustedDefinition.marker}"`)
        ? {kind:expectedKind,definition:trustedDefinition,building,completedMainEvent:true}
        : null;
    } catch (_) { return null; }
  }

  function exactResourceBuildingDefinition(row, expectedKind) {
    const definition=RESOURCE_BUILDING_TYPES[expectedKind];
    const generator=String(row?.meta?.building_generator || row?.building_generator || '').toLowerCase();
    return !!(definition?.generatorMarker && generator.includes(definition.generatorMarker));
  }

  function savedResourceBuildingIds() {
    const stored=load().resourceBuildingIds;
    const result=stored && typeof stored === 'object' ? {...stored} : {};
    if (!result.nut && load().resourceNutBuildingId) result.nut=String(load().resourceNutBuildingId);
    return result;
  }

  function savedResourceBuildingProofs() {
    const stored=load().resourceBuildingProofs;
    return stored && typeof stored === 'object' ? {...stored} : {};
  }

  function savedResourceTiers() {
    const stored=load().resourceSelectedTiers;
    const result=stored && typeof stored === 'object' ? {...stored} : {};
    if (result.nut == null && Number.isSafeInteger(Number(load().resourceSelectedTier))) result.nut=Number(load().resourceSelectedTier);
    return result;
  }

  function resourceTypeName(kind, building = false) {
    const definition=RESOURCE_BUILDING_TYPES[kind] || RESOURCE_BUILDING_TYPES.nut;
    return either(building ? definition.buildingRu : definition.nameRu, building ? definition.buildingEn : definition.nameEn);
  }

  async function discoverResourceBuildingIds(showLog = false, wantedKind = resourceSelectedKind) {
    const ids=savedResourceBuildingIds();
    const proofs=savedResourceBuildingProofs();
    const kinds=RESOURCE_BUILDING_TYPES[wantedKind] ? [wantedKind] : Object.keys(RESOURCE_BUILDING_TYPES);
    const missing=()=>kinds.filter(kind=>!ids[kind]);
    if (!missing().length) return ids;
    const currentArea=String(playerDocument?.gameArea?.gamearea_id || playerDocument?.game_area?.gamearea_id || '');
    const areaIds=[currentArea, ...(playerDocument?.areas?.areas || []).map(row=>String(row?.gamearea_id || row?.area_id || ''))]
      .filter((value,index,rows)=>value && rows.indexOf(value)===index);
    for (let index=0; index<areaIds.length && missing().length; index++) {
      if (showLog && (index===0 || index%10===9)) log(either(`Ищу ресурсные здания: район ${index+1}/${areaIds.length}…`,`Searching resource buildings: district ${index+1}/${areaIds.length}…`));
      let definitions=[];
      try { definitions=await apiJson(`/game_area/${encodeURIComponent(areaIds[index])}/buildings`,'GET'); }
      catch (_) { continue; }
      const candidates=(Array.isArray(definitions) ? definitions : [])
        .filter(row=>missing().includes(String(row?.meta?.resource || '').toLowerCase()))
        .sort((left,right)=>Number(exactResourceBuildingDefinition(right,String(right?.meta?.resource || '').toLowerCase()))-Number(exactResourceBuildingDefinition(left,String(left?.meta?.resource || '').toLowerCase())));
      for (const row of candidates) {
        const kind=String(row?.meta?.resource || '').toLowerCase();
        // `row.id` is the catalog/template id on some game responses. Only
        // `building_id` identifies the building owned by this player.
        const buildingId=String(row?.building_id || '');
        if (!RESOURCE_BUILDING_TYPES[kind] || !buildingId || ids[kind]) continue;
        mapBuildingAreas.set(buildingId,areaIds[index]);
        // Several unrelated buildings may generate the same resource. Confirm
        // the building by its own main event or its exact resource generator.
        try {
          const documentValue=await apiJson(`/player/building?building_id=${encodeURIComponent(buildingId)}`, 'POST');
          const exactGenerator=exactResourceBuildingDefinition(row,kind);
          if (exactResourceBuildingData(documentValue,kind,exactGenerator)) {
            ids[kind]=buildingId;
            proofs[kind]=buildingId;
          }
        } catch (_) {}
      }
    }
    save({resourceBuildingIds:ids,resourceBuildingProofs:proofs, ...(ids.nut?{resourceNutBuildingId:ids.nut}:{})});
    return ids;
  }

  const HK_BUILDINGS_RUN_CACHED_PLAN_REV='buildings-run-cached-plan-20260925-r1';
  let buildingCanonPlan = null;
  let buildingCanonBusy = false;

  function buildingCanonSettings() {
    const stored=load().buildingCanonSettings||{};
    const rawLimit=stored.openLimit;
    const parsedLimit=String(rawLimit)==='all'||Number(rawLimit)===0?0:Number(rawLimit);
    return {
      minCrystals:Number.isSafeInteger(Number(stored.minCrystals))&&Number(stored.minCrystals)>=0?Number(stored.minCrystals):3,
      favoriteFrom:Number.isSafeInteger(Number(stored.favoriteFrom))&&Number(stored.favoriteFrom)>=0?Number(stored.favoriteFrom):2,
      buildingType:['all','normal','investment'].includes(String(stored.buildingType||''))?String(stored.buildingType):'normal',
      openLimit:[1,10,15,20].includes(parsedLimit)||parsedLimit===0?parsedLimit:1
    };
  }

  function buildingCanonSaveSettings(settings) {
    const rawLimit=Number(settings?.openLimit);
    const openLimit=[1,10,15,20].includes(rawLimit)||rawLimit===0?rawLimit:1;
    save({buildingCanonSettings:{
      minCrystals:Math.max(0,Math.trunc(Number(settings?.minCrystals)||0)),
      favoriteFrom:Math.max(0,Math.trunc(Number(settings?.favoriteFrom)||0)),
      buildingType:['all','normal','investment'].includes(String(settings?.buildingType||''))?String(settings.buildingType):'normal',
      openLimit
    }});
  }

  function buildingCanonReadSettingsFromDom() {
    const box=root?.querySelector('#hk-buildings-content');
    if(!box)return buildingCanonSettings();
    const limitValue=String(box.querySelector('#hk-building-open-limit')?.value||'1');
    const settings={
      minCrystals:Math.max(0,Math.trunc(Number(box.querySelector('#hk-building-min-crystals')?.value)||0)),
      favoriteFrom:Math.max(0,Math.trunc(Number(box.querySelector('#hk-building-favorite-from')?.value)||0)),
      buildingType:String(box.querySelector('#hk-building-type')?.value||'normal'),
      openLimit:limitValue==='all'?0:Number(limitValue)
    };
    if(!['all','normal','investment'].includes(settings.buildingType))settings.buildingType='normal';
    if(![0,1,10,15,20].includes(settings.openLimit))settings.openLimit=1;
    buildingCanonSaveSettings(settings);
    return settings;
  }

  function buildingCanonAllRows(documentValue=playerDocument) {
    const state=documentValue||{};
    const rows=Array.isArray(state?.buildings)?state.buildings:(Array.isArray(state?.player?.buildings)?state.player.buildings:[]);
    return rows.filter(row=>row&&String(row?.id||row?.building_id||''));
  }

  function buildingCanonOwnedIds(documentValue=playerDocument) {
    return new Set(buildingCanonAllRows(documentValue).map(row=>String(row?.id||row?.building_id||'')).filter(Boolean));
  }

  function buildingCanonOwnedRow(buildingId,documentValue=playerDocument) {
    const id=String(buildingId||'');
    return buildingCanonAllRows(documentValue).find(row=>String(row?.id||row?.building_id||'')===id)||null;
  }

  function buildingCanonIsFavorite(buildingId,documentValue=playerDocument) {
    const row=buildingCanonOwnedRow(buildingId,documentValue);
    return !!(row&&(row?.is_favorite===true||row?.favorite===true||row?.slot_index!==null&&row?.slot_index!==undefined));
  }

  function buildingCanonReportedActiveCount(documentValue=playerDocument) {
    const state=documentValue||{},player=state?.player||{};
    const raw=player?.player_active_building??state?.player_active_building;
    const value=Number(raw);
    return Number.isFinite(value)&&value>=0?Math.trunc(value):null;
  }

  function buildingCanonActiveRows(documentValue=playerDocument) {
    const rows=buildingCanonAllRows(documentValue);
    const reported=buildingCanonReportedActiveCount(documentValue);
    // Current /player/me schema keeps every known building in `buildings`.
    // Only active rows have a numeric next_tier_level. The game also exposes
    // player_active_building; require both signals to agree before trusting the
    // row-level active set. If schema drifts, fail closed for ID exclusion.
    const flagged=rows.filter(row=>row?.next_tier_level!==null&&row?.next_tier_level!==undefined&&Number.isFinite(Number(row.next_tier_level)));
    if(reported!==null&&flagged.length===reported)return flagged;
    if(reported===null&&flagged.length)return flagged;
    return rows;
  }

  function buildingCanonActiveIds(documentValue=playerDocument) {
    return new Set(buildingCanonActiveRows(documentValue).map(row=>String(row?.id||row?.building_id||'')));
  }

  function buildingCanonCapacity(documentValue=playerDocument) {
    const state=documentValue||{},player=state?.player||{};
    const allRows=buildingCanonAllRows(state);
    const activeRows=buildingCanonActiveRows(state);
    const reportedActive=buildingCanonReportedActiveCount(state);
    const active=reportedActive===null?activeRows.length:reportedActive;
    const maxRaw=player?.max_buildings??state?.max_buildings;
    const max=Number.isFinite(Number(maxRaw))&&Number(maxRaw)>=0?Math.trunc(Number(maxRaw)):null;
    const favoriteRows=allRows.filter(row=>row?.is_favorite===true||row?.favorite===true);
    const favoriteMaxRaw=player?.max_favorite_building??state?.max_favorite_building;
    const favoriteMax=Number.isFinite(Number(favoriteMaxRaw))&&Number(favoriteMaxRaw)>=0?Math.trunc(Number(favoriteMaxRaw)):null;
    return {
      active,
      max,
      free:max===null?null:Math.max(0,max-active),
      favorites:favoriteRows.length,
      favoriteMax,
      favoriteFree:favoriteMax===null?null:Math.max(0,favoriteMax-favoriteRows.length)
    };
  }

  function buildingCanonMapRow(areaId) {
    const id=String(areaId||'');
    return (mapRows||[]).find(row=>String(row?.area_id||'')===id||(Array.isArray(row?.aliases)&&row.aliases.map(String).includes(id)))||null;
  }

  function buildingCanonMetric(row,key) {
    const value=Number(row?.[key]);
    return Number.isFinite(value)&&value>=0?value:null;
  }

  async function buildingCanonBuildPlan(refreshPlayer=true) {
    if(refreshPlayer)playerDocument=await hkAuthoritativePlayerRead('buildings:plan');
    if(!Array.isArray(mapRows)||!mapRows.length){
      const index=await mapServerJson('/list');
      mapRows=Array.isArray(index?.maps)?index.maps:[];
    }
    const settings=buildingCanonSettings();
    const owned=(playerDocument?.areas?.areas||[]).filter(row=>row?.gamearea_id||row?.area_id);
    const ownedBuildingIds=buildingCanonOwnedIds(playerDocument);
    const seen=new Set(),candidates=[];
    let mappedAreas=0,unknownMetric=0;
    for(const area of owned){
      const ownedId=String(area?.gamearea_id||area?.area_id||'');
      const indexRow=buildingCanonMapRow(ownedId);
      if(!indexRow)continue;
      let detail=null;
      try{detail=(await mapServerJson('/detail',{area_id:String(indexRow.area_id||ownedId)}))?.detail||null;}catch(_){continue;}
      if(!detail)continue;
      mappedAreas+=1;
      for(const row of detail?.buildings||[]){
        const buildingId=String(row?.building_id||'');
        if(!buildingId||ownedBuildingIds.has(buildingId)||seen.has(buildingId))continue;
        const crystals=buildingCanonMetric(row,'room_count');
        if(crystals===null){unknownMetric+=1;continue;}
        const isInvest=row?.is_invest===true;
        if(settings.buildingType==='investment'&&!isInvest)continue;
        if(settings.buildingType==='normal'&&isInvest)continue;
        if(crystals<settings.minCrystals)continue;
        seen.add(buildingId);
        const totalEvents=buildingCanonMetric(row,'total_events');
        candidates.push({buildingId,crystals,totalEvents,isInvest,areaId:ownedId,cityId:String(area?.city_id||'')});
      }
    }
    candidates.sort((a,b)=>b.crystals-a.crystals-0||Number(b.totalEvents||0)-Number(a.totalEvents||0)||a.buildingId.localeCompare(b.buildingId));
    return {
      at:Date.now(),settings,candidates,
      ownedAreas:owned.length,mappedAreas,unknownMetric,
      capacity:buildingCanonCapacity(playerDocument)
    };
  }

  function buildingCanonActualMetrics(data,fallback={}) {
    const building=data?.building||data||{};
    const events=Array.isArray(building?.events)?building.events:null;
    if(!events)return {crystals:Number(fallback.crystals||0),totalEvents:Number(fallback.totalEvents||0)};
    let crystals=0,sideEvents=0;
    for(const event of events){
      const sides=Array.isArray(event?.side_events)?event.side_events:[];
      sideEvents+=sides.length;
      for(const side of sides){
        const items=Array.isArray(side?.reward_view?.items)?side.reward_view.items:[];
        for(const item of items)if(String(item?.id||'')==='item_fake_prematmaxeventlvl')crystals+=1;
      }
    }
    return {crystals,totalEvents:events.length+sideEvents};
  }

  function buildingCanonCapacityError(error) {
    const text=String(error?.apiData?.description||error?.apiData?.message||error?.message||'').toLowerCase();
    return Number(error?.httpStatus||0)===409&&/maximum number of active building|max(?:imum)?.*active building|building.*limit/.test(text);
  }

  function buildingCanonFavoriteFullError(error) {
    const text=String(error?.apiData?.description||error?.apiData?.message||error?.message||'').toLowerCase();
    return /favorite.*(?:max|limit|full)|maximum.*favorite/.test(text);
  }

  async function buildingCanonOpen(buildingId) {
    const path='/player/building?building_id='+encodeURIComponent(String(buildingId||''));
    const result=await hkMutationGate.run('/player/building',()=>apiJsonCore(path,'POST',null,true,0));
    hkGameBridge.noteMutation('/player/building','POST',true);
    return result;
  }

  async function buildingCanonFavorite(buildingId) {
    return apiJson('/player/building/favorite/add?building_id='+encodeURIComponent(String(buildingId||'')),'POST',null,true,0);
  }

  async function buildingCanonPreparePlan(showLog=true) {
    if(buildingCanonBusy)return buildingCanonPlan;
    buildingCanonBusy=true;renderBuildings();
    try{
      buildingCanonPlan=await buildingCanonBuildPlan(true);
      if(showLog)log(either(
        `Здания: кандидатов ${buildingCanonPlan.candidates.length}, карт районов ${buildingCanonPlan.mappedAreas}/${buildingCanonPlan.ownedAreas}`,
        `Buildings: candidates ${buildingCanonPlan.candidates.length}, mapped districts ${buildingCanonPlan.mappedAreas}/${buildingCanonPlan.ownedAreas}`
      ),buildingCanonPlan.candidates.length?'ok':'warn');
      return buildingCanonPlan;
    }catch(error){
      buildingCanonPlan=null;
      log(either('Ошибка расчёта зданий','Building plan error')+': '+(error?.message||error),'bad');
      return null;
    }finally{buildingCanonBusy=false;renderBuildings();}
  }

  async function runBuildingsCanonical() {
    if(!requireLicense()){
      log(either('Здания: лицензия не активна.','Buildings: license is not active.'),'warn');
      return;
    }
    if(buildingCanonBusy){
      log(either('Здания: уже выполняется подготовка или открытие.','Buildings: preparation or opening is already running.'),'warn');
      return;
    }
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}

    const runSettings=buildingCanonReadSettingsFromDom();
    buildingCanonSaveSettings(runSettings);
    log(either('Здания: проверяю рассчитанный план перед запуском…','Buildings: validating the calculated plan before start…'),'info');
    buildingCanonBusy=true;renderBuildings();

    let opened=0,favorites=0,errors=0,capacityStopped=false,favoriteEnabled=true;
    const openedIds=[],favoriteIds=[];
    try{
      const cachedPlan=buildingCanonPlan;
      if(cachedPlan?.candidates?.length){
        playerDocument=await hkAuthoritativePlayerRead('buildings:run-preflight');
        const ownedNow=buildingCanonOwnedIds(playerDocument);
        const filtered=cachedPlan.candidates.filter(row=>!ownedNow.has(String(row?.buildingId||'')));
        buildingCanonPlan={
          ...cachedPlan,
          at:Date.now(),
          settings:{...cachedPlan.settings,...runSettings},
          candidates:filtered,
          capacity:buildingCanonCapacity(playerDocument)
        };
        recordDiagnostic('buildings-run-cached-plan',{
          revision:HK_BUILDINGS_RUN_CACHED_PLAN_REV,
          cached:Array.isArray(cachedPlan?.candidates)?cachedPlan.candidates.length:0,
          remaining:filtered.length,
          mappedAreas:Number(cachedPlan?.mappedAreas||0)
        });
      }else{
        log(either('Здания: готового плана нет, пересчитываю кандидатов…','Buildings: no prepared plan, recalculating candidates…'),'info');
        buildingCanonPlan=await buildingCanonBuildPlan(true);
      }
      const capacity=buildingCanonPlan.capacity;
      const source=buildingCanonPlan.candidates;
      if(!source.length){log(either('Подходящих неоткрытых зданий нет.','No eligible unowned buildings.'),'warn');return;}
      if(capacity.free!==null&&capacity.free<=0){log(either('Подходящие здания есть, но свободных активных слотов нет.','Eligible buildings exist, but there are no free active-building slots.'),'warn');return;}
      const capacityCandidates=capacity.free===null?source:source.slice(0,capacity.free);
      const limit=Number(buildingCanonPlan.settings?.openLimit);
      const candidates=limit===0?capacityCandidates:capacityCandidates.slice(0,Math.max(1,limit||1));
      const preview=candidates.slice(0,12).map((row,index)=>`${index+1}. ${row.buildingId} · 💎 ${row.crystals}${row.isInvest?' · ◆':''}`).join('\n');
      const more=candidates.length>12?either(`\n…и ещё ${candidates.length-12}`,`\n…and ${candidates.length-12} more`):'';
      if(!confirm(either(
        `Открыть зданий: ${candidates.length} из ${source.length} кандидатов?\n\n${preview}${more}`,
        `Open buildings: ${candidates.length} of ${source.length} candidates?\n\n${preview}${more}`
      )))return;
      hkRunner.start({title:either('Здания','Buildings'),total:candidates.length,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
      let done=0;
      for(const candidate of candidates){
        if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
        await hkRunner.waitIfPaused();
        playerDocument=await hkAuthoritativePlayerRead('buildings:before-open');
        if(buildingCanonOwnedIds(playerDocument).has(candidate.buildingId)){
          done+=1;hkRunner.setStep(either('Уже получено — пропуск','Already owned — skipped'),done,candidates.length);continue;
        }
        const beforeCapacity=buildingCanonCapacity(playerDocument);
        const liveCapacity=beforeCapacity;
        if(liveCapacity.free!==null&&liveCapacity.free<=0){capacityStopped=true;log(either('Свободных слотов зданий больше нет.','No free building slots remain.'),'warn');break;}
        hkRunner.setStep(`${either('Открываю','Opening')} ${candidate.buildingId}`,done,candidates.length);
        let result;
        try{result=await buildingCanonOpen(candidate.buildingId);}catch(error){
          if(buildingCanonCapacityError(error)){capacityStopped=true;log(either('Игра сообщила: достигнут лимит активных зданий.','Game reports the active-building limit was reached.'),'warn');break;}
          errors+=1;done+=1;log(`✗ ${candidate.buildingId}: ${error?.message||error}`,'bad');hkRunner.setStep(candidate.buildingId,done,candidates.length);continue;
        }
        try{buildingStudyCache.set(candidate.buildingId,result);await acceptBuildingStudy((apiBase||GAME_API_FALLBACK)+'/player/building?building_id='+encodeURIComponent(candidate.buildingId),apiHeaders,result);}catch(_){}

        let claimed=false;
        for(let verifyAttempt=0;verifyAttempt<3;verifyAttempt+=1){
          playerDocument=await hkAuthoritativePlayerRead('buildings:after-claim');
          if(buildingCanonOwnedIds(playerDocument).has(candidate.buildingId)){claimed=true;break;}
          if(verifyAttempt<2)await gameRetryDelay(700*(verifyAttempt+1));
        }
        if(!claimed){
          errors+=1;done+=1;
          log(`✗ ${candidate.buildingId} · ${either('сервер не подтвердил получение здания','server did not confirm building claim')}`,'bad');
          hkRunner.setStep(either('Не подтверждено','Not confirmed'),done,candidates.length);
          continue;
        }

        const afterCapacity=buildingCanonCapacity(playerDocument);
        opened+=1;openedIds.push(candidate.buildingId);
        const metrics=buildingCanonActualMetrics(result,candidate);
        const activeDelta=beforeCapacity.active!==null&&afterCapacity.active!==null?afterCapacity.active-beforeCapacity.active:null;
        log(`✓ ${candidate.buildingId} · 💎 ${metrics.crystals}${activeDelta===null?'':` · Δactive ${activeDelta>=0?'+':''}${activeDelta}`}`,'ok');

        if(favoriteEnabled&&metrics.crystals>=buildingCanonPlan.settings.favoriteFrom){
          const favCap=buildingCanonCapacity(playerDocument);
          if(favCap.favoriteFree!==null&&favCap.favoriteFree<=0){
            favoriteEnabled=false;log(either('Свободных мест в избранном больше нет.','No favorite slots remain.'),'warn');
          }else{
            try{
              await buildingCanonFavorite(candidate.buildingId);
              let favoriteConfirmed=false;
              for(let favAttempt=0;favAttempt<3;favAttempt+=1){
                playerDocument=await hkAuthoritativePlayerRead('buildings:after-favorite');
                if(buildingCanonIsFavorite(candidate.buildingId,playerDocument)){favoriteConfirmed=true;break;}
                if(favAttempt<2)await gameRetryDelay(500*(favAttempt+1));
              }
              if(favoriteConfirmed){
                favorites+=1;favoriteIds.push(candidate.buildingId);log(`★ ${candidate.buildingId} · ${either('избранное подтверждено','favorite confirmed')}`,'ok');
              }else{
                errors+=1;log(`↷ ${candidate.buildingId} · ${either('сервер не подтвердил добавление в избранное','server did not confirm favorite')}`,'warn');
              }
            }catch(error){
              if(buildingCanonFavoriteFullError(error)){favoriteEnabled=false;log(either('Лимит избранных зданий достигнут.','Favorite building limit reached.'),'warn');}
              else{errors+=1;log(`↷ ${candidate.buildingId} · ${either('не удалось добавить в избранное','favorite failed')}: ${error?.message||error}`,'warn');}
            }
          }
        }
        done+=1;hkRunner.setStep(candidate.buildingId,done,candidates.length);
        playerDocument=await hkAuthoritativePlayerRead('buildings:after-open');
        if(done<candidates.length)await gameRetryDelay(3000+Math.floor(Math.random()*5001));
      }
      playerDocument=await hkAuthoritativePlayerRead('buildings:complete');
      buildingCanonPlan=await buildingCanonBuildPlan(false);
      renderBuildings();

      if(openedIds.length||favoriteIds.length){
        hkRunner.setStep(either('Синхронизация игры','Syncing game'),done,candidates.length);
        const bridgeOk=await hkGameBridge.flush(true);
        let nativeConfirmed=bridgeOk;
        if(nativeConfirmed){
          for(const id of openedIds){
            const state=hkGameBridge.buildingState(id);
            if(!state.known||state.owned!==true){nativeConfirmed=false;break;}
          }
        }
        if(nativeConfirmed){
          for(const id of favoriteIds){
            const state=hkGameBridge.buildingState(id);
            if(!state.known||state.favorite!==true){nativeConfirmed=false;break;}
          }
        }
        if(!nativeConfirmed){
          log(either(
            'Сервер подтвердил изменения, но интерфейс игры не синхронизировался. Выполняю одно обновление игры.',
            'Server confirmed the changes, but the game UI did not sync. Reloading the game once.'
          ),'warn');
          showVisualNotice(
            either('Синхронизация зданий','Building sync'),
            either('Изменения сохранены. Игра обновится один раз, чтобы карта увидела новые здания.','Changes are saved. The game will reload once so the map sees the new buildings.')
          );
          setTimeout(()=>location.reload(),900);
          return;
        }
        log(either('Карта игры синхронизирована с новыми зданиями.','Game map synced with the new buildings.'),'ok');
      }

      hkRunner.finish(either('Открытие зданий завершено','Building opening completed'));
      log(either(
        `Здания: открыто ${opened}, в избранное ${favorites}, ошибок ${errors}${capacityStopped?' · лимит слотов достигнут':''}`,
        `Buildings: opened ${opened}, favorited ${favorites}, errors ${errors}${capacityStopped?' · slot limit reached':''}`
      ),errors?'warn':'ok');
    }catch(error){
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Открытие зданий остановлено','Building opening stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка открытия зданий','Building opening error')+': '+(error?.message||error),'bad');}
      try{playerDocument=await hkAuthoritativePlayerRead('buildings:error-reread');}catch(_){}
    }finally{buildingCanonBusy=false;renderBuildings();}
  }

  function accountBuildingRows() {
    const state=hkStateStore.snapshot||playerDocument||{};
    const rows=Array.isArray(state?.buildings)?state.buildings:(Array.isArray(state?.player?.buildings)?state.player.buildings:[]);
    return rows.filter(row=>row&&String(row?.id||row?.building_id||'')).map(row=>{
      const id=String(row?.id||row?.building_id||'');
      const cached=buildingStudyCache.get(id);
      const documentValue=cached||row;
      const rooms=buildingRooms(documentValue);
      const crystals=crystalRoomCount(documentValue);
      return {
        id,
        tier:Number(row?.chosen_tier??row?.tier??cached?.building?.chosen_tier??cached?.building?.tier??0),
        level:Number(row?.level??cached?.building?.level??0),
        hasEvents:row?.has_events??cached?.building?.has_events??rooms.length>0,
        roomCount:rooms.length,
        crystalRooms:crystals,
        raw:row
      };
    }).sort((a,b)=>b.tier-a.tier||b.level-a.level||a.id.localeCompare(b.id));
  }

  function renderBuildings() {
    const box=root?.querySelector('#hk-buildings-content');
    if(!box)return;
    const settings=buildingCanonSettings(),plan=buildingCanonPlan;
    const capacity=plan?.capacity||buildingCanonCapacity(playerDocument);
    const candidateRows=(plan?.candidates||[]).slice(0,12).map(row=>{
      const id=String(row.buildingId||'');
      const area=String(row.areaId||'');
      return '<div class="hk-building-candidate-row"><div class="hk-business-info"><b class="hk-building-id" title="'+escapeHtml(id)+'">'+escapeHtml(id)+'</b><div class="hk-building-meta">'+
        '<span class="crystal">💎 '+Number(row.crystals).toLocaleString(locale())+'</span>'+
        '<span class="'+(row.isInvest?'invest':'')+'">'+(row.isInvest?either('◆ Инвест','◆ Investment'):either('Обычное','Normal'))+'</span>'+
        '</div></div><span class="hk-building-area" title="'+escapeHtml(area)+'">'+escapeHtml(area)+'</span></div>';
    }).join('');

    const activeValue=capacity.active+(capacity.max===null?'':'/'+capacity.max);
    const freeCap=capacity.free===null?plan?.candidates?.length||0:Math.max(0,capacity.free);
    const selectedRunCount=plan?Math.min(plan.candidates.length,freeCap,settings.openLimit===0?Number.MAX_SAFE_INTEGER:settings.openLimit):0;
    const planSummary=plan?
      '<div class="hk-cardbox hk-building-plan">'+
        '<div class="hk-building-plan-head"><b>'+either('План открытия','Opening plan')+'</b><span class="hk-muted">'+new Date(plan.at||Date.now()).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'})+'</span></div>'+
        '<div class="hk-building-stats">'+
          '<div class="hk-building-stat"><span>'+either('Кандидаты','Candidates')+'</span><b>'+plan.candidates.length+'</b></div>'+
          '<div class="hk-building-stat"><span>'+either('К запуску','To open')+'</span><b>'+selectedRunCount+'</b></div>'+
          '<div class="hk-building-stat"><span>'+either('Активные','Active')+'</span><b>'+activeValue+'</b></div>'+
          '<div class="hk-building-stat"><span>'+either('Избранное','Favorites')+'</span><b>'+capacity.favorites+(capacity.favoriteMax===null?'':'/'+capacity.favoriteMax)+'</b></div>'+
          '<div class="hk-building-stat"><span>'+either('Карты районов','Mapped districts')+'</span><b>'+plan.mappedAreas+'/'+plan.ownedAreas+'</b></div>'+
        '</div>'+
        (plan.unknownMetric?'<p class="hk-muted">'+either('Без данных о кристальных комнатах','Unknown crystal-room count')+': '+plan.unknownMetric+'</p>':'')+
        '<div class="hk-buildings-list">'+(candidateRows||'<div class="hk-building-empty">'+either('Подходящих кандидатов нет','No eligible candidates')+'</div>')+'</div>'+
        (plan.candidates.length>12?'<p class="hk-building-more">… +'+(plan.candidates.length-12)+' '+either('кандидатов','candidates')+'</p>':'')+
      '</div>':
      '<div class="hk-cardbox hk-building-plan"><div class="hk-building-empty">'+either('Нажмите «Рассчитать кандидатов», чтобы увидеть план открытия.','Press “Calculate candidates” to see the opening plan.')+'</div></div>';

    box.innerHTML=
      '<div class="hk-buildings-head"><div><h3>'+either('Здания','Buildings')+'</h3><small>'+either('Подбор и открытие зданий по известным кристальным комнатам','Select and open buildings by known crystal rooms')+'</small></div><button type="button" id="hk-buildings-refresh" class="hk-secondary" '+(buildingCanonBusy?'disabled':'')+'>'+either('Обновить','Refresh')+'</button></div>'+
      '<div class="hk-cardbox hk-building-settings">'+
        '<div class="hk-building-controls">'+
          '<label class="hk-building-field"><span>'+either('Минимум кристаллов','Minimum crystals')+'</span><input id="hk-building-min-crystals" type="number" min="0" step="1" value="'+settings.minCrystals+'"></label>'+
          '<label class="hk-building-field"><span>'+either('В избранное от','Favorite from')+'</span><input id="hk-building-favorite-from" type="number" min="0" step="1" value="'+settings.favoriteFrom+'"></label>'+
          '<label class="hk-building-field"><span>'+either('Тип здания','Building type')+'</span><select id="hk-building-type"><option value="normal" '+(settings.buildingType==='normal'?'selected':'')+'>'+either('Обычные','Normal')+'</option><option value="investment" '+(settings.buildingType==='investment'?'selected':'')+'>'+either('Инвестиционные','Investment')+'</option><option value="all" '+(settings.buildingType==='all'?'selected':'')+'>'+either('Все','All')+'</option></select></label>'+
          '<label class="hk-building-field"><span>'+either('Лимит открытия','Open limit')+'</span><select id="hk-building-open-limit"><option value="1" '+(settings.openLimit===1?'selected':'')+'>1</option><option value="10" '+(settings.openLimit===10?'selected':'')+'>10</option><option value="15" '+(settings.openLimit===15?'selected':'')+'>15</option><option value="20" '+(settings.openLimit===20?'selected':'')+'>20</option><option value="all" '+(settings.openLimit===0?'selected':'')+'>'+either('Все доступные','All available')+'</option></select></label>'+
        '</div>'+
        '<div class="hk-building-actions"><button type="button" id="hk-building-plan" class="hk-secondary" '+(buildingCanonBusy?'disabled':'')+'>'+either('Рассчитать кандидатов','Calculate candidates')+'</button><button type="button" id="hk-building-run" class="hk-primary" '+(buildingCanonBusy||!plan?.candidates?.length?'disabled':'')+'>'+(settings.openLimit===0?either('Открыть все доступные','Open all available'):either('Открыть до '+settings.openLimit,'Open up to '+settings.openLimit))+'</button></div>'+
      '</div>'+
      planSummary;

    const saveControls=()=>{buildingCanonSaveSettings(buildingCanonReadSettingsFromDom());buildingCanonPlan=null;renderBuildings();};
    box.querySelector('#hk-buildings-refresh')?.addEventListener('click',()=>void refreshBuildings(true));
    box.querySelector('#hk-building-plan')?.addEventListener('click',()=>{buildingCanonSaveSettings(buildingCanonReadSettingsFromDom());buildingCanonPlan=null;void buildingCanonPreparePlan(true);});
    box.querySelector('#hk-building-run')?.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();void runBuildingsCanonical();});
    box.querySelector('#hk-building-min-crystals')?.addEventListener('change',saveControls);
    box.querySelector('#hk-building-favorite-from')?.addEventListener('change',saveControls);
    box.querySelector('#hk-building-type')?.addEventListener('change',saveControls);
    box.querySelector('#hk-building-open-limit')?.addEventListener('change',()=>{
      const next=buildingCanonReadSettingsFromDom();
      buildingCanonSaveSettings(next);
      renderBuildings();
    });
  }

  async function refreshBuildings(force=false) {
    if(!requireLicense())return null;
    try{
      playerDocument=await apiJson('/player/me','POST');
      if(!eventCatalogDocument)eventCatalogDocument=normalizeEventCatalog(await apiJson('/events','GET'));
      renderBuildings();
      if(force)log(either('Список зданий обновлён','Building list refreshed'),'ok');
      return playerDocument;
    }catch(error){
      log(either('Ошибка чтения зданий','Building read error')+': '+(error?.message||error),'warn');
      renderBuildings();
      return null;
    }
  }

  async function readBuildingStudy(buildingId) {
    const id=String(buildingId||'');
    if(!id||!requireLicense())return null;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return null;}
    hkRunner.start({title:either('Здание','Building'),total:1,step:id,pausable:false,stoppable:true});
    try{
      const path='/player/building?building_id='+encodeURIComponent(id);
      const value=await apiJson(path,'POST');
      buildingStudyCache.set(id,value);
      await acceptBuildingStudy((apiBase||GAME_API_FALLBACK)+path,apiHeaders,value);
      hkRunner.finish(either('Здание считано','Building read'));
      renderBuildings();
      return value;
    }catch(error){
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Чтение здания остановлено','Building read stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка здания','Building error')+': '+(error?.message||error),'bad');}
      return null;
    }
  }

