          hkRunner.setStep(either('Автобой','Auto battle')+' · '+before+'/'+Number(current?.max_battle_level||0),0,1);const res=await exploreE3Mutation('/player/battle/fast',{building_id:buildingId},buildingId,'explore:e3-auto-battle');current=res.building||current;
          if(Number(current?.battle_level||0)>before){if(Number(current?.battle_level||0)>=Number(current?.max_battle_level||0))exploreE3Stage('battles',either('Бои','Battles'),'done',Number(current?.battle_level||0)+'/'+Number(current?.max_battle_level||0));else exploreE3Stage('battles',either('Бои','Battles'),'running',Number(current?.battle_level||0)+'/'+Number(current?.max_battle_level||0));await exploreE3Delay(settings,'battle');continue;}
