  async function runExploreE3Single(){
    if(!requireLicense()||exploreBusy||hkRunner.running)return;const settings=exploreReadSettings();exploreBusy=true;exploreE3ShopLots=null;renderExplore();
    try{
      explorePlan=await exploreBuildPlan();const total=Number(explorePlan?.selected?.length||0);if(!total){log(either('Нет зданий для запуска','No buildings to run'),'warn');return;}
      const candidate=explorePlan.selected[0],ok=confirm(either('E3: обработать 1 тестовое здание из '+total+'? После успешной проверки включим очередь.','E3: process 1 test building out of '+total+'? The queue will be enabled after a successful check.'));
      if(!ok)return;
      hkRunner.start({title:either('Исследование · E3','Explore · E3'),total:1,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
      exploreE3InitStages(candidate,total);
      const result=await exploreE3ProcessOne(candidate,settings);
      exploreE3Stage('verify',either('Финальная проверка','Final verification'),'running');
      await exploreE3Reconcile(String(candidate.id||''),'explore:e3-final');
      if(result.status==='completed'){exploreE3Stage('verify',either('Финальная проверка','Final verification'),'done',either('состояние подтверждено','state confirmed'));hkRunner.advance(either('Здание завершено','Building completed'));hkRunner.finish(either('E3 завершён','E3 completed'));log(either('E3: одно здание успешно обработано','E3: one building processed successfully'),'ok');}
      else{const msg=(result.reason||result.status),st=result.status==='skipped'||result.status==='resources_exhausted'?'skipped':'error';exploreE3CloseRunning(st,msg);exploreE3Stage('verify',either('Финальная проверка','Final verification'),st,msg);hkRunner.fail(new Error(msg));log(either('E3 остановлен: ','E3 stopped: ')+msg,'warn');}
      exploreMeta=await exploreLoadMeta(true,exploreState());explorePlan=null;
    }catch(e){if(e?.name==='AbortError'){exploreE3CloseRunning('skipped',either('остановлено пользователем','stopped by user'));exploreE3Stage('verify',either('Финальная проверка','Final verification'),'skipped',either('остановлено','stopped'));hkRunner.fail(new Error(either('Остановлено пользователем','Stopped by user')));log(either('E3 остановлен пользователем','E3 stopped by user'),'warn');}else{exploreE3CloseRunning('error',e?.message||String(e));exploreE3Stage('verify',either('Финальная проверка','Final verification'),'error',e?.message||String(e));hkRunner.fail(e);log(either('Ошибка E3: ','E3 error: ')+(e?.message||e),'bad');}}
    finally{exploreBusy=false;renderExplore();}
  }

  async function runExploreE4Queue(){
    if(!requireLicense()||exploreBusy||hkRunner.running)return;
    const settings=exploreReadSettings();
    exploreBusy=true;exploreE3ShopLots=null;renderExplore();
    try{
      explorePlan=await exploreBuildPlan();
      const source=Array.isArray(explorePlan?.selected)?explorePlan.selected:[];
      if(!source.length){log(either('Нет зданий для очереди E4','No buildings for the E4 queue'),'warn');return;}
      const queue=source;
      const ok=confirm(either(
        'Обработать '+queue.length+' выбранных зданий последовательно?',
        'Process '+queue.length+' selected buildings sequentially?'
      ));
      if(!ok)return;

      hkRunner.start({title:either('Исследование','Explore'),total:queue.length,step:either('Подготовка очереди','Preparing queue'),pausable:true,stoppable:true});
      let completed=0,skipped=0,failed='';
      for(let i=0;i<queue.length;i++){
        await hkRunner.waitIfPaused();
        const candidate=queue[i];
        hkRunner.setStep(either('Здание ','Building ')+(i+1)+'/'+queue.length,i,queue.length);
        hkRunner.state.history=[];
        exploreE3InitStages(candidate,queue.length,i+1);

        const result=await exploreE3ProcessOne(candidate,settings);
        exploreE3Stage('verify',either('Финальная проверка','Final verification'),'running');
        await exploreE3Reconcile(String(candidate.id||''),'explore:e4-final-'+(i+1));

        if(result.status==='completed'){
          completed++;
          exploreE3Stage('verify',either('Финальная проверка','Final verification'),'done',either('состояние подтверждено','state confirmed'));
          hkRunner.advance(either('Здание ','Building ')+(i+1)+'/'+queue.length+' · '+either('готово','done'));
        }else if(result.status==='skipped'){
          skipped++;
          const msg=result.reason||either('пропущено','skipped');
          exploreE3CloseRunning('skipped',msg);
          exploreE3Stage('verify',either('Финальная проверка','Final verification'),'skipped',msg);
          hkRunner.advance(either('Здание ','Building ')+(i+1)+'/'+queue.length+' · '+either('пропущено','skipped'));
          log(either('Здание пропущено: ','Building skipped: ')+msg,'warn');
        }else{
          failed=result.reason||result.status||either('Неизвестная ошибка','Unknown error');
          const st=result.status==='resources_exhausted'?'skipped':'error';
          exploreE3CloseRunning(st,failed);
          exploreE3Stage('verify',either('Финальная проверка','Final verification'),st,failed);
          break;
        }

        if(i<queue.length-1)await exploreE4BetweenDelay(settings);
      }

      exploreMeta=await exploreLoadMeta(true,exploreState());
      explorePlan=null;

      if(failed){
        hkRunner.fail(new Error(failed));
        log(either('Исследование остановлено: ','Explore stopped: ')+failed,'warn');
      }else{
        hkRunner.finish(either('Исследование завершено','Explore completed')+' · '+completed+' '+either('готово','done')+(skipped?' · '+skipped+' '+either('пропущено','skipped'):''));
        log(either('Очередь исследования завершена','Explore queue completed')+' · '+completed+'/'+queue.length,'ok');
      }
    }catch(e){
      if(e?.name==='AbortError'){
        exploreE3CloseRunning('skipped',either('остановлено пользователем','stopped by user'));
        exploreE3Stage('verify',either('Финальная проверка','Final verification'),'skipped',either('остановлено','stopped'));
        hkRunner.fail(new Error(either('Остановлено пользователем','Stopped by user')));
        log(either('Исследование остановлено пользователем','Explore stopped by user'),'warn');
      }else{
        exploreE3CloseRunning('error',e?.message||String(e));
        exploreE3Stage('verify',either('Финальная проверка','Final verification'),'error',e?.message||String(e));
        hkRunner.fail(e);
        log(either('Ошибка исследования: ','Explore error: ')+(e?.message||e),'bad');
      }
    }finally{
      exploreBusy=false;
      renderExplore();
    }
  }

  function explorePrOptions(v){return [['min',either('Минимум сначала','Minimum first')],['max',either('Максимум сначала','Maximum first')],['any',either('Любой порядок','Any order')]].map(r=>'<option value="'+r[0]+'" '+(v===r[0]?'selected':'')+'>'+r[1]+'</option>').join('');}
  function exploreDistrictOptions(v){return ['<option value="all">'+either('Все районы','All districts')+'</option>'].concat((exploreMeta?.districts||[]).map(r=>'<option value="'+escapeHtml(r.areaId)+'" '+(String(v)===String(r.areaId)?'selected':'')+'>'+escapeHtml(r.label)+'</option>')).join('');}

