  function bossCanonReadRunConfigs(){
    if(!bossCanonState.loaded)return[];const result=[];
    for(const kind of ['area','regional']){const row=bossCanonState[kind],selected=kind==='area'?bossCanonSelectedArea():bossCanonSelectedRegional(),plan=bossCanonSelectedPlan(kind);if(!row.enabled||!selected||!plan||plan.affordable===false)continue;const target=kind==='area'&&bossCanonWhole(row.targetLevel)>0?bossCanonTargetPlan(row.targetLevel,{basePlan:plan}):null;if(target&&!target.valid)continue;result.push({kind,bossLevel:kind==='area'?Number(row.bossLevel):undefined,bossId:kind==='regional'?String(row.bossId):undefined,planId:plan.id,total:plan.total,executionTotal:bossCanonWhole(plan.total)+bossCanonWhole(target?.scheduledNow),steps:plan.steps.map(step=>({...step})),paymentMode:plan.paymentMode,crystalBudget:plan.crystalCost,itemPassBudget:plan.itemCost,freePasses:plan.freePasses,paidPasses:plan.paidPasses,maxRestoration:Math.min(bossCanonWhole(row.maxRestoration),bossCanonResource(playerDocument,HK_BOSS_RESTORATION_ITEM_ID,'item')),autofinish:!!row.autofinish,passCost:kind==='regional'?bossCanonRetryCost('regional'):null,targetLevel:bossCanonWhole(target?.level),targetScore:bossCanonWhole(target?.targetScore),targetStrategy:target?target.strategy:'last_day',targetRequestedNow:bossCanonWhole(target?.requestedNow),targetScheduledNow:bossCanonWhole(target?.scheduledNow),targetRequiredExtra:bossCanonWhole(target?.requiredExtraAttempts),targetProjectedFinal:bossCanonWhole(target?.projectedFinal)});}
    return result;
  }
  async function runBossesCanonical(){
    if(!requireLicense())return;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}
    const configs=bossCanonReadRunConfigs();
    if(!configs.length){alert(either('Выберите хотя бы одного босса','Select at least one boss'));return;}
    const progress={done:0,total:configs.reduce((sum,row)=>sum+Math.max(1,bossCanonWhole(row.executionTotal??row.total)),0)};
    const crystals=configs.reduce((sum,row)=>sum+bossCanonWhole(row.crystalBudget),0);
    const items=configs.reduce((sum,row)=>sum+bossCanonWhole(row.itemPassBudget),0);
    const paws=configs.reduce((sum,row)=>sum+(bossCanonWhole(row.maxRestoration)*Math.max(1,bossCanonWhole(row.executionTotal??row.total))),0);
    const preview=configs.map((row,index)=>{
      const label=row.kind==='area'
        ? either('Босс района','Area Boss')+' · Lv '+bossCanonWhole(row.bossLevel)
        : either('Региональный босс','Regional Boss')+' · '+String(row.bossId||'');
      return (index+1)+'. '+label+' · '+either('план','plan')+': '+String(row.planId||'')+' · '+either('проходов','runs')+': '+Math.max(1,bossCanonWhole(row.executionTotal??row.total));
    }).join('\n');
    if(!confirm(either(
      'Запустить выбранных Боссов?\n\n'+preview+'\n\nМаксимальный плановый расход: 💎 '+crystals+' · 🎟 '+items+' · 🐾 '+paws+'\n\nПеред расходом план и live-цены будут проверены повторно.',
      'Start selected Bosses?\n\n'+preview+'\n\nMaximum planned spend: 💎 '+crystals+' · 🎟 '+items+' · 🐾 '+paws+'\n\nThe plan and live prices will be revalidated before spending.'
    )))return;
    hkRunner.start({title:either('Боссы','Bosses'),step:either('Подготовка','Preparing'),total:progress.total,pausable:true,stoppable:true});
    bossCanonDecisionReset();log(either('Боссы — запуск выбранного плана','Bosses — starting selected plan'),'info');recordDiagnostic('bosses-run-config-snapshot',{revision:HK_BOSSES_CANON_REV,configs});
    try{for(const config of configs){if(config.kind==='area')await bossCanonRunArea(config,progress);else await bossCanonRunRegional(config,progress);}playerDocument=await hkAuthoritativePlayerRead('bosses:complete');await bossCanonLoadData();renderBosses();hkRunner.finish(either('Боссы завершены','Bosses completed'));log(either('Выбранные бои боссов завершены','Selected boss battles completed'),'ok');}
    catch(error){if(error?.name==='AbortError'){hkRunner.reset();log(either('Боссы остановлены пользователем','Bosses stopped by user'),'warn');}else{hkRunner.fail(error);log(`${either('Ошибка Боссов','Bosses error')}: ${error?.message||error}`,'bad');}try{await bossCanonLoadData();renderBosses();}catch(_){}}
    finally{bossCanonDecisionReset();}
  }

  function bossCanonPlanMeta(kind,plan){if(!plan)return'';const free=bossCanonFreePasses(kind),retry=bossCanonRetryCost(kind),primary=kind==='area'?HK_BOSS_AREA_TOKEN_ITEM_ID:HK_BOSS_REGIONAL_TOKEN_ITEM_ID;return `<div class="hk-muted" style="margin-top:6px">${either('Доступно бесплатных проходов','Free passes available')}: <b>${free}</b>${retry?` · ${either('стоимость одного','cost per pass')}: ${retry}`:''} · 🎟 ${bossCanonResource(playerDocument,primary,'item')} · 💎 ${bossCanonResource(playerDocument,'cur_prem','currency')}</div>`;}
  function bossCanonTargetUi(){
    const row=bossCanonState.area,levels=bossCanonTargetLevels(),level=bossCanonWhole(row.targetLevel),plan=level?bossCanonTargetPlan(level):null,current=bossCanonWhole(bossCanonState.areaProgress?.score),options=['<option value="0">'+either('Без цели награды','No reward target')+'</option>',...levels.map(x=>`<option value="${x.level}"${x.level===level?' selected':''}>${either('Ур.','Lv')} ${x.level} · ${x.score.toLocaleString(locale())} BP XP</option>`)].join(''),strategy=bossCanonTargetStrategy(row.targetStrategy),strategyOptions=[['upfront',either('Сразу','Upfront')],['gradual',either('Постепенно','Gradual')],['last_day',either('В последний день','Last day')]].map(([v,t])=>`<option value="${v}"${strategy===v?' selected':''}>${t}</option>`).join('');
    const stats=plan?`<div class="hk-boss-target-stats"><span>${either('Сейчас','Current')}: <b>${current.toLocaleString(locale())}</b></span><span>${either('За попытку','Per attempt')}: <b>${plan.pointsPerAttempt.toLocaleString(locale())}</b></span><span>${either('Доп. сейчас','Extra now')}: <b>${plan.scheduledNow}</b></span><span>${either('Прогноз','Projected')}: <b>${plan.projectedFinal.toLocaleString(locale())}</b></span><span>${either('Достижимый уровень','Reach level')}: <b>${plan.maxReachLevel||'—'}</b></span><span>${either('Статус','Status')}: <b>${plan.valid?either('достижимо','reachable'):either('не подтверждено','not confirmed')}</b></span></div>`:'';
    return `<details class="hk-pit-reward-block" ${level?'open':''}><summary><span>${either('Турнирная цель Area Boss','Area Boss tournament target')}</span><b class="${level?'active':''}">${level?`${either('Ур.','Lv')} ${level}`:either('выкл.','off')}</b></summary><div class="hk-pit-reward-body"><div class="hk-pit-reward-controls"><label><span>${either('Целевой уровень','Target level')}</span><select data-boss-target-level="area">${options}</select></label><label><span>${either('Стратегия','Strategy')}</span><select data-boss-target-strategy="area">${strategyOptions}</select></label><label><span>${either('Базовых попыток в день','Daily base runs')}</span><input data-boss-daily-base-runs="area" type="number" min="0" value="${bossCanonDailyBaseRuns()}"></label></div>${stats}<small class="hk-pit-reward-note">${either('После каждого завершённого раунда очки и оставшийся план пересчитываются по live battle pass.','After every completed round, live battle-pass score and remaining plan are recalculated.')}</small></div></details>`;
  }
  function bossCanonSection(kind){
    const area=kind==='area',row=bossCanonState[kind],selected=area?bossCanonSelectedArea():bossCanonSelectedRegional(),plans=bossCanonBuildPlans(kind),plan=bossCanonSelectedPlan(kind),paws=bossCanonResource(playerDocument,HK_BOSS_RESTORATION_ITEM_ID,'item');
    const options=(area?bossCanonState.areaBosses:bossCanonState.regionalBosses).map(item=>area?`<option value="${item.level}"${String(item.level)===String(row.bossLevel)?' selected':''}>${escapeHtml(`${either('Уровень','Level')} ${item.level} · ${item.points} ${either('очк.','pts')} · ${item.boxes} 📦 · ${Number(item.winrate||0).toFixed(2)}%`)}</option>`:`<option value="${escapeHtml(item.id)}"${String(item.id)===String(row.bossId)?' selected':''}>${escapeHtml(bossCanonRegionalName(item))}</option>`).join('');
    const planOptions=plans.map(item=>`<option value="${escapeHtml(item.id)}"${item.id===row.planId?' selected':''}${item.affordable===false?' disabled':''}>${escapeHtml(bossCanonPlanLabel(kind,item))}</option>`).join('');
    const title=area?either('Боссы районов','Area Bosses'):either('Региональные боссы','Regional Bosses');
    return `<section class="hk-cardbox"><div class="hk-clan-head"><div><h3>${title}</h3><small>${area?either('Повторные бои по доступным уровням','Replay unlocked Area Boss levels'):either('Повторные Beast Boss бои','Replay defeated Beast Bosses')}</small></div><label style="display:flex;align-items:center;gap:6px"><input data-boss-canon-enable="${kind}" type="checkbox" ${row.enabled?'checked':''}> ${either('Запускать','Run')}</label></div>${options?`<div class="hk-grid"><span>${either('Босс','Boss')}</span><select data-boss-canon-select="${kind}">${options}</select><span>${either('План проходов','Pass plan')}</span><select data-boss-canon-plan="${kind}">${planOptions}</select><span>${either('Максимум Лап восстановления','Max Restoration Paws')}</span><input data-boss-canon-paws="${kind}" type="number" min="0" max="${paws}" value="${Math.min(row.maxRestoration,paws)}"><span>${either('Автозавершение','Auto finish')}</span><input data-boss-canon-autofinish="${kind}" type="checkbox" ${row.autofinish?'checked':''}></div>${bossCanonPlanMeta(kind,plan)}${area?bossCanonTargetUi():''}`:`<p class="hk-muted">${area?either('Нет доступных повторных Area Boss боёв.','No unlocked Area Boss replays available.'):either('Нет доступных повторных региональных боссов.','No regional boss replays available.')}</p>`}</section>`;
  }
  function renderBosses(){
    const box=root?.querySelector('#hk-boss-content');if(!box)return;if(!bossCanonState.loaded){box.innerHTML=`<p class="hk-muted">${either('Загрузка Боссов…','Loading Bosses…')}</p>`;return;}bossCanonClamp();const configs=bossCanonReadRunConfigs();box.innerHTML=`<div class="hk-clan-head"><div><h3>${either('Боссы','Bosses')}</h3><small>${either('Канонический Area + Regional runner','Canonical Area + Regional runner')} · ${HK_BOSSES_CANON_REV} · ${HK_BOSSES_TARGET_REV}</small></div><button id="hk-boss-refresh" class="hk-secondary">${either('Обновить','Refresh')}</button></div><div class="hk-muted" style="margin:4px 0 10px">🐾 ${bossCanonResource(playerDocument,HK_BOSS_RESTORATION_ITEM_ID,'item')} · ${bossLastReadAt?either('обновлено','updated')+' '+new Date(bossLastReadAt).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'}):''}</div>${bossCanonSection('area')}${bossCanonSection('regional')}<button id="hk-boss-start" class="hk-primary" ${configs.length?'':'disabled'}>${either('Запустить выбранных Боссов','Start selected Bosses')}</button>`;
    box.querySelector('#hk-boss-refresh')?.addEventListener('click',()=>void refreshBosses(true));box.querySelector('#hk-boss-start')?.addEventListener('click',()=>void runBossesCanonical());
    box.querySelectorAll('[data-boss-canon-enable],[data-boss-canon-plan],[data-boss-canon-paws],[data-boss-canon-autofinish]').forEach(control=>control.onchange=()=>{const kind=String(control.dataset.bossCanonEnable||control.dataset.bossCanonPlan||control.dataset.bossCanonPaws||control.dataset.bossCanonAutofinish||'');if(!['area','regional'].includes(kind))return;const row=bossCanonState[kind];if(control.dataset.bossCanonEnable!==undefined)row.enabled=!!control.checked;else if(control.dataset.bossCanonPlan!==undefined)row.planId=String(control.value||'');else if(control.dataset.bossCanonPaws!==undefined)row.maxRestoration=Math.min(bossCanonWhole(control.value),bossCanonResource(playerDocument,HK_BOSS_RESTORATION_ITEM_ID,'item'));else row.autofinish=!!control.checked;bossCanonClamp();bossCanonSave();renderBosses();});
    box.querySelectorAll('[data-boss-canon-select]').forEach(control=>control.onchange=async()=>{const kind=String(control.dataset.bossCanonSelect||'');if(kind==='area'){bossCanonState.area.bossLevel=String(control.value||'');bossCanonState.area.planId='';bossCanonClamp();bossCanonSave();renderBosses();return;}bossCanonState.regional.bossId=String(control.value||'');bossCanonState.regional.planId='';bossCanonSave();renderBosses();try{await bossCanonLoadRegionalState();bossCanonClamp();bossCanonSave();renderBosses();}catch(error){log(either('Ошибка чтения Regional Boss','Regional Boss read error')+': '+(error?.message||error),'warn');}});
    box.querySelectorAll('[data-boss-target-level],[data-boss-target-strategy],[data-boss-daily-base-runs]').forEach(control=>control.onchange=()=>{if(control.dataset.bossTargetLevel!==undefined){bossCanonState.area.targetLevel=bossCanonWhole(control.value);if(bossCanonState.area.targetLevel>0&&bossCanonState.area.planId==='')bossCanonState.area.planId='reward-0';}else if(control.dataset.bossTargetStrategy!==undefined)bossCanonState.area.targetStrategy=bossCanonTargetStrategy(control.value);else bossCanonState.area.dailyBaseRuns=bossCanonWhole(control.value);bossCanonClamp();bossCanonSave();renderBosses();});
  }
  async function refreshBosses(force=false){
    if(!requireLicense())return null;try{await bossCanonLoadData();renderBosses();if(force)log(either('Данные боссов обновлены','Boss data refreshed'),'ok');return playerDocument;}catch(error){log(either('Ошибка чтения боссов','Boss read error')+': '+(error?.message||error),'warn');renderBosses();return null;}
  }

            function warHpHtml(current,maximum,side='our') {
    const currentValue=Number(current), maximumValue=Number(maximum);
    const hasCurrent=Number.isFinite(currentValue)&&currentValue>=0;
    const hasMaximum=Number.isFinite(maximumValue)&&maximumValue>0;
    if(!hasCurrent&&!hasMaximum)return '';
    const safeCurrent=hasCurrent?Math.max(0,currentValue):0;
    const safeMaximum=hasMaximum?Math.max(1,maximumValue):0;
    const percent=hasMaximum?Math.max(0,Math.min(100,Math.round(safeCurrent/safeMaximum*100))):null;
    const label=hasMaximum
      ? safeCurrent.toLocaleString(locale())+' / '+safeMaximum.toLocaleString(locale())+' HP'+(percent===null?'':' · '+percent+'%')
      : safeCurrent.toLocaleString(locale())+' HP';
    return '<div class="hk-war-hp '+(side==='enemy'?'enemy':'our')+'"><small>'+escapeHtml(label)+'</small>'+
      (hasMaximum?'<span><i style="width:'+percent+'%"></i></span>':'')+'</div>';
  }


  function warCombatSaved() {
    const value=load().warCombat;
    return value&&typeof value==='object'?value:{};
  }

  function warCombatSave() {
    save({warCombat:{planId:String(warCombat.planId||'')}});
  }

  async function warFetchActiveBattles() {
    return apiJson('/clan/active_battles','GET',null,true,1);
  }

  async function warFetchAttackCost() {
    return apiJson('/alliance_war/attack_cost','GET',null,true,1);
  }

  async function warFetchOpponents() {
    const data=await apiJson('/alliance_war/get_opponents','GET',null,true,1);
    return Array.isArray(data?.opponents)?data.opponents.filter(row=>String(row?.id||'')):[];
  }

  function warOpponentPower(row) { return Math.max(0,pitCanonWhole(row?.power)); }
  function warOpponentFatigue(row) { return Math.max(0,Math.min(99,Number(row?.fatigue)||0)); }
  function warOpponentEffectivePower(row) {
    return Math.max(0,Math.round(warOpponentPower(row)*((100-warOpponentFatigue(row))/100)));
  }
  function warWeakestOpponent(rows) {
    return [...(rows||[])].sort((a,b)=>{
      const effective=warOpponentEffectivePower(a)-warOpponentEffectivePower(b);if(effective)return effective;
      const fatigue=warOpponentFatigue(b)-warOpponentFatigue(a);if(fatigue)return fatigue;
      const power=warOpponentPower(a)-warOpponentPower(b);if(power)return power;
      return String(a?.id||'').localeCompare(String(b?.id||''));
    })[0]||null;
  }

  function warCrystalRefillCost(data) {
    const value=pitCanonCostQuantity(data?.attack_pass_buy_costs?.prem_costs,'cur_prem','currency');
    return value===null?0:pitCanonWhole(value);
  }

  function warItemRefillCost(data) {
    const value=pitCanonCostQuantity(data?.attack_pass_buy_costs?.item_costs,WAR_PASS_ITEM_ID,'item');
    return value===null?0:pitCanonWhole(value);
  }

  function warBuildPlans(available,attackCost) {
    available=pitCanonWhole(available);
    const freeSteps=Array.from({length:available},()=>({chunk:1,payment:'FREE',cost:0}));
    const plans=[];
    if(available>0)plans.push({id:'free-exact',kind:'exact',total:available,freePasses:available,paidPasses:0,paymentMode:'FREE',steps:freeSteps.map(step=>({...step})),crystalCost:0,itemCost:0});
    const crystalCost=warCrystalRefillCost(attackCost);
    if(crystalCost>0)plans.push({id:'free-plus-prem-1',kind:'direct',total:available+1,freePasses:available,paidPasses:1,paymentMode:'PREM',steps:[...freeSteps.map(step=>({...step})),{chunk:1,payment:'PREM',cost:crystalCost}],crystalCost,itemCost:0});
    return plans;
  }

  function warPlanLabel(plan) {
    if(!plan)return either('Нет доступного плана','No available plan');
    if(plan.paymentMode==='PREM'){
      const parts=[];
      if(pitCanonWhole(plan.freePasses)>0)parts.push(either('бесплатно','free')+' '+pitCanonWhole(plan.freePasses));
      parts.push(either('платный','paid')+' '+pitCanonWhole(plan.paidPasses));
      return parts.join(' + ')+' — 💎 '+pitCanonWhole(plan.crystalCost).toLocaleString(locale());
    }
    return either('Точно по бесплатным пропускам','Exact free passes')+' — '+pitCanonWhole(plan.total).toLocaleString(locale());
  }

  function warSelectedPlan() {
    return warCombat.plans.find(plan=>plan.id===warCombat.planId)||null;
  }

  function warAcceptResponse(response,reason='war-combat') {
    if(response&&typeof response==='object'){
      try{hkStateStore.merge(response,reason);}catch(_){}
      playerDocument=hkStateStore.snapshot||playerDocument;
      if(response?.alliance_attack_war&&typeof response.alliance_attack_war==='object')warCombat.activeWar=response.alliance_attack_war;
    }
    const smokeWar=response?.alliance_attack_war||warCombat.activeWar||null;
    hkRuntimeSmokeRecord('war-state',{
      reason,
      responseKeys:hkSmokeObjectKeys(response),
      hasWar:!!smokeWar,
      health:Number(smokeWar?.health??0),
      initialHealth:Number(smokeWar?.initial_health??0),
      battleWin:response?.battle_result?.is_win===true?true:response?.battle_result?.is_win===false?false:null,
      previewRounds:Array.isArray(response?.pvp_preview?.rounds)?response.pvp_preview.rounds.length:0
    });
    return response;
  }

  function warWinrateSummary(response) {
    const rates=(response?.pvp_preview?.rounds||[]).map(row=>Number(row?.winrate)).filter(Number.isFinite);
    if(!rates.length)return '';
    const min=Math.min(...rates),max=Math.max(...rates),avg=rates.reduce((sum,value)=>sum+value,0)/rates.length;
    return min===max?Math.round(avg)+'%':Math.round(min)+'–'+Math.round(max)+'% · '+either('ср.','avg')+' '+avg.toFixed(1)+'%';
  }

  async function loadWarCombat(force=false) {
    if(!requireLicense())return null;
    playerDocument=await hkAuthoritativePlayerRead(force?'wars:refresh':'wars:load');
    const activeBattles=await warFetchActiveBattles();
    const activeWar=activeBattles?.alliance_attack_war&&typeof activeBattles.alliance_attack_war==='object'?activeBattles.alliance_attack_war:null;
    let attackCost=null,opponents=[];
    if(activeWar){
      const result=await Promise.allSettled([warFetchAttackCost(),warFetchOpponents()]);
      if(result[0].status==='fulfilled')attackCost=result[0].value;
      if(result[1].status==='fulfilled')opponents=result[1].value;
    }
    const available=pitCanonResourceQuantity(playerDocument,WAR_FREE_PASS_ID,'currency');
    const maxPasses=pitCanonCurrencyMax(playerDocument,WAR_FREE_PASS_ID);
    const plans=activeWar?warBuildPlans(available,attackCost):[];
    const saved=warCombatSaved();
    const selected=plans.find(plan=>plan.id===String(saved?.planId||''))||plans.find(plan=>plan.paymentMode==='FREE')||plans[0]||null;
    Object.assign(warCombat,{loaded:true,activeBattles,activeWar,attackCost,opponents,available,maxPasses,plans,planId:selected?.id||'',lastReadAt:Date.now()});
    warCombatSave();
    return warCombat;
  }

  function warCombatHtml() {
    if(!warCombat.loaded)return '<section style="padding:12px;margin-top:12px;border:1px solid #304057;border-radius:12px;background:#101927"><p class="hk-muted">'+either('Загрузка боевого режима…','Loading combat mode…')+'</p></section>';
    const war=warCombat.activeWar,plan=warSelectedPlan();
    if(!war)return '<section style="padding:12px;margin-top:12px;border:1px solid #304057;border-radius:12px;background:#101927"><b>'+either('Боевой режим','Combat mode')+'</b><p class="hk-muted">'+either('Активной атакующей войны сейчас нет.','There is no active attack war.')+'</p></section>';
    const weak=warWeakestOpponent(warCombat.opponents);
    const opponentHtml=warCombat.opponents.length?warCombat.opponents.map(row=>{
      const weakest=weak&&String(weak.id)===String(row.id);
      return '<div style="padding:7px 8px;border:1px solid '+(weakest?'#58779f':'#27364b')+';border-radius:9px">'+
        '<b>'+escapeHtml(String(row?.nickname||row?.id||'—'))+(weakest?' · '+either('выбран','selected'):'')+'</b>'+
        '<small style="display:block;margin-top:3px">'+either('Сила','Power')+': '+warOpponentPower(row).toLocaleString(locale())+
        ' · '+either('Усталость','Fatigue')+': '+warOpponentFatigue(row).toFixed(0)+'% · '+either('Эффективная','Effective')+': '+warOpponentEffectivePower(row).toLocaleString(locale())+'</small></div>';
    }).join(''):'<p class="hk-muted">'+either('Список противников недоступен.','Opponent list unavailable.')+'</p>';
    const plans=warCombat.plans.map(row=>'<option value="'+escapeHtml(row.id)+'" '+(row.id===warCombat.planId?'selected':'')+'>'+escapeHtml(warPlanLabel(row))+'</option>').join('');
    const crystalCost=warCrystalRefillCost(warCombat.attackCost),itemCost=warItemRefillCost(warCombat.attackCost);
    return '<section style="padding:12px;margin-top:12px;border:1px solid #304057;border-radius:12px;background:#101927">'+
      '<div style="display:flex;justify-content:space-between;gap:8px"><div><b>'+either('Боевая война','War combat')+'</b><small style="display:block;margin-top:3px">'+HK_WAR_COMBAT_REV+'</small></div>'+
      '<span class="hk-free">'+either('АКТИВНА','ACTIVE')+'</span></div>'+
      '<div style="display:flex;flex-wrap:wrap;gap:7px;margin:10px 0">'+
        '<span style="padding:5px 8px;border:1px solid #304057;border-radius:9px">🎟 <b>'+warCombat.available.toLocaleString(locale())+(warCombat.maxPasses?' / '+warCombat.maxPasses.toLocaleString(locale()):'')+'</b></span>'+
        '<span style="padding:5px 8px;border:1px solid #304057;border-radius:9px">💎 <b>'+pitCanonResourceQuantity(playerDocument,'cur_prem','currency').toLocaleString(locale())+'</b></span>'+
        (itemCost?'<span style="padding:5px 8px;border:1px solid #304057;border-radius:9px">🎟️+ <b>'+pitCanonResourceQuantity(playerDocument,WAR_PASS_ITEM_ID,'item').toLocaleString(locale())+'</b></span>':'')+
      '</div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><span><small>'+either('Оборона войны','War defense')+'</small><b style="display:block">'+pitCanonWhole(war.health).toLocaleString(locale())+' / '+pitCanonWhole(war.initial_health).toLocaleString(locale())+'</b></span>'+
      '<span><small>'+either('Урон атаки','Attack value')+'</small><b style="display:block">'+pitCanonWhole(warCombat.attackCost?.attack_value).toLocaleString(locale())+'</b></span></div>'+
      '<div class="hk-grid" style="margin-top:10px"><span>'+either('План пропусков','Pass plan')+'</span><select id="hk-war-plan">'+plans+'</select></div>'+
      '<div style="margin:8px 0"><small>'+either('Дополнительный пропуск','Extra pass')+': '+(crystalCost?'💎 '+crystalCost.toLocaleString(locale()):'—')+(itemCost?' · '+either('предмет','item')+' '+itemCost.toLocaleString(locale())+' '+either('(donor не использует автоматически)','(donor does not auto-use)'):'')+'</small></div>'+
      '<div style="display:grid;gap:6px;margin:10px 0">'+opponentHtml+'</div>'+
      '<button id="hk-war-run" class="hk-primary" '+(plan&&weak?'':'disabled')+'>'+either('Запустить выбранный план','Run selected plan')+'</button>'+
    '</section>';
  }

  async function runWarCombat() {
    if(!requireLicense())return;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}
    if(!warCombat.loaded)await loadWarCombat(false);
    const plan=warSelectedPlan(),activeWar=warCombat.activeWar,weak=warWeakestOpponent(warCombat.opponents);
    if(!plan||!activeWar||!weak){log(either('Боевой план войны недоступен','War combat plan unavailable'),'warn');return;}
    const steps=(plan.steps||[]).map(step=>({...step}));
    if(!confirm(either(
      'Запустить бой клана?\\n\\nПлан: '+warPlanLabel(plan)+'\\nСейчас будет выбран самый слабый противник по эффективной силе перед каждой атакой.\\nТекущий кандидат: '+String(weak.nickname||weak.id),
      'Start clan war combat?\\n\\nPlan: '+warPlanLabel(plan)+'\\nThe weakest opponent by effective power will be selected before every attack.\\nCurrent candidate: '+String(weak.nickname||weak.id)
    )))return;

    runtimeSmokeResetModule('war');
    hkRuntimeSmokeRecord('war-start',{
      steps:steps.length,
      paymentMode:String(plan?.paymentMode||''),
      warId:String(activeWar?.id||'').slice(0,100),
      freePasses:pitCanonWhole(warCombat.available)
    });
    hkRunner.start({title:either('Войны','Wars'),total:steps.length,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
    let completed=0;
    try{
      playerDocument=await hkAuthoritativePlayerRead('wars:preflight');
      const liveAvailable=pitCanonResourceQuantity(playerDocument,WAR_FREE_PASS_ID,'currency');
      if(liveAvailable!==pitCanonWhole(warCombat.available))throw new Error(either('Баланс пропусков изменился — обновите данные','War pass balance changed — refresh data'));
      let activeData=await warFetchActiveBattles(),war=activeData?.alliance_attack_war||null;
      if(!war||String(war.id||'')!==String(activeWar.id||''))throw new Error(either('Активная война изменилась','Active war changed'));

      for(const step of steps){
        await hkRunner.waitIfPaused();if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
        if(pitCanonWhole(war?.health)<=0)break;
        let currentPasses=pitCanonResourceQuantity(playerDocument,WAR_FREE_PASS_ID,'currency');
        if(step.payment==='PREM'&&currentPasses<=0){
          const liveAttackCost=await warFetchAttackCost(),liveCost=warCrystalRefillCost(liveAttackCost);
          if(liveCost<=0||liveCost!==pitCanonWhole(step.cost))throw new Error(either('Цена дополнительного пропуска изменилась','Extra pass price changed'));
          if(pitCanonResourceQuantity(playerDocument,'cur_prem','currency')<liveCost)throw new Error(either('Недостаточно кристаллов','Not enough crystals'));
          hkRunner.setStep(either('Покупка дополнительного пропуска','Buying extra pass')+' · 💎 '+liveCost,completed,steps.length);
          const bought=await apiJson('/alliance_war/buy_pass','POST',{war_id:String(war.id||activeWar.id),payment_type:'PREM'},true,0);
          warAcceptResponse(bought,'war-combat:buy-pass');
          currentPasses=pitCanonResourceQuantity(playerDocument,WAR_FREE_PASS_ID,'currency');
          if(currentPasses<=0)throw new Error(either('Дополнительный пропуск не появился','Extra pass was not added'));
        }
        if(currentPasses<=0)throw new Error(either('Нет пропусков для атаки','No attack passes available'));

        const opponents=await warFetchOpponents();
        if(opponents.length!==3)throw new Error(either('Список противников изменился — обновите данные','Opponent list changed — refresh data'));
        const selected=warWeakestOpponent(opponents);
        if(!selected)throw new Error(either('Не удалось выбрать противника','Could not select opponent'));
        const beforeHealth=pitCanonWhole(war?.health);
        hkRunner.setStep(either('Атака','Attack')+': '+String(selected.nickname||selected.id)+' · '+either('эфф. сила','effective power')+' '+warOpponentEffectivePower(selected).toLocaleString(locale()),completed,steps.length);
        await gameRetryDelay(1000);
        const battle=await apiJson('/alliance_war/fight','POST',{defender_id:String(selected.id)},true,0);
        warAcceptResponse(battle,'war-combat:fight');
        war=battle?.alliance_attack_war||warCombat.activeWar||war;
        warCombat.activeWar=war;
        const afterHealth=pitCanonWhole(war?.health),damage=Math.max(0,beforeHealth-afterHealth),won=battle?.battle_result?.is_win===true,winrate=warWinrateSummary(battle);
        log((won?'✓ ':'✗ ')+String(selected.nickname||selected.id)+' · '+either('урон обороне','defense damage')+': '+damage.toLocaleString(locale())+' · '+either('оборона','defense')+': '+afterHealth.toLocaleString(locale())+' / '+pitCanonWhole(war?.initial_health).toLocaleString(locale())+(winrate?' · '+either('винрейт','winrate')+': '+winrate:''),won?'ok':'warn');
        completed++;hkRunner.setStep(either('Атака завершена','Attack completed'),completed,steps.length);
        if(afterHealth<=0)break;
      }

      playerDocument=await hkAuthoritativePlayerRead('wars:complete');
      await loadWarCombat(false);
      const publicResult=await readPublicWar(warCombat.activeBattles);
      warSnapshot=publicResult?.war||null;warLastReadAt=Date.now();
      hkRuntimeSmokeRecord('war-complete',{
        hasWar:!!warCombat.activeWar,
        health:Number(warCombat.activeWar?.health??0),
        initialHealth:Number(warCombat.activeWar?.initial_health??0),
        passes:pitCanonResourceQuantity(playerDocument,WAR_FREE_PASS_ID,'currency')
      });
      renderWars();
      hkRunner.finish(either('План войны завершён','War plan completed'));
      log(either('План войны завершён','War plan completed'),'ok');
    }catch(error){
      hkRuntimeSmokeRecord('war-error',{
        name:String(error?.name||''),
        status:Number(error?.httpStatus||0),
        message:String(error?.message||error||'').slice(0,500)
      });
      try{
        playerDocument=await hkAuthoritativePlayerRead('wars:error');
        await loadWarCombat(false);
        const publicResult=await readPublicWar(warCombat.activeBattles);
        warSnapshot=publicResult?.war||null;warLastReadAt=Date.now();
      }catch(_){}
      renderWars();
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Война остановлена','War stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка Войны','War error')+': '+(error?.message||error),'bad');}
    }
  }

            function renderWars() {
    const box=root?.querySelector('#hk-war-content');
    if(!box)return;
    const war=warSnapshot;
    let top='';
    if(!war){
      top='<div class="hk-clan-head"><div><h3>'+either('Войны','Wars')+'</h3><small>'+either('Данные читаются из активных войн клана','Data is read from active clan wars')+'</small></div><button id="hk-war-refresh" class="hk-secondary">'+either('Обновить','Refresh')+'</button></div><p class="hk-muted">'+either('Сводная активная война не найдена.','No aggregate active war found.')+'</p>';
    }else{
      const ourScore=war.our_score==null?'—':Number(war.our_score).toLocaleString(locale());
      const enemyScore=war.opponent_score==null?'—':Number(war.opponent_score).toLocaleString(locale());
      const ourHp=warHpHtml(war.our_hp,war.our_hp_max,'our');
      const enemyHp=warHpHtml(war.opponent_hp,war.opponent_hp_max,'enemy');
      const started=warTimestamp(war.started_at),ends=warTimestamp(war.ends_at);
      top='<div class="hk-clan-head"><div><h3>'+either('Войны','Wars')+'</h3><small>'+escapeHtml(String(war.status||either('активна','active')))+'</small></div><button id="hk-war-refresh" class="hk-secondary">'+either('Обновить','Refresh')+'</button></div>'+
        '<div class="hk-war-score"><div><small>'+either('Наш клан','Our clan')+'</small><b>'+escapeHtml(war.our_clan||'—')+'</b><strong>'+ourScore+'</strong>'+ourHp+'</div><span>VS</span><div><small>'+either('Соперник','Opponent')+'</small><b>'+escapeHtml(war.opponent||'—')+'</b><strong>'+enemyScore+'</strong>'+enemyHp+'</div></div>'+
        '<p class="hk-muted">'+[started?either('Начало','Started')+': '+started:'',ends?either('Окончание','Ends')+': '+ends:'',warLastReadAt?either('Обновлено','Updated')+': '+new Date(warLastReadAt).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'}):''].filter(Boolean).join(' · ')+'</p>';
    }
    box.innerHTML=top+warCombatHtml();
    box.querySelector('#hk-war-refresh')?.addEventListener('click',()=>void refreshModuleLive('wars',{force:true}));
    box.querySelector('#hk-war-plan')?.addEventListener('change',event=>{warCombat.planId=String(event.target.value||'');warCombatSave();renderWars();});
    box.querySelector('#hk-war-run')?.addEventListener('click',()=>void runWarCombat());
  }

  async function refreshWars(force=false) {
    if(!requireLicense())return null;
    try{
      let combat=null;
      try{combat=await loadWarCombat(force);}catch(error){log(either('Ошибка боевого режима Войны','War combat read error')+': '+(error?.message||error),'warn');}
      const result=await readPublicWar(combat?.activeBattles||null);
      warSnapshot=result?.war||null;
      warLastReadAt=Date.now();
      renderWars();
      if(force)log(warSnapshot||warCombat.activeWar?either('Данные войны обновлены','War data refreshed'):either('Активная война не найдена','No active war found'),warSnapshot||warCombat.activeWar?'ok':'warn');
      return warSnapshot||warCombat.activeWar;
    }catch(error){
      log(either('Ошибка чтения войны','War read error')+': '+(error?.message||error),'warn');
      renderWars();
      return null;
    }
  }

  function ratHuntSlot(documentValue) {
    return documentValue?.your_lb_slot || documentValue?.player_slot || documentValue?.slot || null;
  }

  function ratHuntRewardParts(rewardView) {
    const result=[];
    for (const kind of ['items','currencies']) for (const reward of rewardView?.[kind] || []) {
      const id=String(reward?.id || reward?.item_id || reward?.currency_id || '');
      const quantity=Math.max(0,Number(reward?.quantity ?? reward?.value ?? 0));
      if(id && quantity>0) result.push({kind,id,quantity});
    }
    return result;
  }

  function ratHuntRewardHtml(rewardView) {
    const parts=ratHuntRewardParts(rewardView);
    if(!parts.length) return '<span class="hk-muted">—</span>';
    return '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">'+parts.map(part =>
      '<span style="display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border:1px solid #304057;border-radius:9px;background:#101927">'+
      fairIconHtml(paymentIcon(part),'hk-price-icon')+
      '<b>'+escapeHtml(gameText(part.id)||paymentLabel(part.id)||part.id)+' ×'+Number(part.quantity).toLocaleString(locale())+'</b></span>'
    ).join('')+'</div>';
  }

  function ratHuntMetric(slot, keys) {
    const value=metricFromObject(slot,keys);
    return value===null?null:Number(value);
  }

  function normalizeRatHuntRow(def,current,previous) {
    const currentSlot=ratHuntSlot(current);
    const previousSlot=ratHuntSlot(previous);
    const rank=ratHuntMetric(currentSlot,['rank','place','position']);
    const score=ratHuntMetric(currentSlot,['score','points','value','amount','result']);
    const previousRank=ratHuntMetric(previousSlot,['rank','place','position']);
    const previousScore=ratHuntMetric(previousSlot,['score','points','value','amount','result']);
    const claimable=String(previous?.status||'').toUpperCase()==='RELOAD' &&
      previousSlot?.is_claimed===false && !!previousSlot?.reward_view && !!previous?.id;
    const claimed=previousSlot?.is_claimed===true;
    return {
      ...def,current,previous,currentSlot,previousSlot,rank,score,previousRank,previousScore,
      rewardView:previousSlot?.reward_view||null,claimable,claimed,
      available:!!current||!!previous
    };
  }

  async function readRatHuntLeaderboards() {
    const rows=[];
    for(const def of RAT_HUNT_LEADERBOARDS) {
      let current=null,previous=null;
      try { current=await apiJson('/leaderboard','POST',{leaderboard_type:def.id,leaderboard_status:'ACTUAL'},true,1); }
      catch(error) { recordDiagnostic('rat-hunt-current-read',{id:def.id,error:error?.message||error}); }
      try { previous=await apiJson('/leaderboard','POST',{leaderboard_type:def.id,leaderboard_status:'RELOAD'},true,1); }
      catch(error) { recordDiagnostic('rat-hunt-reload-read',{id:def.id,error:error?.message||error}); }
      rows.push(normalizeRatHuntRow(def,current,previous));
    }
    return rows;
  }


  function ratHuntCombatSaved() {
    const value=load().ratHuntCombat;
    return value&&typeof value==='object'?value:{};
  }

  function ratHuntCombatSave() {
    save({ratHuntCombat:{
      presetId:String(ratHuntCombat.presetId||''),
      planId:String(ratHuntCombat.planId||''),
      autofinish:!!ratHuntCombat.autofinish,
      maxRestoration:pitCanonWhole(ratHuntCombat.maxRestoration)
    }});
  }

  function ratHuntCombatState(documentValue=playerDocument) {
    return documentValue&&typeof documentValue.pit_generals==='object'?documentValue.pit_generals:null;
  }

  function ratHuntPresetName(preset) {
    const key=String(preset?.meta?.name||'');
    return gameText(key||preset?.id||'');
  }

  function ratHuntPresetLabel(preset) {
    const power=pitCanonWhole(preset?.meta?.power);
    return ratHuntPresetName(preset)+(power>0?' — '+power.toLocaleString(locale()):'');
  }

  function ratHuntSwitchCost(preset) {
    const row=(preset?.switch_cost?.items||[]).find(item=>String(item?.id||'')===RAT_HUNT_CLAN_GOLD_ID);
    return pitCanonWhole(row?.quantity);
  }

  function ratHuntMasses(state,view) {
    const values=[];
    for(const row of view?.mass_multipliers||[])values.push(pitCanonWhole(row?.mass_multiplier));
    for(const row of state?.retry_cost?.mass_multipliers||[])if(row?.available!==false)values.push(pitCanonWhole(row?.mass_multiplier));
    for(const row of state?.pass_costs||[])values.push(pitCanonWhole(row?.mass_multiplier));
    return [...new Set(values.filter(value=>value>0))].sort((a,b)=>b-a);
  }

  function ratHuntDecomposeExact(total,masses) {
    let remaining=pitCanonWhole(total),chunks=[];
    for(const mass of [...new Set((masses||[]).map(pitCanonWhole).filter(Boolean))].sort((a,b)=>b-a)){
      while(remaining>=mass){chunks.push(mass);remaining-=mass;}
    }
    return remaining===0?chunks:[];
  }

  function ratHuntDirectPassCost(state,mass,payment) {
    const prem=payment==='PREM';
    const row=(state?.pass_costs||[]).find(entry=>entry?.is_prem===prem&&pitCanonWhole(entry?.mass_multiplier)===pitCanonWhole(mass));
    if(!row)return null;
    return pitCanonCostQuantity(row?.cost,prem?'cur_prem':RAT_HUNT_PASS_ITEM_ID,prem?'currency':'item');
  }

  function ratHuntRespawnCost(state) {
    const option=(state?.respawn_costs||[]).find(row=>row?.is_prem===false);
    const cost=pitCanonCostQuantity(option,RAT_HUNT_RESTORATION_ITEM_ID,'item');
    return cost===null?0:pitCanonWhole(cost);
  }

  function ratHuntBuildPlans(state,available,view) {
    if(!state)return[];
    if(state.is_finish===false){
      const chunk=Math.max(1,pitCanonWhole(state?.mass_multiplier)||1);
      return[{id:'active',kind:'active',total:chunk,paymentMode:'ACTIVE',steps:[{chunk,payment:'ACTIVE',cost:0}],crystalCost:0,itemCost:0}];
    }
    const plans=[],masses=ratHuntMasses(state,view),free=ratHuntDecomposeExact(available,masses);
    if(available>0&&free.length&&free.reduce((sum,value)=>sum+value,0)===pitCanonWhole(available)){
      plans.push({id:'free-exact',kind:'exact',total:pitCanonWhole(available),paymentMode:'FREE',steps:free.map(chunk=>({chunk,payment:'FREE',cost:0})),crystalCost:0,itemCost:0});
    }
    const seen=new Set();
    const rows=[...(state?.pass_costs||[])].filter(row=>pitCanonWhole(row?.mass_multiplier)>0).sort((a,b)=>
      pitCanonWhole(a?.mass_multiplier)-pitCanonWhole(b?.mass_multiplier)||
      ((a?.is_prem===true?0:1)-(b?.is_prem===true?0:1))
    );
    for(const row of rows){
      const mass=pitCanonWhole(row.mass_multiplier),payment=row?.is_prem===true?'PREM':'ITEM',key=payment+':'+mass;
      if(seen.has(key))continue;seen.add(key);
      const cost=ratHuntDirectPassCost(state,mass,payment);
      if(cost===null)continue;
      plans.push({id:'direct-'+payment.toLowerCase()+'-'+mass,kind:'direct',total:mass,paymentMode:payment,
        steps:[{chunk:mass,payment,cost:pitCanonWhole(cost)}],
        crystalCost:payment==='PREM'?pitCanonWhole(cost):0,itemCost:payment==='ITEM'?pitCanonWhole(cost):0});
    }
    return plans;
  }

  function ratHuntMaxLevel(view=ratHuntCombat.view,state=ratHuntCombat.state) {
    const fromView=Math.max(0,...(view?.levels||[]).map(row=>pitCanonWhole(row?.level)+1));
    return Math.max(fromView,pitCanonWhole(state?.max_preset_level));
  }

  function ratHuntRewardToMax(view=ratHuntCombat.view,state=ratHuntCombat.state) {
    const maxLevel=ratHuntMaxLevel(view,state);let total=0;
    for(const level of view?.levels||[]){
      if(pitCanonWhole(level?.level)>=maxLevel)continue;
      const row=(level?.reward_view?.reward?.items||[]).find(item=>String(item?.id||'')===RAT_HUNT_REWARD_ITEM_ID);
      total+=pitCanonWhole(row?.count??row?.quantity);
    }
    return total;
  }

  function ratHuntSelectedPlan() {
    return ratHuntCombat.plans.find(plan=>plan.id===ratHuntCombat.planId)||null;
  }

  function ratHuntEffectiveSteps() {
    const plan=ratHuntSelectedPlan();if(!plan)return[];
    const steps=(plan.steps||[]).map(step=>({...step}));
    return ratHuntCombat.state?.is_finish===false||ratHuntCombat.autofinish?steps:steps.slice(0,1);
  }

  function ratHuntEffectiveCosts() {
    let crystalCost=0,itemCost=0;
    for(const step of ratHuntEffectiveSteps()){
      if(step.payment==='PREM')crystalCost+=pitCanonWhole(step.cost);
      if(step.payment==='ITEM')itemCost+=pitCanonWhole(step.cost);
    }
    return {crystalCost,itemCost};
  }

  function ratHuntPlanLabel(plan) {
    if(!plan)return either('Нет доступного плана','No available plan');
    if(plan.kind==='active')return either('Продолжить активную охоту','Continue active hunt');
    const chunks=(plan.steps||[]).map(step=>'×'+pitCanonWhole(step.chunk)).join(' + ');
    if(plan.paymentMode==='FREE')return either('Бесплатные жетоны','Free tokens')+': '+chunks;
    if(plan.paymentMode==='PREM')return '💎 '+pitCanonWhole(plan.crystalCost).toLocaleString(locale())+' · '+chunks;
    if(plan.paymentMode==='ITEM')return '🎟 '+pitCanonWhole(plan.itemCost).toLocaleString(locale())+' · '+chunks;
    return chunks;
  }

  function ratHuntAcceptResponse(response,reason='rat-hunt') {
    if(response&&typeof response==='object'){
      try{hkStateStore.merge(response,reason);}catch(_){}
      playerDocument=hkStateStore.snapshot||playerDocument;
      if(response?.pit_generals&&typeof response.pit_generals==='object'&&(!playerDocument||playerDocument.pit_generals!==response.pit_generals)){
        playerDocument={...(playerDocument||{}),pit_generals:response.pit_generals};
      }
    }
    ratHuntCombat.state=ratHuntCombatState(playerDocument)||ratHuntCombat.state;
    const smokeState=ratHuntCombat.state;
    hkRuntimeSmokeRecord('rat-hunt-state',{
      reason,
      responseKeys:hkSmokeObjectKeys(response),
      hasState:!!smokeState,
      isFinish:smokeState?.is_finish,
      level:Number(smokeState?.level??0),
      maxLevel:Number(smokeState?.max_preset_level??0),
      health:Number(smokeState?.health??0),
      massMultiplier:Number(smokeState?.mass_multiplier??0),
      passCosts:Array.isArray(smokeState?.pass_costs)?smokeState.pass_costs.length:0,
      respawnCosts:Array.isArray(smokeState?.respawn_costs)?smokeState.respawn_costs.length:0
    });
    return response;
  }

  async function ratHuntFetchPresets() {
    const data=await apiJson('/battle_presets/view','GET',null,true,1);
    return (Array.isArray(data?.pit_generals_presets)?data.pit_generals_presets:[])
      .filter(row=>String(row?.id||''))
      .map(row=>({...row,id:String(row.id),meta:row.meta&&typeof row.meta==='object'?row.meta:{}}))
      .sort((a,b)=>pitCanonWhole(a?.meta?.power)-pitCanonWhole(b?.meta?.power));
  }

  async function ratHuntFetchView(presetId) {
    return apiJson('/pit_generals/view?preset_id='+encodeURIComponent(String(presetId||'')),'GET',null,true,1);
  }

  function ratHuntRefreshPlans() {
    const state=ratHuntCombat.state;
    const available=pitCanonResourceQuantity(playerDocument,RAT_HUNT_FREE_PASS_ID,'currency');
    ratHuntCombat.plans=ratHuntBuildPlans(state,available,ratHuntCombat.view);
    const saved=ratHuntCombatSaved();
    const selected=ratHuntCombat.plans.find(plan=>plan.id===ratHuntCombat.planId)||
      ratHuntCombat.plans.find(plan=>plan.id===String(saved.planId||''))||
      ratHuntCombat.plans.find(plan=>plan.paymentMode==='FREE')||
      ratHuntCombat.plans[0]||null;
    ratHuntCombat.planId=selected?.id||'';
    ratHuntCombatSave();
  }

  async function loadRatHuntCombat(force=false) {
    if(!requireLicense())return null;
    playerDocument=await hkAuthoritativePlayerRead(force?'rat-hunt:refresh':'rat-hunt:load');
    const state=ratHuntCombatState(playerDocument);
    const presets=await ratHuntFetchPresets();
    if(!state||!presets.length)throw new Error(either('Данные Rat Hunt недоступны','Rat Hunt data is unavailable'));
    const saved=ratHuntCombatSaved(),active=state.is_finish===false;
    const currentPresetId=String(state?.preset_id||presets[0]?.id||'');
    const savedPresetId=String(saved?.presetId||'');
    const presetId=active?currentPresetId:(presets.some(row=>row.id===savedPresetId)?savedPresetId:currentPresetId);
    const view=await ratHuntFetchView(presetId);
    ratHuntCombat.loaded=true;ratHuntCombat.presets=presets;ratHuntCombat.view=view;ratHuntCombat.state=state;
    ratHuntCombat.currentPresetId=currentPresetId;ratHuntCombat.presetId=presetId;
    ratHuntCombat.autofinish=saved?.autofinish===true;
    ratHuntCombat.maxRestoration=Math.min(
      pitCanonResourceQuantity(playerDocument,RAT_HUNT_RESTORATION_ITEM_ID,'item'),
      pitCanonWhole(saved?.maxRestoration)
    );
    ratHuntCombat.planId=String(saved?.planId||'');
    ratHuntCombat.lastReadAt=Date.now();
    ratHuntRefreshPlans();
    return ratHuntCombat;
  }

  function ratHuntResourceBadge(id,kind='item') {
    const amount=pitCanonResourceQuantity(playerDocument,id,kind);
    const icon=fairIconHtml(paymentIcon({id,kind:kind==='currency'?'currencies':'items'}),'hk-price-icon');
    return '<span style="display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border:1px solid #304057;border-radius:9px">'+icon+'<b>'+amount.toLocaleString(locale())+'</b></span>';
  }

  function ratHuntCombatHtml() {
    if(!ratHuntCombat.loaded)return '<section style="padding:12px;border:1px solid #304057;border-radius:12px;background:#101927"><p class="hk-muted">'+either('Загрузка боевой Охоты на крыс…','Loading Rat Hunt combat…')+'</p></section>';
    const state=ratHuntCombat.state||{},active=state.is_finish===false,plan=ratHuntSelectedPlan(),steps=ratHuntEffectiveSteps(),costs=ratHuntEffectiveCosts();
    const selectedPreset=ratHuntCombat.presets.find(row=>row.id===ratHuntCombat.presetId);
    const switchCost=!active&&ratHuntCombat.presetId!==ratHuntCombat.currentPresetId?ratHuntSwitchCost(selectedPreset):0;
    const presets=ratHuntCombat.presets.map(row=>'<option value="'+escapeHtml(row.id)+'" '+(row.id===ratHuntCombat.presetId?'selected':'')+'>'+
      escapeHtml(ratHuntPresetLabel(row)+(row.id===ratHuntCombat.currentPresetId?' · '+either('текущий','current'):''))+'</option>').join('');
    const plans=ratHuntCombat.plans.map(row=>'<option value="'+escapeHtml(row.id)+'" '+(row.id===ratHuntCombat.planId?'selected':'')+'>'+escapeHtml(ratHuntPlanLabel(row))+'</option>').join('');
    const maxLevel=ratHuntMaxLevel(),level=pitCanonWhole(state.level),health=pitCanonWhole(state.health);
    const multiplier=steps.reduce((sum,step)=>sum+pitCanonWhole(step.chunk),0);
    const expected=ratHuntRewardToMax()*multiplier;
    const paws=pitCanonResourceQuantity(playerDocument,RAT_HUNT_RESTORATION_ITEM_ID,'item');
    const totalPaws=pitCanonWhole(ratHuntCombat.maxRestoration)*steps.length;
    return '<section style="padding:12px;border:1px solid #304057;border-radius:12px;background:#101927;margin-bottom:12px">'+
      '<div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div><b>'+either('Боевая Охота','Combat Rat Hunt')+'</b><small style="display:block;margin-top:3px">'+HK_RAT_HUNT_COMBAT_REV+'</small></div>'+
      '<span class="'+(active?'hk-free':'hk-muted')+'">'+(active?either('АКТИВНА','ACTIVE'):either('готова','ready'))+'</span></div>'+
      '<div style="display:flex;flex-wrap:wrap;gap:6px;margin:10px 0">'+
        ratHuntResourceBadge(RAT_HUNT_FREE_PASS_ID,'currency')+
        ratHuntResourceBadge(RAT_HUNT_PASS_ITEM_ID,'item')+
        ratHuntResourceBadge(RAT_HUNT_RESTORATION_ITEM_ID,'item')+
        ratHuntResourceBadge(RAT_HUNT_CLAN_GOLD_ID,'item')+
        ratHuntResourceBadge('cur_prem','currency')+
      '</div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0"><span><small>'+either('Уровень','Level')+'</small><b style="display:block">'+level+' / '+maxLevel+'</b></span>'+
      '<span><small>HP</small><b style="display:block">'+health.toLocaleString(locale())+'</b></span></div>'+
      '<div class="hk-grid">'+
        '<span>'+either('Пресет крыс','Rat preset')+'</span><select id="hk-rat-preset" '+(active?'disabled':'')+'>'+presets+'</select>'+
        '<span>'+either('План пропусков','Pass plan')+'</span><select id="hk-rat-plan" '+(active?'disabled':'')+'>'+plans+'</select>'+
        '<span>'+either('Максимум лап на раунд','Max paws per round')+'</span><input id="hk-rat-paws" type="number" min="0" max="'+paws+'" value="'+Math.min(paws,pitCanonWhole(ratHuntCombat.maxRestoration))+'">'+
        '<span>'+either('Автозавершение','Auto finish')+'</span><input id="hk-rat-autofinish" type="checkbox" '+(ratHuntCombat.autofinish?'checked':'')+'>'+
      '</div>'+
      '<div style="margin:10px 0;padding:9px;border:1px solid #27364b;border-radius:10px"><small>'+
        (plan?escapeHtml(ratHuntPlanLabel(plan)):'—')+
        (switchCost?' · '+either('смена пресета','preset switch')+': 🪙 '+switchCost.toLocaleString(locale()):'')+
        (costs.crystalCost?' · 💎 '+costs.crystalCost.toLocaleString(locale()):'')+
        (costs.itemCost?' · 🎟 '+costs.itemCost.toLocaleString(locale()):'')+
        (totalPaws?' · 🐾 ≤ '+totalPaws.toLocaleString(locale()):'')+
        (expected?' · 🐀 ~'+expected.toLocaleString(locale()):'')+
        (!active&&!ratHuntCombat.autofinish&&plan?.steps?.length>1?' · '+either('без автозавершения выполнится только первый раунд','without auto finish only the first round will run'):'')+
      '</small></div>'+
      '<button id="hk-rat-run" class="hk-primary" '+(plan?'':'disabled')+'>'+either(active?'Продолжить Охоту':'Запустить Охоту',active?'Continue Hunt':'Start Hunt')+'</button>'+
    '</section>';
  }

  async function changeRatHuntPreset(presetId) {
    if(ratHuntCombat.state?.is_finish===false)return;
    if(!ratHuntCombat.presets.some(row=>row.id===presetId))return;
    ratHuntCombat.presetId=presetId;ratHuntCombat.view=await ratHuntFetchView(presetId);ratHuntRefreshPlans();ratHuntCombatSave();renderRatHunt();
  }

  async function runRatHuntCombat() {
    if(!requireLicense())return;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}
    if(!ratHuntCombat.loaded)await loadRatHuntCombat(false);
    const selectedPlan=ratHuntSelectedPlan(),steps=ratHuntEffectiveSteps().map(step=>({...step}));
    if(!selectedPlan||!steps.length){log(either('Нет доступного плана Rat Hunt','No Rat Hunt plan available'),'warn');return;}
    const selectedPreset=ratHuntCombat.presets.find(row=>row.id===ratHuntCombat.presetId);
    const switchCost=ratHuntCombat.state?.is_finish===false||ratHuntCombat.presetId===ratHuntCombat.currentPresetId?0:ratHuntSwitchCost(selectedPreset);
    const costs=ratHuntEffectiveCosts(),rounds=steps.length,totalPaws=pitCanonWhole(ratHuntCombat.maxRestoration)*rounds;
    if(!confirm(either(
      'Запустить Охоту на крыс?\\n\\nПресет: '+ratHuntPresetLabel(selectedPreset)+'\\nРаунды: '+steps.map(step=>'×'+pitCanonWhole(step.chunk)).join(' + ')+(switchCost?'\\nСмена пресета: '+switchCost+' кланового золота':'')+(costs.crystalCost?'\\nКристаллы: '+costs.crystalCost:'')+(costs.itemCost?'\\nЖетоны пополнения: '+costs.itemCost:'')+'\\nЛапы восстановления: до '+totalPaws,
      'Start Rat Hunt?\\n\\nPreset: '+ratHuntPresetLabel(selectedPreset)+'\\nRounds: '+steps.map(step=>'×'+pitCanonWhole(step.chunk)).join(' + ')+(switchCost?'\\nPreset switch: '+switchCost+' Clan Gold':'')+(costs.crystalCost?'\\nCrystals: '+costs.crystalCost:'')+(costs.itemCost?'\\nRefill tickets: '+costs.itemCost:'')+'\\nRestoration Paws: up to '+totalPaws
    )))return;

    runtimeSmokeResetModule('rat-hunt');
    hkRuntimeSmokeRecord('rat-hunt-start',{
      rounds,
      paymentMode:String(selectedPlan?.paymentMode||''),
      presetId:String(ratHuntCombat.presetId||'').slice(0,100),
      maxRestoration:pitCanonWhole(ratHuntCombat.maxRestoration)
    });
    hkRunner.start({title:either('Охота на крыс','Rat Hunt'),total:rounds,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
    let completed=0;
    try{
      playerDocument=await hkAuthoritativePlayerRead('rat-hunt:preflight');
      let state=ratHuntCombatState(playerDocument);if(!state)throw new Error(either('Rat Hunt недоступна','Rat Hunt is unavailable'));

      if(state.is_finish!==false&&String(state.preset_id||'')!==String(ratHuntCombat.presetId||'')){
        const presets=await ratHuntFetchPresets(),livePreset=presets.find(row=>row.id===ratHuntCombat.presetId);
        const liveCost=livePreset?ratHuntSwitchCost(livePreset):null;
        if(liveCost===null||liveCost!==pitCanonWhole(switchCost))throw new Error(either('Стоимость смены пресета изменилась — обновите данные','Preset switch cost changed — refresh data'));
        if(pitCanonResourceQuantity(playerDocument,RAT_HUNT_CLAN_GOLD_ID,'item')<liveCost)throw new Error(either('Недостаточно кланового золота','Not enough Clan Gold'));
        hkRunner.setStep(either('Смена пресета','Changing preset'),completed,rounds);
        const changed=await apiJson('/pit_generals/change_preset','POST',{preset_id:ratHuntCombat.presetId},true,0);
        ratHuntAcceptResponse(changed,'rat-hunt:change-preset');state=ratHuntCombatState(playerDocument);
        if(String(state?.preset_id||'')!==String(ratHuntCombat.presetId))throw new Error(either('Пресет не изменился','Preset did not change'));
      }

      for(let index=0;index<steps.length;index++){
        await hkRunner.waitIfPaused();if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
        const step=steps[index];state=ratHuntCombatState(playerDocument);if(!state)throw new Error(either('Состояние Rat Hunt потеряно','Rat Hunt state is unavailable'));
        const resuming=step.payment==='ACTIVE';
        if(resuming){
          if(state.is_finish!==false)throw new Error(either('Активная Охота уже завершена','Active hunt is already finished'));
        }else{
          if(state.is_finish===false)throw new Error(either('Уже есть активная Охота — обновите данные','A Rat Hunt is already active — refresh data'));
          const chunk=pitCanonWhole(step.chunk);
          hkRunner.setStep(either('Запуск раунда','Starting round')+' ×'+chunk,completed,rounds);
          let result;
          if(step.payment==='FREE'){
            if(pitCanonResourceQuantity(playerDocument,RAT_HUNT_FREE_PASS_ID,'currency')<chunk)throw new Error(either('Свободные жетоны изменились — обновите данные','Free tokens changed — refresh data'));
            result=await apiJson('/pit_generals/start','POST',{mass_multiplier:chunk},true,0);
          }else{
            const liveCost=ratHuntDirectPassCost(state,chunk,step.payment);
            if(liveCost===null||pitCanonWhole(liveCost)!==pitCanonWhole(step.cost))throw new Error(either('Цена запуска изменилась — обновите данные','Run price changed — refresh data'));
            const resourceId=step.payment==='PREM'?'cur_prem':RAT_HUNT_PASS_ITEM_ID,kind=step.payment==='PREM'?'currency':'item';
            if(pitCanonResourceQuantity(playerDocument,resourceId,kind)<pitCanonWhole(liveCost))throw new Error(either('Недостаточно ресурса для запуска','Not enough resource to start'));
            result=await apiJson('/pit_generals/pass','POST',{mass_multiplier:chunk,payment_type:step.payment},true,0);
          }
          ratHuntAcceptResponse(result,'rat-hunt:start');state=ratHuntCombatState(playerDocument);
        }

        let restorationSpent=0,stoppedForRestoration=false;
        while(state&&state.is_finish===false&&pitCanonWhole(state.level)<pitCanonWhole(state.max_preset_level||10)){
          await hkRunner.waitIfPaused();if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
          if(pitCanonWhole(state.health)<=0){
            const cost=ratHuntRespawnCost(state),available=pitCanonResourceQuantity(playerDocument,RAT_HUNT_RESTORATION_ITEM_ID,'item');
            if(cost<=0||restorationSpent+cost>pitCanonWhole(ratHuntCombat.maxRestoration)||available<cost){stoppedForRestoration=true;break;}
            hkRunner.setStep(either('Восстановление','Restoring')+' 🐾 '+cost,completed,rounds);
            const restored=await apiJson('/pit_generals/respawn','POST',{payment_type:'ITEM'},true,0);
            ratHuntAcceptResponse(restored,'rat-hunt:respawn');restorationSpent+=cost;state=ratHuntCombatState(playerDocument);continue;
          }
          const beforeLevel=pitCanonWhole(state.level),beforeHealth=pitCanonWhole(state.health);
          hkRunner.setStep(either('Бой','Battle')+' · '+beforeLevel+'/'+pitCanonWhole(state.max_preset_level||10)+' · HP '+beforeHealth,completed,rounds);
          await gameRetryDelay(1000);
          const battle=await apiJson('/pit_generals/battle','POST',null,true,0);
          ratHuntAcceptResponse(battle,'rat-hunt:battle');state=ratHuntCombatState(playerDocument);
          const won=pitCanonWhole(state?.level)>beforeLevel||battle?.battle_result?.is_win===true;
          log((won?'✓ ':'✗ ')+either('Охота на крыс','Rat Hunt')+': '+beforeLevel+' → '+pitCanonWhole(state?.level)+' · HP '+pitCanonWhole(state?.health),won?'ok':'warn');
        }

        state=ratHuntCombatState(playerDocument);
        if(stoppedForRestoration)log(either('Остановлено: достигнут лимит Лап восстановления','Stopped: Restoration Paws limit reached'),'warn');
        if(state?.is_finish===false){
          if(ratHuntCombat.autofinish){
            hkRunner.setStep(either('Завершение раунда','Finishing round'),completed,rounds);
            const finished=await apiJson('/pit_generals/finish','POST',null,true,0);
            ratHuntAcceptResponse(finished,'rat-hunt:finish');
          }else{
            log(either('Охота оставлена активной для ручного продолжения','Hunt left active for manual continuation'),'warn');
            completed++;hkRunner.setStep(either('Раунд оставлен активным','Round left active'),completed,rounds);break;
          }
        }
        completed++;hkRunner.setStep(either('Раунд завершён','Round completed'),completed,rounds);
      }

      playerDocument=await hkAuthoritativePlayerRead('rat-hunt:complete');
      await loadRatHuntCombat(false);
      hkRuntimeSmokeRecord('rat-hunt-complete',{
        hasState:!!ratHuntCombat.state,
        isFinish:ratHuntCombat.state?.is_finish,
        level:Number(ratHuntCombat.state?.level??0),
        health:Number(ratHuntCombat.state?.health??0)
      });
      hkRunner.finish(either('План Охоты на крыс завершён','Rat Hunt plan completed'));
      log(either('План Охоты на крыс завершён','Rat Hunt plan completed'),'ok');
      renderRatHunt();
    }catch(error){
      hkRuntimeSmokeRecord('rat-hunt-error',{
        name:String(error?.name||''),
        status:Number(error?.httpStatus||0),
        message:String(error?.message||error||'').slice(0,500)
      });
      try{playerDocument=await hkAuthoritativePlayerRead('rat-hunt:error');await loadRatHuntCombat(false);}catch(_){}
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Охота на крыс остановлена','Rat Hunt stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка Охоты на крыс','Rat Hunt error')+': '+(error?.message||error),'bad');}
      renderRatHunt();
    }
  }

  function renderRatHunt() {
    const box=root?.querySelector('#hk-rat-content');
    if(!box)return;
    const pending=ratHuntRows.filter(row=>row.claimable).length;
    const rows=ratHuntRows.length?ratHuntRows:RAT_HUNT_LEADERBOARDS.map(def=>({...def,available:false}));
    const cards=rows.map(row=>{
      const label=language==='en'?row.en:row.ru;
      const currentRank=row.rank===null||row.rank===undefined?'—':'#'+Number(row.rank).toLocaleString(locale());
      const currentScore=row.score===null||row.score===undefined?'—':Number(row.score).toLocaleString(locale());
      const previousRank=row.previousRank===null||row.previousRank===undefined?'—':'#'+Number(row.previousRank).toLocaleString(locale());
      const previousScore=row.previousScore===null||row.previousScore===undefined?'—':Number(row.previousScore).toLocaleString(locale());
      const rewardState=row.claimable?either('можно получить','claimable'):row.claimed?either('получено','claimed'):either('нет доступной награды','no claimable reward');
      return '<section style="padding:10px;margin:8px 0;border:1px solid #304057;border-radius:12px;background:#101927">'+
        '<div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><b>'+escapeHtml(label)+'</b><small>'+escapeHtml(row.id||'')+'</small></div>'+
        (row.available
          ? '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">'+
              '<div><small>'+either('Текущий рейтинг','Current ranking')+'</small><div><b>'+currentRank+'</b> · '+either('очки','score')+': <b>'+currentScore+'</b></div></div>'+
              '<div><small>'+either('Прошлый период','Previous period')+'</small><div><b>'+previousRank+'</b> · '+either('очки','score')+': <b>'+previousScore+'</b></div></div>'+
            '</div><div style="margin-top:7px"><small>'+either('Награда','Reward')+': '+escapeHtml(rewardState)+'</small>'+ratHuntRewardHtml(row.rewardView)+'</div>'
          : '<p class="hk-muted">'+either('Рейтинг сейчас недоступен или ещё не считан.','Leaderboard is unavailable or has not been read yet.')+'</p>')+
      '</section>';
    }).join('');
    box.innerHTML='<div class="hk-clan-head"><div><h3>'+either('Охота на крыс','Rat Hunt')+'</h3><small>'+
      either('Боевая механика + месячные рейтинги','Combat runner + monthly leaderboards')+
      '</small></div><button id="hk-rat-refresh" class="hk-secondary">'+either('Обновить всё','Refresh all')+'</button></div>'+
      ratHuntCombatHtml()+
      '<details open style="margin-top:10px"><summary style="cursor:pointer"><b>'+either('Месячные рейтинги Cat / Dog / Pigeon','Monthly Cat / Dog / Pigeon leaderboards')+'</b></summary>'+
      '<div style="display:flex;justify-content:flex-end;margin:8px 0"><button id="hk-rat-claim" class="hk-secondary" '+(pending?'':'disabled')+'>'+either('Получить рейтинговые награды','Claim leaderboard rewards')+(pending?' ('+pending+')':'')+'</button></div>'+
      cards+'</details>';
    box.querySelector('#hk-rat-refresh')?.addEventListener('click',()=>void refreshModuleLive('rats',{force:true}));
    box.querySelector('#hk-rat-claim')?.addEventListener('click',()=>void claimRatHuntRewards());
    box.querySelector('#hk-rat-run')?.addEventListener('click',()=>void runRatHuntCombat());
    box.querySelector('#hk-rat-preset')?.addEventListener('change',event=>void changeRatHuntPreset(String(event.target.value||'')));
    box.querySelector('#hk-rat-plan')?.addEventListener('change',event=>{ratHuntCombat.planId=String(event.target.value||'');ratHuntCombatSave();renderRatHunt();});
    box.querySelector('#hk-rat-autofinish')?.addEventListener('change',event=>{ratHuntCombat.autofinish=!!event.target.checked;ratHuntCombatSave();renderRatHunt();});
    box.querySelector('#hk-rat-paws')?.addEventListener('change',event=>{
      ratHuntCombat.maxRestoration=Math.min(pitCanonResourceQuantity(playerDocument,RAT_HUNT_RESTORATION_ITEM_ID,'item'),pitCanonWhole(event.target.value));
      ratHuntCombatSave();renderRatHunt();
    });
  }

  async function refreshRatHunt(force=false) {
    if(!requireLicense())return null;
    try{
      const results=await Promise.allSettled([loadRatHuntCombat(force),readRatHuntLeaderboards()]);
      if(results[0].status==='rejected')log(either('Ошибка боевой Охоты','Rat Hunt combat read error')+': '+(results[0].reason?.message||results[0].reason),'warn');
      if(results[1].status==='fulfilled')ratHuntRows=results[1].value;
      else log(either('Ошибка рейтингов Охоты','Rat Hunt leaderboard read error')+': '+(results[1].reason?.message||results[1].reason),'warn');
      ratHuntLastReadAt=Date.now();
      renderRatHunt();
      if(force)log(either('Охота на крыс обновлена','Rat Hunt refreshed'),results[0].status==='fulfilled'?'ok':'warn');
      return {combat:results[0].status==='fulfilled'?results[0].value:null,leaderboards:ratHuntRows};
    }catch(error){
      log(either('Ошибка чтения Охоты на крыс','Rat Hunt read error')+': '+(error?.message||error),'warn');
      renderRatHunt();
      return null;
    }
  }

  async function claimRatHuntRewards() {
    if(!requireLicense())return;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}
    if(!ratHuntRows.length) await refreshRatHunt(false);
    const pending=ratHuntRows.filter(row=>row.claimable&&row.previous?.id);
    if(!pending.length){log(either('Доступных наград Охоты на крыс нет','No Rat Hunt rewards are available'),'warn');renderRatHunt();return;}
    if(!confirm(either(`Получить награды Охоты на крыс: ${pending.length}?`,`Claim Rat Hunt rewards: ${pending.length}?`)))return;
    hkRunner.start({title:either('Охота на крыс','Rat Hunt'),total:pending.length,step:either('Получение наград','Claiming rewards'),pausable:true,stoppable:true});
    let claimed=0;
    try{
      for(const row of pending){
        if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
        await hkRunner.waitIfPaused();
        hkRunner.setStep((language==='en'?row.en:row.ru),claimed,pending.length);
        try{
          const result=await apiJson('/leaderboard/reward','POST',{leaderboard_id:String(row.previous.id)});
          playerDocument=hkStateStore.snapshot||result||playerDocument;
          claimed+=1;
          log(either('Получена награда Охоты на крыс','Rat Hunt reward claimed')+': '+row.id,'ok');
        }catch(error){
          if(!/HTTP 409/.test(String(error?.message||error)))throw error;
        }
      }
      hkRunner.finish(either('Награды Охоты на крыс получены','Rat Hunt rewards claimed'));
      await refreshRatHunt(false);
      log(either(`Получено наград Охоты на крыс: ${claimed}`,`Rat Hunt rewards claimed: ${claimed}`),'ok');
    }catch(error){
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Сбор наград Охоты на крыс остановлен','Rat Hunt reward claim stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка получения наград Охоты на крыс','Rat Hunt reward claim error')+': '+(error?.message||error),'bad');}
    }
  }


  function neighborhoodBaseName() {
    const translated=localizationDocument?.ui_idler_building_default_name;
    return typeof translated==='string'&&translated.trim() ? translated : either('Район под угрозой','Neighborhood Under Threat');
  }

  function neighborhoodSavedIds() {
    const value=load().neighborhoodBattleIds;
    return Array.isArray(value) ? value.map(String).filter(Boolean) : null;
  }

  function neighborhoodSaveIds(ids) {
    save({neighborhoodBattleIds:[...new Set((ids||[]).map(String).filter(Boolean))]});
  }

  function neighborhoodFinalLevel(enemy) {
    return (enemy?.levels||[]).reduce((max,row)=>Math.max(max,Math.max(0,Number(row?.level)||0)),0);
  }

  function neighborhoodLevelDef(enemy,level) {
    const rows=Array.isArray(enemy?.levels)?enemy.levels:[];
    return rows.find(row=>Number(row?.level)===Number(level)) || rows[0] || {};
  }

  function neighborhoodLiveRow(id) {
    return (neighborhoodIdler?.buildings||[]).find(row=>String(row?.building_id||'')===String(id)) || {};
  }

  function neighborhoodApplyIdler(data,reason='neighborhood') {
    const idler=data?.idler || data?.player?.idler || data?.data?.idler || data?.data?.player?.idler;
    if(!idler||typeof idler!=='object'){
      hkRuntimeSmokeRecord('neighborhood-shape-miss',{reason,responseKeys:hkSmokeObjectKeys(data)});
      return false;
    }
    neighborhoodIdler=idler;
    try{
      hkStateStore.merge({idler,timestamp:data?.timestamp||data?.data?.timestamp},reason);
      playerDocument=hkStateStore.snapshot||playerDocument;
    }catch(_){}
    const smokeBuildings=Array.isArray(idler?.buildings)?idler.buildings:[];
    hkRuntimeSmokeRecord('neighborhood-state',{
      reason,
      responseKeys:hkSmokeObjectKeys(data),
      tapPower:Number(idler?.player_tap_power??0),
      buildings:smokeBuildings.length,
      sample:smokeBuildings.slice(0,6).map(row=>({
        buildingId:String(row?.building_id||'').slice(0,80),
        level:Number(row?.level??0),
        maxLevel:Number(row?.max_level??row?.level??0),
        health:Number(row?.health??0)
      }))
    });
    return true;
  }

  function neighborhoodRewardParts(rewardView) {
    const result=[];
    for(const kind of ['currencies','items']) for(const row of rewardView?.[kind]||[]) {
      const id=String(row?.id||row?.currency_id||row?.item_id||'');
      const quantity=Math.max(0,Number(row?.count??row?.quantity??row?.value??0));
      if(id&&quantity>0)result.push({kind,id,quantity});
    }
    return result;
  }

  function neighborhoodRewardHtml(rewardView) {
    const parts=neighborhoodRewardParts(rewardView);
    return parts.length ? '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:7px">'+parts.map(part=>
      '<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 7px;border:1px solid #304057;border-radius:8px">'+
      fairIconHtml(paymentIcon(part),'hk-price-icon')+'<b>×'+Number(part.quantity).toLocaleString(locale())+'</b><small>'+escapeHtml(gameText(part.id))+'</small></span>'
    ).join('')+'</div>' : '';
  }

  function neighborhoodName(enemy,index) {
    return neighborhoodBaseName()+' '+(index+1);
  }

  function renderNeighborhoodBattles() {
    const box=root?.querySelector('#hk-neighborhood-content'); if(!box)return;
    const saved=neighborhoodSavedIds();
    const selected=new Set(saved===null?neighborhoodEnemies.map(row=>String(row?.building_id||'')).filter(Boolean):saved);
    const rows=neighborhoodEnemies.map((enemy,index)=>{
      const id=String(enemy?.building_id||'');
      const live=neighborhoodLiveRow(id);
      const finalLevel=neighborhoodFinalLevel(enemy);
      const current=Math.max(0,Number(live?.level)||0);
      const unlocked=Math.min(finalLevel,Math.max(0,Number(live?.max_level??live?.level)||0));
      const shown=Math.min(finalLevel,Math.max(current,unlocked));
      const levelDef=neighborhoodLevelDef(enemy,shown);
      const hp=Math.max(0,Number(live?.health)||0);
      const fullHp=Math.max(hp,Math.max(0,Number(levelDef?.health)||0));
      const image=mediaUrl(levelDef?.meta?.image||'');
      return '<label style="display:grid;grid-template-columns:auto 44px 1fr;gap:9px;align-items:center;padding:10px;margin:8px 0;border:1px solid #304057;border-radius:12px;background:#101927">'+
        '<input type="checkbox" data-neighborhood-id="'+escapeHtml(id)+'" '+(selected.has(id)?'checked':'')+'>'+
        (image?'<img src="'+escapeHtml(image)+'" alt="" style="width:42px;height:42px;object-fit:contain">':'<span></span>')+
        '<span><b>'+escapeHtml(neighborhoodName(enemy,index))+'</b><small style="display:block;margin-top:3px">'+
        either('Уровень','Level')+': <b>'+current+'/'+finalLevel+'</b>'+(unlocked>current?' · '+either('открыт','unlocked')+' '+unlocked:'')+
        (fullHp?' · HP '+hp.toLocaleString(locale())+'/'+fullHp.toLocaleString(locale()):'')+'</small>'+
        neighborhoodRewardHtml(levelDef?.reward_view)+'</span></label>';
    }).join('');
    const selectedCount=[...selected].filter(id=>neighborhoodEnemies.some(row=>String(row?.building_id||'')===id)).length;
    box.innerHTML='<div class="hk-clan-head"><div><h3>'+either('Районы','Neighborhoods')+'</h3><small>'+
      either('Neighborhood Battles · живое состояние только из idler/*','Neighborhood Battles · live state only from idler/*')+' · '+HK_NEIGHBORHOOD_BATTLES_REV+
      '</small></div><button id="hk-neighborhood-refresh" class="hk-secondary">'+either('Обновить','Refresh')+'</button></div>'+
      (neighborhoodLastReadAt?'<p class="hk-muted">'+either('Обновлено','Updated')+': '+new Date(neighborhoodLastReadAt).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'})+
      (neighborhoodIdler?.player_tap_power!=null?' · '+either('Сила тапа','Tap power')+': '+Number(neighborhoodIdler.player_tap_power||0).toLocaleString(locale()):'')+'</p>':'')+
      (neighborhoodEnemies.length
        ? '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin:8px 0"><label class="hk-check"><input id="hk-neighborhood-all" type="checkbox" '+(selectedCount===neighborhoodEnemies.length?'checked':'')+'><span>'+either('Выбрать все','Select all')+'</span></label><small>'+either('Выбрано','Selected')+': '+selectedCount+'/'+neighborhoodEnemies.length+'</small></div>'+rows+
          '<button id="hk-neighborhood-run" class="hk-primary" '+(selectedCount?'':'disabled')+'>'+either('Запустить выбранные районы','Run selected Neighborhoods')+'</button>'
        : '<p class="hk-muted">'+either('Откройте вкладку или нажмите «Обновить», чтобы считать угрозы.','Open this tab or press Refresh to read threats.')+'</p>');
    box.querySelector('#hk-neighborhood-refresh')?.addEventListener('click',()=>void refreshModuleLive('neighborhoods',{force:true}));
    box.querySelector('#hk-neighborhood-all')?.addEventListener('change',event=>{
      neighborhoodSaveIds(event.target.checked?neighborhoodEnemies.map(row=>String(row?.building_id||'')).filter(Boolean):[]);
      renderNeighborhoodBattles();
    });
    box.querySelectorAll('[data-neighborhood-id]').forEach(input=>input.addEventListener('change',()=>{
      neighborhoodSaveIds([...box.querySelectorAll('[data-neighborhood-id]:checked')].map(node=>node.dataset.neighborhoodId));
      renderNeighborhoodBattles();
    }));
    box.querySelector('#hk-neighborhood-run')?.addEventListener('click',()=>void runNeighborhoodBattles());
  }

  async function refreshNeighborhoodBattles(force=false) {
    if(!requireLicense())return null;
    try{
      if(!neighborhoodIdler) neighborhoodIdler=hkStateStore.snapshot?.idler||playerDocument?.idler||{buildings:[]};
      const view=await apiJson('/idler/view','GET',null,true,1);
      neighborhoodApplyIdler(view,'neighborhood:view');
      neighborhoodEnemies=(Array.isArray(view?.idler_enemies)?view.idler_enemies:[])
        .filter(row=>String(row?.building_id||'')&&Array.isArray(row?.levels)&&row.levels.length);
      neighborhoodLastReadAt=Date.now();
      renderNeighborhoodBattles();
      if(force)log(either('Районы обновлены','Neighborhoods refreshed')+': '+neighborhoodEnemies.length,(neighborhoodEnemies.length?'ok':'warn'));
      return neighborhoodEnemies;
    }catch(error){
      log(either('Ошибка чтения Районов','Neighborhoods read error')+': '+(error?.message||error),'warn');
      renderNeighborhoodBattles(); return null;
    }
  }

  function neighborhoodTapBatch(health,fullHealth,power) {
    const needed=Math.max(1,Math.ceil(Math.max(0,health)/Math.max(1,power)));
    const damageSafe=Math.max(1,Math.floor((Math.max(1,fullHealth)*0.45)/Math.max(1,power)));
    let clicks=6+Math.floor(Math.random()*33);
    clicks=Math.max(1,Math.min(clicks,needed,damageSafe));
    const tapsPerSecond=5.2+Math.random()*2.2;
    let duration=Math.round(500+(clicks/tapsPerSecond)*1000+(Math.random()-0.5)*180);
    duration=Math.max(800,Math.min(5000,duration));
    return {clicks,duration};
  }

  async function neighborhoodTransientDelay(error) {
    const status=Number(error?.httpStatus||0);
    if(error?.name==='HKRateLimitError'||status===429) {
      await gameRetryDelay(Math.max(1000,Number(error?.retryAfterMs||gameApiCooldownRemainingMs()||GAME_API_429_FALLBACK_COOLDOWN_MS)));
    } else if(status>=500) await gameRetryDelay(1500);
  }

  async function neighborhoodPost(path,body) {
    await hkRunner.waitIfPaused();
    if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
    try{
      const data=await apiJson(path,'POST',body,true,0);
      neighborhoodApplyIdler(data,'neighborhood:'+path);
      return data;
    }catch(error){
      neighborhoodApplyIdler(error?.apiData,'neighborhood:error:'+path);
      throw error;
    }
  }

  function neighborhoodRewardText(data) {
    return neighborhoodRewardParts(data?.idler_reward).map(part=>
      Number(part.quantity).toLocaleString(locale())+' '+gameText(part.id)
    );
  }

  async function runNeighborhoodBattles() {
    if(!requireLicense())return;
    if(hkRunner.running){alert(either('Сначала завершите текущую задачу','Finish the current task first'));return;}
    const freshNeighborhoods=await refreshNeighborhoodBattles(false);
    if(!Array.isArray(freshNeighborhoods)||!freshNeighborhoods.length){log(either('Свежие данные Районов недоступны','Fresh Neighborhood data is unavailable'),'warn');return;}
    const saved=neighborhoodSavedIds();
    const selected=new Set(saved===null?neighborhoodEnemies.map(row=>String(row?.building_id||'')):saved);
    const enemies=neighborhoodEnemies.filter(row=>selected.has(String(row?.building_id||'')));
    if(!enemies.length){log(either('Не выбраны районы для боя','No Neighborhoods selected'),'warn');return;}
    if(!neighborhoodIdler)neighborhoodIdler=hkStateStore.snapshot?.idler||playerDocument?.idler||{buildings:[]};

    const finals=new Map(enemies.map(enemy=>[String(enemy.building_id),neighborhoodFinalLevel(enemy)]));
    const total=[...finals.values()].reduce((sum,value)=>sum+value,0);
    const indexById=new Map(neighborhoodEnemies.map((enemy,index)=>[String(enemy?.building_id||''),index]));
    const names=new Map(enemies.map(enemy=>[String(enemy.building_id),neighborhoodName(enemy,indexById.get(String(enemy.building_id))||0)]));
    const targetFor=(enemy,order)=>({enemy,id:String(enemy.building_id),order,finalLevel:finals.get(String(enemy.building_id))||0});
    const live=id=>neighborhoodLiveRow(id);
    const fullHealthFor=(enemy,level,currentHealth=0)=>Math.max(0,Number(neighborhoodLevelDef(enemy,level)?.health)||0,Number(currentHealth)||0);
    const progress=()=>{
      let done=0;
      for(const [id,finalLevel] of finals){
        const row=live(id);
        done+=Math.min(finalLevel,Math.max(0,Number(row?.max_level??row?.level)||0));
      }
      hkRunner.setStep(hkRunner.state.step,done,total);
      return done;
    };

    const claimTarget=async target=>{
      const before=live(target.id),beforeMax=Math.max(0,Number(before?.max_level??before?.level)||0);
      try{
        const data=await neighborhoodPost('/idler/claim',{building_id:target.id});
        progress();
        const after=live(target.id),afterMax=Math.max(0,Number(after?.max_level??after?.level)||0);
        if(afterMax>beforeMax){
          const rewards=neighborhoodRewardText(data);
          log('✓ '+names.get(target.id)+' · '+either('открыт уровень ','unlocked level ')+afterMax+'/'+target.finalLevel+(rewards.length?' · '+rewards.join(' · '):''),'ok');
        }
        return true;
      }catch(error){
        if(error?.name==='AbortError')throw error;
        const status=Number(error?.httpStatus||0);
        if(status===409)return false;
        if(status===429||status>=500||error?.name==='HKRateLimitError'){await neighborhoodTransientDelay(error);return false;}
        throw error;
      }
    };

    const updateTarget=async target=>{
      try{
        await neighborhoodPost('/idler/update',{building_id:target.id});
        progress(); return true;
      }catch(error){
        if(error?.name==='AbortError')throw error;
        const status=Number(error?.httpStatus||0);
        if(status===409||status===429||status>=500||error?.name==='HKRateLimitError'){await neighborhoodTransientDelay(error);return false;}
        throw error;
      }
    };

    const selectUnlockedLevel=async target=>{
      let row=live(target.id),current=Math.max(0,Number(row?.level)||0),unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
      if(unlocked<=current)return false;
      let desired=Math.min(target.finalLevel,unlocked);
      try{
        await neighborhoodPost('/idler/level',{building_id:target.id,level:desired});
      }catch(error){
        if(error?.name==='AbortError')throw error;
        if(Number(error?.httpStatus||0)!==409)throw error;
        row=live(target.id);current=Math.max(0,Number(row?.level)||0);unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
        if(unlocked<=current)return false;
        desired=Math.min(target.finalLevel,unlocked);
        await neighborhoodPost('/idler/level',{building_id:target.id,level:desired});
      }
      progress();
      const confirmed=Math.max(0,Number(live(target.id)?.level)||0);
      if(confirmed<desired)throw new Error(names.get(target.id)+' · '+either('игровое состояние изменилось','game state changed'));
      log('↗ '+names.get(target.id)+' · '+either('уровень ','level ')+confirmed+'/'+target.finalLevel,'ok');
      return true;
    };

    const syncTargetOnEntry=async target=>{
      const exists=(neighborhoodIdler?.buildings||[]).some(row=>String(row?.building_id||'')===target.id);
      if(!exists)return updateTarget(target);
      try{return await claimTarget(target);}
      catch(error){
        if(error?.name==='AbortError')throw error;
        const message=String(error?.apiData?.message||error?.apiData?.description||error?.message||'').toLowerCase();
        if(Number(error?.httpStatus||0)===406&&message.includes('not found'))return updateTarget(target);
        throw error;
      }
    };

    const confirmPreview=enemies.map(enemy=>{
      const id=String(enemy?.building_id||''),row=live(id),finalLevel=finals.get(id)||0;
      const current=Math.max(0,Number(row?.level)||0),unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
      return '• '+names.get(id)+' · '+Math.max(current,unlocked)+'/'+finalLevel;
    }).join('\n');
    if(!confirm(either(
      'Запустить выбранные Районы: '+enemies.length+'?\n\n'+confirmPreview+'\n\nСила тапа: '+Math.max(0,Number(neighborhoodIdler?.player_tap_power)||0).toLocaleString(locale())+'\n\nСкрипт будет собирать накопленный прогресс, переключать открытые уровни и выполнять боевые тапы.',
      'Run selected Neighborhoods: '+enemies.length+'?\n\n'+confirmPreview+'\n\nTap power: '+Math.max(0,Number(neighborhoodIdler?.player_tap_power)||0).toLocaleString(locale())+'\n\nThe script will claim accumulated progress, switch unlocked levels and perform battle taps.'
    )))return;
    runtimeSmokeResetModule('neighborhood');
    hkRuntimeSmokeRecord('neighborhood-start',{
      selected:enemies.length,
      totalLevels:total,
      tapPower:Number(neighborhoodIdler?.player_tap_power??0)
    });
    try{
      const liveView=await apiJson('/idler/view','GET',null,true,1);
      neighborhoodApplyIdler(liveView,'neighborhood:run-preflight');
    }catch(error){
      hkRuntimeSmokeRecord('neighborhood-error',{
        stage:'run-preflight',
        name:String(error?.name||''),
        status:Number(error?.httpStatus||0),
        message:String(error?.message||error||'').slice(0,500)
      });
      log(either('Не удалось повторно проверить Районы перед запуском','Could not revalidate Neighborhoods before start')+': '+(error?.message||error),'warn');
      return;
    }
    hkRunner.start({title:either('Районы','Neighborhoods'),total,step:either('Синхронизация угроз','Syncing threats'),pausable:true,stoppable:true});
    try{
      progress();
      for(let order=0;order<enemies.length;order++){
        await hkRunner.waitIfPaused();
        const target=targetFor(enemies[order],order);
        hkRunner.setStep(names.get(target.id),hkRunner.state.done,total);
        await syncTargetOnEntry(target);
        let row=live(target.id),current=Math.max(0,Number(row?.level)||0),unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
        if(unlocked>current)await selectUnlockedLevel(target);
        row=live(target.id);current=Math.max(0,Number(row?.level)||0);unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
        const health=Math.max(0,Number(row?.health)||0),fullHealth=fullHealthFor(target.enemy,current,health);
        log(names.get(target.id)+' · '+either('уровень ','level ')+current+'/'+target.finalLevel+(unlocked>current?' · '+either('открыт ','unlocked ')+unlocked:'')+' · HP '+health.toLocaleString(locale())+'/'+fullHealth.toLocaleString(locale()),'info');
      }

      log(either('Сила тапа','Tap power')+': '+Math.max(0,Number(neighborhoodIdler?.player_tap_power)||0).toLocaleString(locale()),'info');

      let turnIndex=0;
      while(true){
        await hkRunner.waitIfPaused();
        if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
        let target=null;
        for(let step=0;step<enemies.length;step++){
          const order=(turnIndex+step)%enemies.length,candidate=targetFor(enemies[order],order),row=live(candidate.id);
          const current=Math.max(0,Number(row?.level)||0),unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
          if(current<candidate.finalLevel||unlocked<candidate.finalLevel){target=candidate;turnIndex=order;break;}
        }
        if(!target)break;

        hkRunner.setStep(names.get(target.id),hkRunner.state.done,total);
        await syncTargetOnEntry(target);
        let row=live(target.id),current=Math.max(0,Number(row?.level)||0),unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
        if(unlocked>current){await selectUnlockedLevel(target);turnIndex=(target.order+1)%enemies.length;continue;}
        if(current>=target.finalLevel&&unlocked>=target.finalLevel){turnIndex=(target.order+1)%enemies.length;continue;}

        let didTap=false;
        while(true){
          await hkRunner.waitIfPaused();
          if(hkRunner.signal?.aborted)throw new DOMException('Aborted','AbortError');
          row=live(target.id);current=Math.max(0,Number(row?.level)||0);unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
          if(unlocked>current){await selectUnlockedLevel(target);break;}
          if(current>=target.finalLevel)break;
          const power=Math.max(0,Number(neighborhoodIdler?.player_tap_power)||0);
          const health=Math.max(0,Number(row?.health)||0),fullHealth=fullHealthFor(target.enemy,current,health);
          if(power<=0)throw new Error(names.get(target.id)+' · Tap Power 0');
          const batch=neighborhoodTapBatch(health,fullHealth,power);
          hkRunner.setStep(names.get(target.id)+' · '+batch.clicks+' '+either('тапов','taps'),hkRunner.state.done,total);
          await gameRetryDelay(batch.duration);
          const beforeMax=unlocked;
          try{
            const data=await neighborhoodPost('/idler/tap',{building_id:target.id,quantity:batch.clicks,duration:batch.duration});
            didTap=true;progress();
            const fresh=live(target.id),afterMax=Math.max(0,Number(fresh?.max_level??fresh?.level)||0),afterHealth=Math.max(0,Number(fresh?.health)||0);
            if(afterMax>beforeMax){
              const rewards=neighborhoodRewardText(data);
              log('✓ '+names.get(target.id)+' · '+either('победа','defeated')+' · '+either('открыт ','unlocked ')+afterMax+'/'+target.finalLevel+(rewards.length?' · '+rewards.join(' · '):''),'ok');
              const afterCurrent=Math.max(0,Number(fresh?.level)||0);
              if(afterMax>afterCurrent)await selectUnlockedLevel(target);
              break;
            }
            log('✓ '+names.get(target.id)+' · '+batch.clicks+' '+either('тапов','taps')+' · HP '+afterHealth.toLocaleString(locale())+'/'+fullHealth.toLocaleString(locale()),'ok');
          }catch(error){
            if(error?.name==='AbortError')throw error;
            const status=Number(error?.httpStatus||0),message=String(error?.apiData?.message||error?.apiData?.description||error?.message||'').toLowerCase();
            if(status===409){
              row=live(target.id);current=Math.max(0,Number(row?.level)||0);unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
              if(unlocked>current){await selectUnlockedLevel(target);break;}
              if(message.includes('claim accumulated idler rewards')){
                await claimTarget(target);
                row=live(target.id);current=Math.max(0,Number(row?.level)||0);unlocked=Math.max(0,Number(row?.max_level??row?.level)||0);
                if(unlocked>current){await selectUnlockedLevel(target);break;}
              }
              continue;
            }
            if(status===429||status>=500||error?.name==='HKRateLimitError'){await neighborhoodTransientDelay(error);continue;}
            throw error;
          }
        }
        if(didTap)await updateTarget(target);
        turnIndex=(target.order+1)%enemies.length;
      }

      progress();
      neighborhoodLastReadAt=Date.now();
      hkRuntimeSmokeRecord('neighborhood-complete',{
        tapPower:Number(neighborhoodIdler?.player_tap_power??0),
        buildings:Array.isArray(neighborhoodIdler?.buildings)?neighborhoodIdler.buildings.length:0
      });
      renderNeighborhoodBattles();
      hkRunner.finish(either('Все выбранные районы завершены','All selected Neighborhoods completed'));
      log(either('Районы завершены','Neighborhoods completed'),'ok');
    }catch(error){
      hkRuntimeSmokeRecord('neighborhood-error',{
        name:String(error?.name||''),
        status:Number(error?.httpStatus||0),
        message:String(error?.message||error||'').slice(0,500)
      });
      neighborhoodLastReadAt=Date.now();
      renderNeighborhoodBattles();
      if(error?.name==='AbortError'){hkRunner.reset();log(either('Бои в Районах остановлены','Neighborhood Battles stopped'),'warn');}
      else{hkRunner.fail(error);log(either('Ошибка Районов','Neighborhoods error')+': '+(error?.message||error),'bad');}
    }
  }

  // HK_ALLIANCE_RATINGS_V2
  // Alliance totals are built from the clans that belong to each alliance.
  // Defense/defence ("Оборона" in the game) comes from the alliance/clan list;
  // clan power and influence are joined by clan name from the game's clan leaderboards.
  let discoveredClanPowerLeaderboardType = '';

  function allianceNameKey(value) {
    return String(value || '').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase();
  }

  function allianceObjectName(value) {
    if(!value||typeof value!=='object')return '';
    const node=value.alliance||value.alliance_info||value.allianceInfo||value;
    return firstText(
      node?.name,node?.title,node?.alliance_name,node?.allianceName,
      value.alliance_name,value.allianceName,value.name,value.title
    );
  }

  function clanObjectName(value) {
    if(!value||typeof value!=='object')return '';
    const node=value.clan||value.clan_info||value.clanInfo||value;
    return firstText(
      node?.name,node?.title,node?.clan_name,node?.clanName,
      value.clan_name,value.clanName,value.name,value.title
    );
  }

  function clanObjectId(value) {
    if(!value||typeof value!=='object')return '';
    const node=value.clan||value.clan_info||value.clanInfo||value;
    return firstText(
      node?.clan_id,node?.clanId,node?.id,node?.uuid,
      value.clan_id,value.clanId,value.id,value.uuid
    );
  }

  function clanMemberCount(value) {
    if(!value||typeof value!=='object')return null;
    const node=value.clan||value.clan_info||value.clanInfo||value;
    return metricFromObject(node,[
      'members_count','membersCount','member_count','memberCount',
      'players_count','playersCount','participants_count','participantsCount',
      'members','participants'
    ]) ?? metricFromObject(value,[
      'members_count','membersCount','member_count','memberCount',
      'players_count','playersCount','participants_count','participantsCount'
    ]);
  }

  function directClanMetric(value,kind) {
    if(!value||typeof value!=='object')return null;
    const node=value.clan||value.clan_info||value.clanInfo||value;
    const keys=ALLIANCE_RATING_METRICS[kind]||[];
    return metricFromObject(node,keys) ?? metricFromObject(value,keys);
  }

  function likelyClanArray(list) {
    if(!Array.isArray(list)||!list.length||list.length>20)return false;
    let named=0,clanish=0;
    for(const item of list.slice(0,8)){
      if(!item||typeof item!=='object')continue;
      if(clanObjectName(item))named+=1;
      const keys=new Set([
        ...Object.keys(item),
        ...Object.keys(item.clan||item.clan_info||item.clanInfo||{})
      ].map(String));
      if(
        item.clan||item.clan_info||item.clanInfo||
        keys.has('clan_id')||keys.has('clanId')||
        keys.has('defense')||keys.has('defence')||
        keys.has('defense_points')||keys.has('defence_points')||
        keys.has('player_level')||keys.has('hamsters_power')||
        keys.has('members_count')||keys.has('membersCount')
      )clanish+=1;
    }
    return named>0 && (clanish>0 || named===list.length);
  }

  function allianceClanRows(value) {
    if(!value||typeof value!=='object')return [];
    const sources=[value.alliance||null,value.alliance_info||null,value.allianceInfo||null,value].filter(Boolean);
    const preferred=[
      'clans','alliance_clans','allianceClans','clan_list','clanList',
      'member_clans','memberClans','participants'
    ];
    for(const source of sources){
      for(const key of preferred){
        const list=source?.[key];
        if(likelyClanArray(list))return list;
      }
    }
    for(const source of sources){
      for(const child of Object.values(source||{})){
        if(likelyClanArray(child))return child;
      }
    }
    const singles=[];
    for(const source of sources){
      for(const key of ['core_clan','coreClan','leader_clan','leaderClan','clan']){
        const row=source?.[key];
        if(row&&typeof row==='object'&&clanObjectName(row))singles.push(row);
      }
    }
    return singles;
  }

  function allianceRecords(documentValue) {
    const output=[],seen=new Set();
    for(const value of deepObjects(documentValue)){
      if(!value||typeof value!=='object')continue;
      const name=allianceObjectName(value);
      const clans=allianceClanRows(value);
      if(!name||!clans.length)continue;
      const parsedClans=[];
      const clanSeen=new Set();
      for(const raw of clans){
        const clanName=clanObjectName(raw);
        if(!clanName)continue;
        const clanKey=allianceNameKey(clanName);
        if(!clanKey||clanSeen.has(clanKey))continue;
        clanSeen.add(clanKey);
        parsedClans.push({
          name:clanName,
          key:clanKey,
          id:clanObjectId(raw),
          members:clanMemberCount(raw),
          power:directClanMetric(raw,'alliance_power'),
          influence:directClanMetric(raw,'alliance_influence'),
          defense:directClanMetric(raw,'alliance_defense')
        });
      }
      if(!parsedClans.length)continue;
      const key=allianceNameKey(name);
      if(!key||seen.has(key))continue;
      seen.add(key);
      output.push({
        name,key,clans:parsedClans,
        power:metricFromObject(value.alliance||value,ALLIANCE_RATING_METRICS.alliance_power),
        influence:metricFromObject(value.alliance||value,ALLIANCE_RATING_METRICS.alliance_influence),
        defense:metricFromObject(value.alliance||value,ALLIANCE_RATING_METRICS.alliance_defense)
      });
    }
    return output;
  }

  function clanMetricRows(documentValue,kind) {
    const arrays=leaderboardArrays(documentValue);
    for(const list of arrays){
      const rows=list.map((row,index)=>{
        if(!row||typeof row!=='object')return null;
        const entity=row.clan||row.clan_info||row.clanInfo||row;
        const name=clanObjectName(row);
        if(!name)return null;
        const rank=Math.trunc(firstFinite(row.rank,row.place,row.position,entity.rank)||index+1);
        let value=null;
        if(kind==='power'){
          value=metricFromObject(entity,ALLIANCE_RATING_METRICS.alliance_power)
            ?? metricFromObject(row,ALLIANCE_RATING_METRICS.alliance_power)
            ?? finiteMetric(row.value) ?? finiteMetric(row.score);
        }else{
          value=metricFromObject(entity,ALLIANCE_RATING_METRICS.alliance_influence)
            ?? metricFromObject(row,ALLIANCE_RATING_METRICS.alliance_influence)
            ?? finiteMetric(row.value) ?? finiteMetric(row.score);
        }
        return rank>=1&&value!==null?{rank,name,value}:null;
      }).filter(Boolean);
      if(rows.length)return rows.slice(0,200);
    }
    return [];
  }

  function clanRowsMap(rows) {
    return new Map((Array.isArray(rows)?rows:[])
      .filter(row=>row&&row.name&&Number.isFinite(Number(row.value)))
      .map(row=>[allianceNameKey(row.name),Number(row.value)]));
  }

  async function readClanPowerRows() {
    const candidates=discoveredClanPowerLeaderboardType
      ? [discoveredClanPowerLeaderboardType]
      : ['clan_hamsters_power_lb','clan_hamster_power_lb','clan_power_lb','clans_hamsters_power_lb'];
    for(const leaderboard_type of candidates){
      try{
        const value=await apiJson('/leaderboard','POST',{leaderboard_type},true,1);
        const rows=clanMetricRows(value,'power');
        if(rows.length){
          discoveredClanPowerLeaderboardType=leaderboard_type;
          return rows;
        }
      }catch(_){}
    }
    return [];
  }

  function completeAllianceSum(alliance,metric,map) {
    const direct=finiteMetric(alliance?.[metric]);
    if(direct!==null&&direct>0)return direct;
    let total=0,covered=0;
    for(const clan of alliance.clans||[]){
      let value=finiteMetric(clan?.[metric]);
      if((value===null||value<=0)&&map)value=finiteMetric(map.get(clan.key));
      if(value===null||value<0)continue;
      total+=value;covered+=1;
    }
    // Never publish a partial total. A missing clan must not silently reduce
    // an alliance's power/influence/defense.
    return covered===(alliance.clans||[]).length&&covered>0?total:null;
  }

  function buildAllianceRatings(allianceDocument,clanInfluenceRows,clanPowerRows) {
    const alliances=allianceRecords(allianceDocument);
    const influenceMap=clanRowsMap(clanInfluenceRows);
    const powerMap=clanRowsMap(clanPowerRows);
    const totals=alliances.map(alliance=>({
      name:alliance.name,
      clans:alliance.clans.length,
      members:alliance.clans.reduce((sum,row)=>sum+(Number(row.members)||0),0),
      alliance_power:completeAllianceSum(alliance,'power',powerMap),
      alliance_influence:completeAllianceSum(alliance,'influence',influenceMap),
      alliance_defense:completeAllianceSum(alliance,'defense',null)
    }));
    const result={};
    for(const kind of ['alliance_power','alliance_influence','alliance_defense']){
      const rows=totals
        .filter(row=>Number.isFinite(row[kind])&&row[kind]>0)
        .sort((a,b)=>b[kind]-a[kind]||a.name.localeCompare(b.name))
        .slice(0,100)
        .map((row,index)=>({rank:index+1,name:row.name,value:row[kind]}));
      if(rows.length)result[kind]=rows;
    }
    try{
      recordDiagnostic('alliance-rating-v2',{
        alliances:alliances.length,
        power:result.alliance_power?.length||0,
        influence:result.alliance_influence?.length||0,
        defense:result.alliance_defense?.length||0,
        powerLeaderboard:discoveredClanPowerLeaderboardType||''
      });
    }catch(_){}
    return result;
  }

  async function readPublicRatings() {
    const ratings={};
    let clanInfluenceRows=[];

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'player_level_lb'},true,1);
      const rows=normalizePublicRanking(value,'influence');
      if(rows.length)ratings.influence=rows;
    }catch(_){}

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'hamsters_power_lb'},true,1);
      const rows=normalizePublicRanking(value,'power');
      if(rows.length)ratings.power=rows;
    }catch(_){}

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'clan_player_level_lb'},true,1);
      clanInfluenceRows=clanMetricRows(value,'influence');
      const publicRows=normalizePublicRanking(value,'clans');
      if(publicRows.length)ratings.clans=publicRows;
    }catch(_){}

    try{
      const [allianceDocument,clanPowerRows]=await Promise.all([
        apiJson('/alliance/list','GET',null,true,1),
        readClanPowerRows()
      ]);
      Object.assign(ratings,buildAllianceRatings(allianceDocument,clanInfluenceRows,clanPowerRows));
    }catch(error){
      try{recordDiagnostic('alliance-rating-v2-error',{message:error?.message||String(error)});}catch(_){}
    }
    return ratings;
  }

  // HK_PUBLIC_WAR_ALLIANCE_V4
  // Exact schema verified against Hamster King client v1.77.2.2017.
  function hkV4Key(value){
    return String(value||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase();
  }

  function hkV4Number(...values){
    for(const raw of values){
      if(raw===null||raw===undefined||raw==='')continue;
      const value=Number(raw);
      if(Number.isFinite(value)&&value>=0)return value;
    }
    return null;
  }

  function hkV4EndTimer(value){
    const timer=Number(value);
    return Number.isFinite(timer)&&timer>0 ? Math.floor((Date.now()+timer)/1000) : 0;
  }

  async function readPublicWarV4(){
    try{
      const value=await apiJson('/clan/active_battles','GET',null,true,1);
      const ownClan=firstText(
        playerDocument?.player?.clan?.name,
        playerDocument?.clan?.name,
        playerDocument?.player?.clan_name,
        'Top King'
      );
      const attack=value?.alliance_attack_war;
      if(attack&&typeof attack==='object'){
        const current=hkV4Number(attack.health);
        const maximum=hkV4Number(attack.initial_health);
        const war={
          our_clan:ownClan,
          opponent:firstText(attack.name,attack.defender_clan_name,'—'),
          our_score:null,opponent_score:null,status:'active',
          started_at:0,ends_at:hkV4EndTimer(attack.end_timer),
          war_id:String(attack.id||''),war_type:'attack'
        };
        if(current!==null)war.opponent_hp=Math.round(current);
        if(maximum!==null&&maximum>0)war.opponent_hp_max=Math.round(maximum);
        return {read:true,war};
      }
      const defenses=Array.isArray(value?.clan_defense_wars)
        ? value.clan_defense_wars.filter(row=>row&&typeof row==='object')
        : [];
      if(defenses.length){
        defenses.sort((a,b)=>Number(a.end_timer||0)-Number(b.end_timer||0));
        const defense=defenses[0];
        const current=hkV4Number(defense.health);
        const maximum=hkV4Number(defense.initial_health);
        const war={
          our_clan:ownClan,
          opponent:firstText(defense.name,defense.attacker_alliance_name,'—'),
          our_score:null,opponent_score:null,status:'active',
          started_at:0,ends_at:hkV4EndTimer(defense.end_timer),
          war_id:String(defense.id||''),war_type:'defense'
        };
        if(current!==null)war.our_hp=Math.round(current);
        if(maximum!==null&&maximum>0)war.our_hp_max=Math.round(maximum);
        return {read:true,war};
      }
      return {read:true,war:null};
    }catch(error){
      try{recordDiagnostic('public-war-v4-error',{message:error?.message||String(error)});}catch(_){}
      return {read:false,war:null};
    }
  }

  function hkV4AllianceList(value){
    const list=Array.isArray(value?.result)
      ? value.result
      : Array.isArray(value?.data?.result) ? value.data.result : [];
    return list.map(row=>({
      id:String(row?.id||''),
      name:firstText(row?.name,row?.title),
      defense:hkV4Number(row?.defense_point)??0,
      members:hkV4Number(row?.members_count)??0
    })).filter(row=>row.id&&row.name);
  }

  function hkV4AllianceClans(value){
    const raw=[
      value?.core_clan,
      ...(Array.isArray(value?.satellite_clans)?value.satellite_clans:[])
    ].filter(row=>row&&typeof row==='object');
    const result=[],seen=new Set();
    for(const row of raw){
      const name=firstText(row.name,row.clan_name,row.title);
      const key=hkV4Key(name);
      const id=String(row.id||row.clan_id||'');
      if(!name||!id||!key||seen.has(key))continue;
      seen.add(key);
      result.push({
        id,name,key,
        defense:hkV4Number(row.defense_point)??0,
        members:hkV4Number(row.number_of_members,row.members_count)??0
      });
    }
    return result;
  }

  async function hkV4AllianceMembers(alliances){
    const map=new Map();
    let cursor=0;
    const count=Math.min(2,Math.max(1,alliances.length));
    const workers=Array.from({length:count},async()=>{
      while(cursor<alliances.length){
        const alliance=alliances[cursor++];
        try{
          const value=await apiJson(
            '/alliance/members?alliance_id='+encodeURIComponent(alliance.id),
            'GET',null,true,1
          );
          const clans=hkV4AllianceClans(value);
          if(clans.length)map.set(alliance.id,clans);
        }catch(_){}
        await new Promise(resolve=>setTimeout(resolve,120));
      }
    });
    await Promise.all(workers);
    return map;
  }

  function hkV4MapRows(rows){
    return new Map((Array.isArray(rows)?rows:[])
      .filter(row=>row&&row.name&&Number.isFinite(Number(row.value)))
      .map(row=>[hkV4Key(row.name),Number(row.value)]));
  }

  async function hkV4ClanPowerRows(){
    for(const leaderboard_type of [
      'clan_hamsters_power_lb',
      'clan_hamster_power_lb',
      'clan_power_lb',
      'clans_hamsters_power_lb'
    ]){
      try{
        const value=await apiJson('/leaderboard','POST',{leaderboard_type},true,1);
        const rows=normalizePublicRanking(value,'clans');
        if(rows.length){
          try{recordDiagnostic('alliance-power-leaderboard-v4',{leaderboard_type,rows:rows.length});}catch(_){}
          return rows;
        }
      }catch(_){}
    }
    return [];
  }

  async function hkV4ClanPowerFromMembers(clan,cache){
    if(cache.has(clan.id))return cache.get(clan.id);
    let result=null;
    try{
      const value=await apiJson('/clan/members?clan_id='+encodeURIComponent(clan.id),'GET',null,true,1);
      const members=Array.isArray(value?.clan_members)
        ? value.clan_members
        : Array.isArray(value?.members) ? value.members : [];
      if(members.length){
        let sum=0,covered=0;
        for(const member of members){
          const power=hkV4Number(
            member?.hamsters_power,member?.power,
            member?.player?.hamsters_power,member?.player?.power
          );
          if(power===null)continue;
          sum+=power;covered+=1;
        }
        if(covered===members.length&&covered>0)result=sum;
      }
    }catch(_){}
    cache.set(clan.id,result);
    return result;
  }

  async function hkV4AllianceTotals(alliances,membersByAlliance,influenceMap,powerMap){
    const rows=[];
    const powerCache=new Map();
    for(const alliance of alliances){
      const clans=membersByAlliance.get(alliance.id)||[];
      if(!clans.length){
        if(alliance.defense>0)rows.push({
          name:alliance.name,defense:alliance.defense,influence:null,power:null
        });
        continue;
      }

      let influence=0,influenceCovered=0;
      let power=0,powerCovered=0;
      for(const clan of clans){
        const iv=hkV4Number(influenceMap.get(clan.key));
        if(iv!==null){influence+=iv;influenceCovered+=1}

        let pv=hkV4Number(powerMap.get(clan.key));
        if(pv===null)pv=await hkV4ClanPowerFromMembers(clan,powerCache);
        if(pv!==null){power+=pv;powerCovered+=1}
      }

      rows.push({
        name:alliance.name,
        defense:alliance.defense>0?alliance.defense:clans.reduce((sum,row)=>sum+Number(row.defense||0),0),
        influence:influenceCovered===clans.length&&clans.length?influence:null,
        power:powerCovered===clans.length&&clans.length?power:null
      });
      await new Promise(resolve=>setTimeout(resolve,80));
    }
    return rows;
  }

  function hkV4Rank(totals,key){
    return totals
      .filter(row=>Number.isFinite(row[key])&&row[key]>0)
      .sort((a,b)=>b[key]-a[key]||a.name.localeCompare(b.name))
      .slice(0,100)
      .map((row,index)=>({rank:index+1,name:row.name,value:row[key]}));
  }

  async function readPublicRatingsV4(){
    const ratings={};
    let clanInfluenceRows=[];

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'player_level_lb'},true,1);
      const rows=normalizePublicRanking(value,'influence');
      if(rows.length)ratings.influence=rows;
    }catch(_){}

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'hamsters_power_lb'},true,1);
      const rows=normalizePublicRanking(value,'power');
      if(rows.length)ratings.power=rows;
    }catch(_){}

    try{
      const value=await apiJson('/leaderboard','POST',{leaderboard_type:'clan_player_level_lb'},true,1);
      clanInfluenceRows=normalizePublicRanking(value,'clans');
      if(clanInfluenceRows.length)ratings.clans=clanInfluenceRows;
    }catch(_){}

    try{
      const allianceDocument=await apiJson('/alliance/list','GET',null,true,1);
      const alliances=hkV4AllianceList(allianceDocument);
      const [membersByAlliance,clanPowerRows]=await Promise.all([
        hkV4AllianceMembers(alliances),
        hkV4ClanPowerRows()
      ]);
      const totals=await hkV4AllianceTotals(
        alliances,
        membersByAlliance,
        hkV4MapRows(clanInfluenceRows),
        hkV4MapRows(clanPowerRows)
      );
      const defense=hkV4Rank(totals,'defense');
      const influence=hkV4Rank(totals,'influence');
      const power=hkV4Rank(totals,'power');
      if(defense.length)ratings.alliance_defense=defense;
      if(influence.length)ratings.alliance_influence=influence;
      if(power.length)ratings.alliance_power=power;
      try{
        recordDiagnostic('public-alliance-v4',{
          alliances:alliances.length,
          detailed:[...membersByAlliance.values()].filter(rows=>rows.length).length,
          defense:defense.length,influence:influence.length,power:power.length
        });
      }catch(_){}
    }catch(error){
      try{recordDiagnostic('public-alliance-v4-error',{message:error?.message||String(error)});}catch(_){}
    }
    return ratings;
  }

  async function collectPublicSnapshot(force = false) {
    recordDiagnostic('public-snapshot-server-only',{force:!!force,revision:HK_PUBLIC_SNAPSHOT_CLIENT_REV});
    return null;
  }

  async function loadFair() {
    if (!requireLicense()) return;
    try {
      log('Считываю ярмарки…');
      playerDocument = await apiJson('/player/me', 'POST');
      fairDocument = playerDocument;
      shopViewDocument = await apiJson('/shop/view', 'GET');
      fairCatalog = normalizeFairCatalog(shopViewDocument);
      const visibleFairs = fairStatesForView();
      if (!visibleFairs.some(state => state.id === selectedFairId)) selectedFairId = visibleFairs[0]?.id || '';
      selectedFairLots.clear();
      selectedFairSlotRules.clear();
      renderFair();
      log(`Ярмарка считана: ${visibleFairs.length} разделов, ${fairCatalog.length} лотов`, 'ok');
    } catch (error) { log(`Ошибка ярмарки: ${error.message}`, 'bad'); }
  }

  function costVisual(cost, multiplier = 1) {
    const parts = costParts(cost);
    if (!parts.length) return '<span>0</span>';
    return parts.map(part => `${fairIconHtml(paymentIcon(part), 'hk-price-icon')}<b>${(part.quantity * multiplier).toLocaleString(locale())}</b>`).join('');
  }

  function addProjectedCost(target, part, multiplier = 1) {
    if (!part?.id) return;
    const key = `${part.kind}|${part.id}`;
    const current = target.get(key) || {...part, quantity:0};
    current.quantity += Math.max(0, Number(part.quantity || 0)) * Math.max(0, Number(multiplier || 0));
    target.set(key, current);
  }

  function walletForecastHtml(parts) {
    const values = [...parts.values()].filter(part => part?.id).sort((a, b) => a.id.localeCompare(b.id));
    if (!values.length) return '';
    return `<div class="hk-wallet-forecast">${values.map(part => {
      const balance = walletAmount(part.id);
      const spend = Math.max(0, Number(part.quantity || 0));
      const known = balance !== null;
      return `<div class="hk-wallet-row">
        <span class="hk-wallet-currency">${fairIconHtml(paymentIcon(part), 'hk-price-icon')}<b>${escapeHtml(paymentLabel(part.id))}</b></span>
        <span>${tr('balance')}: <b>${known ? balance.toLocaleString(locale()) : '—'}</b> · ${either('Макс. возможный расход','Maximum possible spend')}: <b>${spend.toLocaleString(locale())}</b></span>
      </div>`;
    }).join('')}</div>`;
  }

  function fairRerollCapacity(state = fairState(selectedFairId), allowPremium = Boolean(root?.querySelector('#hk-fair-premium-reroll')?.checked), documentValue = playerDocument) {
    const cost = state?.fair_reroll_cost || {};
    if (!safeReroll(cost, allowPremium)) {
      return {count:0, free:false, problems:[either('цена прокрутки запрещена текущими настройками','reroll cost is blocked by current settings')]};
    }
    const parts = costParts(cost).filter(part => part.quantity > 0);
    if (!parts.length) return {count:Number.MAX_SAFE_INTEGER, free:true, problems:[]};

    let walletLimit = Number.MAX_SAFE_INTEGER;
    const problems = [];
    for (const part of parts) {
      const balance = walletAmount(part.id, documentValue);
      if (balance === null) {
        problems.push(`${paymentLabel(part.id)}: ${either('баланс не определён','balance is unknown')}`);
        walletLimit = 0;
        continue;
      }
      walletLimit = Math.min(walletLimit, Math.floor(Math.max(0, balance) / part.quantity));
    }
    if (!walletLimit || walletLimit === Number.MAX_SAFE_INTEGER) {
      return {count:Math.max(0, walletLimit === Number.MAX_SAFE_INTEGER ? 0 : walletLimit), free:false, problems};
    }

    let allowed = walletLimit;
    if (!isEventFairState(state)) {
      let low = 0, high = walletLimit;
      while (low < high) {
        const middle = Math.ceil((low + high + 1) / 2);
        const decision = budgetDecision(cost, 'fair', middle, documentValue, {allowPremiumOverride:allowPremium});
        if (decision.allowed) low = middle;
        else high = middle - 1;
      }
      allowed = low;
      if (!allowed) {
        const decision = budgetDecision(cost, 'fair', 1, documentValue, {allowPremiumOverride:allowPremium});
        problems.push(...decision.problems);
      }
    }
    return {count:Math.max(0, Math.trunc(allowed)), free:false, problems:[...new Set(problems)]};
  }

  function fairRerollCapacityLabel(state = fairState(selectedFairId), allowPremium = Boolean(root?.querySelector('#hk-fair-premium-reroll')?.checked)) {
    if (!state) return either('Прокрутки: ярмарка не выбрана','Rerolls: no fair selected');
    const plan = fairRerollCapacity(state, allowPremium, playerDocument);
    if (plan.free) return either('Прокрутки: без расхода валюты','Rerolls: no currency cost');
    const parts = costParts(state?.fair_reroll_cost).filter(part => part.quantity > 0);
    const currency = parts.map(part => `${paymentLabel(part.id)} ${part.quantity.toLocaleString(locale())}`).join(' + ');
    if (plan.count > 0) return either(`Прокрутки: до ${plan.count.toLocaleString(locale())} по текущему балансу · ${currency}`, `Rerolls: up to ${plan.count.toLocaleString(locale())} by current balance · ${currency}`);
    return either(`Прокрутки недоступны${plan.problems.length ? ': ' + plan.problems.join('; ') : ''}`, `Rerolls unavailable${plan.problems.length ? ': ' + plan.problems.join('; ') : ''}`);
  }

  function fairBuyTargetValue(rawValue = root?.querySelector('#hk-fair-buy-limit')?.value, exactLots = fairComboSettings().exactLots) {
    const raw = Math.min(999, Math.max(1, Math.trunc(Number(rawValue || 1))));
    if (!exactLots) return raw;
    return Math.min(999, Math.max(3, Math.floor(raw / 3) * 3));
  }

  function syncFairBuyTarget(normalize = false) {
    const input = root?.querySelector('#hk-fair-buy-limit');
    const exactLots = fairComboSettings().exactLots;
    const target = fairBuyTargetValue(input?.value, exactLots);
    if (input) {
      input.min = exactLots ? '3' : '1';
      input.step = exactLots ? '3' : '1';
      if (normalize) input.value = String(target);
    }
    const hint = root?.querySelector('#hk-fair-buy-limit-hint');
    if (hint) hint.textContent = exactLots
      ? either(`Основные покупки: ${target}. В режиме 3/6/9 цель идёт целыми тройками; бонусные нижние ячейки в это число не входят.`,
          `Main purchases: ${target}. In 3/6/9 mode the target uses complete groups of three; lower bonus cells are counted separately.`)
      : either(`Основные покупки: ${target}. Бонусные нижние ячейки считаются отдельно.`,
          `Main purchases: ${target}. Lower bonus cells are counted separately.`);
    return target;
  }

  function fairBonusThreshold(quantity) {
    const value = Number(quantity || 0);
    return value === 5 ? 3 : value === 10 ? 6 : value === 30 ? 9 : 0;
  }

  function fairBonusMaximumPurchases(quantity, buyLimit) {
    const threshold = fairBonusThreshold(quantity);
    const target = Math.max(0, Math.trunc(Number(buyLimit || 0)));
    if (!threshold || target < threshold) return 0;
    // A fair board opens one lower bonus at 3, 6 and 9 bought main cells.
    // After nine main cells the next board can open the same thresholds again.
    return 1 + Math.floor((target - threshold) / 9);
  }

  function fairBonusRowsForQuantity(state, quantity) {
    const wanted = Number(quantity || 0);
    const rows = fairRowsForState(state);
    const currentBonusRows = fairSlotOptions(state)
      .filter(({index}) => index >= 9 && index < 12)
      .map(({slot}) => fairCatalog.find(row => row.lotId === String(slot?.shop_lot_id || '')))
      .filter(row => row && Number(row.rewardQuantity || 0) === wanted);
    const rewardIds = new Set(currentBonusRows.map(row => row.rewardId).filter(Boolean));
    let candidates = rewardIds.size
      ? rows.filter(row => Number(row.rewardQuantity || 0) === wanted && rewardIds.has(row.rewardId))
      : currentBonusRows;
    // Fallback is deliberately conservative: if the current encrypted slot
    // does not expose its reward family yet, use every same-quantity row from
    // this fair and take the highest cost per currency below.
    if (!candidates.length) candidates = rows.filter(row => Number(row.rewardQuantity || 0) === wanted);
    return candidates.filter(row => row?.safe);
  }

  function fairProjectedPurchaseCosts(state = fairState(selectedFairId), buyLimit = fairBuyTargetValue(root?.querySelector('#hk-fair-buy-limit')?.value), exactLots = fairComboSettings().exactLots) {
    const totals = new Map();
    const rows = fairRowsForState(state);
    const selectedRows = rows.filter(row => selectedFairLots.has(row.lotId));
    const maximumMainLots = new Map();
    for (const row of selectedRows) for (const part of costParts(row.cost)) {
      const key = `${part.kind}|${part.id}`;
      const current = maximumMainLots.get(key);
      if (!current || part.quantity > current.quantity) maximumMainLots.set(key, {...part});
    }
    for (const part of maximumMainLots.values()) addProjectedCost(totals, part, selectedRows.length ? buyLimit : 0);

    if (exactLots) {
      const availableBonus = new Set(availableFairBonusLots(exactLots));
      for (const quantity of [5, 10, 30]) {
        if (!availableBonus.has(quantity) || !selectedFairBonusLots.has(quantity)) continue;
        const purchases = fairBonusMaximumPurchases(quantity, buyLimit);
        if (!purchases) continue;
        const maximumBonusLots = new Map();
        for (const row of fairBonusRowsForQuantity(state, quantity)) for (const part of costParts(row.cost)) {
          const key = `${part.kind}|${part.id}`;
          const current = maximumBonusLots.get(key);
          if (!current || part.quantity > current.quantity) maximumBonusLots.set(key, {...part});
        }
        for (const part of maximumBonusLots.values()) addProjectedCost(totals, part, purchases);
      }
    }
    return totals;
  }

  function fairProjectedCosts() {
    const state = fairState(selectedFairId);
    const buyLimit = fairBuyTargetValue(root?.querySelector('#hk-fair-buy-limit')?.value);
    const exactLots = fairComboSettings().exactLots;
    const totals = fairProjectedPurchaseCosts(state, buyLimit, exactLots);
    const allowPremium = Boolean(root?.querySelector('#hk-fair-premium-reroll')?.checked);
    const rerollPlan = fairRerollCapacity(state, allowPremium, playerDocument);
    if (!rerollPlan.free && rerollPlan.count > 0) {
      for (const part of costParts(state?.fair_reroll_cost)) addProjectedCost(totals, part, rerollPlan.count);
    }
    return totals;
  }

  function renderFair() {
    if (!fairTypes || !fairLots) return;
    if (!fairCatalog.length) {
      fairTypes.innerHTML = `<p class="hk-muted">${tr('readFirst')}</p>`;
      fairLots.innerHTML = '';
      const currencyBar = root?.querySelector('#hk-fair-currencies'); if (currencyBar) currencyBar.innerHTML = '';
      updateFairControls(); return;
    }
    const states = fairStatesForView();
    fairTypes.innerHTML = states.map(state => {
      const firstLot = fairRowsForState(state).find(row => (state.fair_slots || []).some(slot => slot.shop_lot_id === row.lotId)) || fairRowsForState(state)[0];
      return `<button class="hk-fair-type ${state.id === selectedFairId ? 'selected' : ''}" data-fair="${escapeHtml(state.id)}">
        ${fairIconHtml(firstLot?.icon || '')}<span>${costVisual(state.fair_reroll_cost)}</span></button>`;
    }).join('') || `<p class="hk-muted">${tr('noFairs')}</p>`;
    fairTypes.querySelectorAll('[data-fair]').forEach(button => button.onclick = () => {
      selectedFairId = button.dataset.fair; selectedFairLots.clear(); selectedFairSlotRules.clear(); selectedFairCurrency = ''; renderFair();
    });
    const query = clean(root?.querySelector('#hk-fair-search')?.value).toLowerCase();
    const allRows = fairRowsForState(fairState(selectedFairId));
    const currencyIds = [...new Set(allRows.flatMap(row => costParts(row.cost).map(part => part.id)).filter(Boolean))];
    if (selectedFairCurrency && !currencyIds.includes(selectedFairCurrency)) selectedFairCurrency = '';
    const currencyBar = root?.querySelector('#hk-fair-currencies');
    if (currencyBar) {
      currencyBar.innerHTML = `<button class="${selectedFairCurrency ? '' : 'selected'}" data-currency="">${tr('all')}</button>` + currencyIds.map(id => {
        const part = allRows.flatMap(row => costParts(row.cost)).find(value => value.id === id);
        return `<button class="${selectedFairCurrency === id ? 'selected' : ''}" data-currency="${escapeHtml(id)}">${fairIconHtml(paymentIcon(part), 'hk-price-icon')}<span>${escapeHtml(paymentLabel(id))}</span></button>`;
      }).join('');
      currencyBar.querySelectorAll('[data-currency]').forEach(button => button.onclick = () => { selectedFairCurrency = button.dataset.currency; renderFair(); });
    }
    const rows = allRows.filter(row => (!selectedFairCurrency || costParts(row.cost).some(part => part.id === selectedFairCurrency)) &&
      (!query || `${row.name} ${row.rewardId} ${row.lotId}`.toLowerCase().includes(query)));
    fairLots.innerHTML = rows.map(row => `<button class="hk-lot ${selectedFairLots.has(row.lotId) ? 'selected' : ''} ${row.premium ? 'premium' : ''} ${row.safe ? '' : 'locked'}" data-lot="${escapeHtml(row.lotId)}">
      ${row.premium ? '<i class="hk-premium-mark">💎</i>' : ''}${fairIconHtml(row.icon)}<b>×${row.rewardQuantity.toLocaleString(locale())}</b><span>${costVisual(row.cost)}</span>${row.safe ? '' : `<small>${tr('blocked')}</small>`}</button>`).join('') || `<p class="hk-muted">${tr('noLots')}</p>`;
    fairLots.querySelectorAll('[data-lot]').forEach(button => button.onclick = () => {
      const row = fairCatalog.find(value => value.lotId === button.dataset.lot);
      if (!row?.safe) { log(either('Этот лот заблокирован: неизвестная валюта', 'This lot is blocked: unknown currency'), 'warn'); return; }
      if (selectedFairLots.has(row.lotId)) {
        selectedFairLots.delete(row.lotId);
        selectedFairSlotRules.delete(row.lotId);
      } else {
        selectedFairLots.add(row.lotId);
        const options = fairSlotOptions();
        selectedFairSlotRules.set(row.lotId, {regular:options.some(value => !value.vip), vip:options.some(value => value.vip)});
      }
      renderFair();
    });
    renderFairSlotRules();
    updateFairControls();
  }

  function fairSlotOptions(state = fairState(selectedFairId)) {
    const fairConfigs = shopViewDocument?.fairs || shopViewDocument?.fair || [];
    const config = (Array.isArray(fairConfigs) ? fairConfigs : []).find(value => String(value?.id) === String(state?.id));
    const metaById = new Map((config?.fair_slots || []).map(slot => [String(slot?.id), slot]));
    return [...(state?.fair_slots || [])]
      .sort((a, b) => Number(a?.id ?? 0) - Number(b?.id ?? 0))
      .map((slot, index) => ({slot, index, key:String(index), vip:Boolean(slot?.is_vip || metaById.get(String(slot?.id))?.is_vip)}));
  }

  function renderFairSlotRules() {
    if (!fairSlotRules) return;
    const slots = fairSlotOptions();
    if (!selectedFairLots.size || !slots.length) {
      fairSlotRules.innerHTML = '';
      fairSlotRules.style.display = 'none';
      return;
    }
    fairSlotRules.style.display = '';
    const hasRegular = slots.some(value => !value.vip);
    const hasVip = slots.some(value => value.vip);
    for (const lotId of selectedFairLots) {
      if (!selectedFairSlotRules.has(lotId)) selectedFairSlotRules.set(lotId, {regular:hasRegular, vip:hasVip});
    }
    fairSlotRules.innerHTML = `<h3>${tr('allowedCells')}</h3><p class="hk-muted">${tr('selectCellsHint')}</p>` +
      [...selectedFairLots].map(lotId => {
        const row = fairCatalog.find(value => value.lotId === lotId);
        const allowed = selectedFairSlotRules.get(lotId) || {regular:hasRegular, vip:hasVip};
        return `<div class="hk-slot-rule"><div class="hk-slot-product">${fairIconHtml(row?.icon || '', 'hk-price-icon')}<b>×${Number(row?.rewardQuantity || 0).toLocaleString(locale())}</b></div>
          <div class="hk-slot-buttons"><button class="${allowed.regular ? 'selected' : ''}" data-rule-lot="${escapeHtml(lotId)}" data-rule-group="regular" ${hasRegular ? '' : 'disabled'}>${tr('regularSlots')}: ${tr(allowed.regular ? 'yes' : 'no')}</button>
          <button class="vip ${allowed.vip ? 'selected' : ''}" data-rule-lot="${escapeHtml(lotId)}" data-rule-group="vip" ${hasVip ? '' : 'disabled'}>♛ ${tr('vipSlots')}: ${tr(allowed.vip ? 'yes' : 'no')}</button></div></div>`;
      }).join('');
    fairSlotRules.querySelectorAll('[data-rule-lot]').forEach(button => button.onclick = () => {
      const allowed = selectedFairSlotRules.get(button.dataset.ruleLot) || {regular:hasRegular, vip:hasVip};
      allowed[button.dataset.ruleGroup] = !allowed[button.dataset.ruleGroup];
      selectedFairSlotRules.set(button.dataset.ruleLot, allowed);
      renderFairSlotRules(); updateFairControls();
    });
  }

  function updateFairControls() {
    syncFairBuyTarget(false);
    const selected = root?.querySelector('#hk-fair-selected');
    if (selected) selected.innerHTML = `<b>${tr('selectedLots', {n:selectedFairLots.size})}</b>${walletForecastHtml(fairProjectedCosts())}`;
    const rerollAuto = root?.querySelector('#hk-fair-reroll-auto');
    if (rerollAuto) rerollAuto.textContent = fairRerollCapacityLabel();
    const start = root?.querySelector('#hk-fair-start');
    const rulesValid = [...selectedFairLots].every(lotId => {
      const rule = selectedFairSlotRules.get(lotId); return Boolean(rule?.regular || rule?.vip);
    });
    if (start) start.disabled = fairRunning || !selectedFairId || !selectedFairLots.size || !rulesValid;
    const stop = root?.querySelector('#hk-fair-stop');
    if (stop) stop.disabled = !fairRunning;
  }

  function fairComboSettings() {
    return {
      exactLots:Math.max(0, Number(root?.querySelector('#hk-fair-exact-lots')?.value || 0))
    };
  }

  function availableFairBonusLots(exactLots = fairComboSettings().exactLots) {
    const maximum = Math.max(0, Math.trunc(Number(exactLots || 0)));
    return maximum >= 9 ? [5, 10, 30] : maximum >= 6 ? [5, 10] : maximum >= 3 ? [5] : [];
  }

  function renderFairBonusChoices() {
    const box = root?.querySelector('#hk-fair-bonus-lots'); if (!box) return;
    const available = new Set(availableFairBonusLots());
    box.innerHTML = `<span>${tr('fairBonusLots')}</span><div>${[5,10,30].map(quantity =>
      `<label class="hk-check ${available.has(quantity) ? 'available' : 'unavailable'}"><input type="checkbox" data-fair-bonus="${quantity}" ${available.has(quantity) && selectedFairBonusLots.has(quantity) ? 'checked' : ''} ${available.has(quantity) ? '' : 'disabled'}><b>×${quantity}</b></label>`).join('')}</div>`;
    box.querySelectorAll('[data-fair-bonus]').forEach(input => input.onchange = () => {
      const quantity = Number(input.dataset.fairBonus);
      if (input.checked) selectedFairBonusLots.add(quantity); else selectedFairBonusLots.delete(quantity);
      updateFairControls();
    });
  }

  function fairPresets() {
    const value = load().fairPresets;
    return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  }

  function refreshFairPresets(selectName = '') {
    if (!fairPresetSelect) return;
    const names = Object.keys(fairPresets()).sort((a, b) => a.localeCompare(b, locale()));
    fairPresetSelect.innerHTML = `<option value="">${tr('fairSavedSettings')}</option>` +
      names.map(name => `<option value="${escapeHtml(name)}" ${name === selectName ? 'selected' : ''}>${escapeHtml(name)}</option>`).join('');
  }

  function fairPresetSnapshot() {
    return {
      fairId:selectedFairId,
      lots:[...selectedFairLots],
      slotGroups:Object.fromEntries([...selectedFairSlotRules].map(([lotId, groups]) => [lotId, {regular:Boolean(groups.regular), vip:Boolean(groups.vip)}])),
      currency:selectedFairCurrency,
      exactLots:fairComboSettings().exactLots, bonusLots:[...selectedFairBonusLots],
      buyLimit:fairBuyTargetValue(root?.querySelector('#hk-fair-buy-limit')?.value),
      premiumReroll:Boolean(root?.querySelector('#hk-fair-premium-reroll')?.checked)
    };
  }

  function saveFairPreset(existingName = '') {
    if (!selectedFairId || !selectedFairLots.size) {
      alert(either('Сначала выберите ярмарку и хотя бы один товар', 'Choose a fair and at least one item first')); return;
    }
    const name = existingName || prompt(tr('settingName'));
    if (!name?.trim()) return;
    const normalized = name.trim();
    const all = fairPresets();
    all[normalized] = fairPresetSnapshot();
    save({fairPresets:all});
    refreshFairPresets(normalized);
    log(tr('settingSaved', {name:normalized}), 'ok');
  }

  function loadFairPreset(name) {
    const preset = fairPresets()[name];
    if (!preset) return;
    if (!fairCatalog.length) {
      alert(either('Сначала нажмите «Считать ярмарку»', 'Press “Read fair” first'));
      refreshFairPresets(); return;
    }
    if (fairStates().some(state => String(state.id) === String(preset.fairId))) selectedFairId = String(preset.fairId);
    const available = new Set(fairRowsForState(fairState(selectedFairId)).map(row => row.lotId));
    selectedFairLots = new Set((preset.lots || []).map(String).filter(id => available.has(id)));
    selectedFairSlotRules.clear();
    const options = fairSlotOptions();
    for (const lotId of selectedFairLots) {
      const groups = preset.slotGroups?.[lotId];
      if (groups && typeof groups === 'object') {
        selectedFairSlotRules.set(lotId, {regular:Boolean(groups.regular), vip:Boolean(groups.vip)});
      } else {
        const oldCells = new Set(Array.isArray(preset.slotRules?.[lotId]) ? preset.slotRules[lotId].map(String) : options.map(value => value.key));
        selectedFairSlotRules.set(lotId, {
          regular:options.some(value => !value.vip && oldCells.has(value.key)),
          vip:options.some(value => value.vip && oldCells.has(value.key))
        });
      }
    }
    selectedFairCurrency = String(preset.currency || '');
    const buy = root?.querySelector('#hk-fair-buy-limit'); if (buy) buy.value = Math.max(1, Number(preset.buyLimit || 1));
    const premium = root?.querySelector('#hk-fair-premium-reroll'); if (premium) premium.checked = Boolean(preset.premiumReroll);
    selectedFairBonusLots = new Set(Array.isArray(preset.bonusLots) ? preset.bonusLots.map(Number).filter(value => [5,10,30].includes(value)) : [5,10,30]);
    renderFair();
    const exact=root?.querySelector('#hk-fair-exact-lots'); if(exact) exact.value=['0','3','6','9'].includes(String(preset.exactLots)) ? String(preset.exactLots) : '0';
    syncFairBuyTarget(true);
    renderFairBonusChoices();
    updateFairControls();
    refreshFairPresets(name);
    log(tr('settingLoaded', {name}), 'ok');
  }

  function deleteFairPreset() {
    const name = fairPresetSelect?.value;
    if (!name || !confirm(tr('deleteSetting', {name}))) return;
    const all = fairPresets(); delete all[name]; save({fairPresets:all}); refreshFairPresets();
  }

  function costDocumentFromParts(parts) {
    const result = {items:[], currencies:[]};
    for (const part of parts || []) if (part?.id && part.quantity > 0) result[part.kind === 'currencies' ? 'currencies' : 'items'].push({id:part.id, quantity:part.quantity});
    return result;
  }

  async function executeFairPurchase(row, slot, allowPremium = false) {
    // Event fairs have their own currency/amount controls in this tab. Do not
    // let the global daily budget reject the whole event run because one of
    // the selected variants costs diamonds. The normal fair remains covered
    // by the unified budget.
    if (!isEventFairState(fairState(selectedFairId))) {
      const decision = budgetDecision(row.cost, 'fair', 1, playerDocument, {allowPremiumOverride:allowPremium});
      if (!decision.allowed) throw new Error(decision.problems.join('; '));
    }
    const beforeDoc = playerDocument;
    const before = new Map(costParts(row.cost).map(part => [part.id, walletAmount(part.id, beforeDoc)]));
    fairDocument = await apiJson('/shop/buy', 'POST', {shop_lot_id:row.lotId, payment_type:'INTERNAL', fair_id:selectedFairId, slot_id:slot.id, lotName:row.name, lotDescription:''});
    updateWalletFromResponse(fairDocument, row.cost);
    for (const part of costParts(row.cost)) appendExpense({section:'fair', lotId:row.lotId, name:gameText(row.name) || row.name,
      currencyId:part.id, amount:part.quantity, balanceBefore:before.get(part.id), balanceAfter:walletAmount(part.id, playerDocument), status:'ok', result:'purchased'});
  }

  function fairRunnerNote(message,type='') { hkRunner.note(message,type); }

  function fairRerollStateSignature(state) {
    return JSON.stringify((state?.fair_slots || []).map((slot,index) => [
      index,
      String(slot?.id ?? ''),
      String(slot?.shop_lot_id ?? ''),
      slot?.is_bought === true ? 1 : 0
    ]));
  }

  function fairRerollTimeoutError(error) {
    const message=String(error?.message || error || '');
    return /\/fair\/reroll/i.test(message) && /(тайм-аут|timeout|timed out|время ожидания)/i.test(message);
  }

  async function reconcileFairRerollTimeout(beforeSignature,beforeBalances,rerollCost) {
    let lastDocument=playerDocument;
    for (const delay of [1200,2500,5000]) {
      await gameRetryDelay(delay);
      try {
        const documentValue=await hkAuthoritativePlayerRead('fair-reroll-timeout-reconcile');
        lastDocument=documentValue || lastDocument;
        fairDocument=lastDocument;
        const currentState=fairState(selectedFairId,lastDocument);
        if (!currentState) continue;
        const stateChanged=fairRerollStateSignature(currentState)!==beforeSignature;
        const charged=costParts(rerollCost).some(part => {
          const before=beforeBalances.get(part.id);
          const after=walletAmount(part.id,lastDocument);
          return before!==null && before!==undefined && after!==null && after!==undefined &&
            Number(after) <= Number(before) - Math.max(0,Number(part.quantity || 0));
        });
        if (stateChanged || charged) return {applied:true,documentValue:lastDocument,state:currentState};
      } catch (probeError) {
        recordDiagnostic('fair-reroll-timeout-probe-error',{error:probeError?.message || String(probeError)});
      }
    }
    return {applied:false,documentValue:lastDocument,state:fairState(selectedFairId,lastDocument)};
  }

  async function runFair() {
    if (!requireLicense() || fairRunning || !selectedFairLots.size) return;
    if ([...selectedFairLots].some(lotId => {
      const rule = selectedFairSlotRules.get(lotId); return !(rule?.regular || rule?.vip);
    })) {
      alert(tr('noCells')); return;
    }
    try {
      playerDocument = await apiJson('/player/me', 'POST');
      fairDocument = playerDocument;
      shopViewDocument = await apiJson('/shop/view', 'GET');
      fairCatalog = normalizeFairCatalog(shopViewDocument);
      const missingSelected = [...selectedFairLots].filter(lotId => !fairCatalog.some(row => row.lotId === lotId && row.safe));
      if (missingSelected.length) {
        renderFair();
        alert(either('Каталог ярмарки изменился. Проверьте выбранные лоты ещё раз.','The fair catalog changed. Review the selected lots again.'));
        return;
      }
    } catch (error) {
      log(either('Не удалось обновить ярмарку перед запуском','Could not refresh the fair before starting') + ': ' + (error?.message || error),'bad');
      return;
    }
    const buyLimit = syncFairBuyTarget(true);
    const allowPremium = root.querySelector('#hk-fair-premium-reroll').checked;
    const combo = fairComboSettings();
    const allowedBonusLots = new Set(availableFairBonusLots(combo.exactLots));
    let state = fairState(selectedFairId);
    if (!safeReroll(state?.fair_reroll_cost, allowPremium)) { alert(either('Прокрутка заблокирована: цена небезопасна.', 'Reroll is blocked: unsafe cost.')); return; }
    const initialRerollPlan = fairRerollCapacity(state, allowPremium, playerDocument);
    const initialRerollText = initialRerollPlan.free
      ? either('без расхода валюты','no currency cost')
      : initialRerollPlan.count.toLocaleString(locale());
    const projectedPurchaseCosts = fairProjectedPurchaseCosts(state, buyLimit, combo.exactLots);
    const maximumCrystalLotCost = Math.max(0, Number(projectedPurchaseCosts.get('currencies|cur_prem')?.quantity || 0));
    const crystalNotice = maximumCrystalLotCost
      ? either(`\nМаксимум кристаллов на покупки: ${maximumCrystalLotCost.toLocaleString(locale())} 💎`, `\nMaximum crystals for purchases: ${maximumCrystalLotCost.toLocaleString(locale())} 💎`)
      : '';
    if (!confirm(language === 'en'
      ? `Start searching for selected lots?\n\nMain purchases: ${buyLimit}${combo.exactLots ? `\n3/6/9 groups: max ${combo.exactLots} main purchases per board; smaller complete groups are also allowed; bonuses are separate` : ''}\nRerolls: by available currency (now: ${initialRerollText})${crystalNotice}`
      : `Запустить поиск выбранных лотов?\n\nОсновных покупок: ${buyLimit}${combo.exactLots ? `\nГруппы 3/6/9: максимум ${combo.exactLots} основных покупок за поле; меньшие полные группы тоже разрешены; бонусы отдельно` : ''}\nПрокрутки: по доступной валюте (сейчас: ${initialRerollText})${crystalNotice}`)) return;
    if (hkRunner.running) { alert(either('Сначала завершите текущую задачу','Finish the current task first')); return; }
    hkRunner.start({title:either('Ярмарка','Fair'),total:buyLimit,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
    fairRunning = true; fairStop = false; updateFairControls();
    let bought = 0, bonusBought = 0, rerolls = 0, authRetries = 0, stopReason = '';
    try {
      playerDocument = await apiJson('/player/me', 'POST');
      fairDocument = playerDocument;
      while (!fairStop && bought < buyLimit) {
        if (hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
        await hkRunner.waitIfPaused();
        hkRunner.setStep(either('Поиск и покупка лотов','Searching and buying lots'), bought, buyLimit);
        if (combo.exactLots && buyLimit - bought < 3) {
          stopReason = either(`Остановка: осталось ${buyLimit - bought} основных покупок, а для режима 3/6/9 нужна полная группа из трёх.`,
            `Stopped: ${buyLimit - bought} main purchases remain, but 3/6/9 mode requires a complete group of three.`);
          fairRunnerNote(stopReason, 'warn');
          break;
        }
        state = fairState(selectedFairId);
        if (!state) throw new Error('Выбранная ярмарка больше недоступна');
        let purchased = false;
        const options = fairSlotOptions(state);
        const targets = options.filter(({slot, vip, index}) => {
          // A combination spans all nine main cells: six regular and three
          // VIP. Encrypted bonus cells start after them and never count toward
          // the 3/6/9 group itself.
          if (index >= 9 || slot.is_bought || !selectedFairLots.has(String(slot.shop_lot_id))) return false;
          const groups = selectedFairSlotRules.get(String(slot.shop_lot_id));
          return !groups || (vip ? groups.vip : groups.regular);
        });
        const maximumGroup = combo.exactLots
          ? Math.floor(Math.min(combo.exactLots, buyLimit - bought) / 3) * 3
          : 0;
        const matchedTargets = maximumGroup ? targets.slice(0, maximumGroup) : [];
        const groupSize = Math.floor(matchedTargets.length / 3) * 3;
        const purchaseTargets = matchedTargets.slice(0, groupSize);
        if (combo.exactLots && groupSize >= 3) {
          const totalCosts = new Map();
          for (const {slot} of purchaseTargets) {
            const row = fairCatalog.find(value => value.lotId === String(slot.shop_lot_id));
            for (const part of costParts(row?.cost)) totalCosts.set(part.id, (totalCosts.get(part.id) || 0) + part.quantity);
          }
          const insufficient = [...totalCosts].filter(([id, amount]) => {
            const balance = walletAmount(id, playerDocument);
            return balance === null || balance < amount;
          }).map(([id, amount]) => {
            const balance = walletAmount(id, playerDocument);
            return `${paymentLabel(id)}: ${balance === null ? either('остаток не определён','balance is unknown') : `${balance.toLocaleString(locale())} / ${amount.toLocaleString(locale())}`}`;
          });
          if (insufficient.length) {
            fairRunnerNote(either(`Комбинация ${purchaseTargets.length} не выкуплена — не хватает средств: ${insufficient.join('; ')}`,
              `Combination ${purchaseTargets.length} was not purchased — insufficient funds: ${insufficient.join('; ')}`), 'warn');
          } else {
            for (const {slot} of purchaseTargets) {
              const row = fairCatalog.find(value => value.lotId === String(slot.shop_lot_id));
              if (!row?.safe) continue;
              fairRunnerNote(`Лоты ${purchaseTargets.length}: покупка…`);
              await executeFairPurchase(row, slot, allowPremium);
              bought++; purchased = true; authRetries = 0;
            }
            // The last /shop/buy response may still contain the previous set
            // of encrypted cells. Refresh once after the completed group so
            // newly opened bonus slots are visible before we try to buy them.
            playerDocument = await apiJson('/player/me', 'POST');
            fairDocument = playerDocument;
            state = fairState(selectedFairId);
            const refreshedOptions = fairSlotOptions(state);
            const boughtMainCells = refreshedOptions.filter(({slot,index}) => index < 9 && slot.is_bought).length;
            const openedBonusSlots = Math.min(3, Math.floor(boughtMainCells / 3));
            const collars = refreshedOptions.filter(({slot,index}) => {
              if (index < 9 || index >= 9 + openedBonusSlots || slot.is_bought) return false;
              const row = fairCatalog.find(value => value.lotId === String(slot.shop_lot_id));
              const quantity = Number(row?.rewardQuantity || 0);
              return allowedBonusLots.has(quantity) && selectedFairBonusLots.has(quantity);
            });
            for (const {slot} of collars) {
              const row = fairCatalog.find(value => value.lotId === String(slot.shop_lot_id));
              if (!row?.safe) continue;
              fairRunnerNote(`Открытый слот ${Number(slot.id) + 1}: покупка…`);
              await executeFairPurchase(row, slot, allowPremium);
              bonusBought++; purchased = true; authRetries = 0;
            }
          }
        }
        if (!combo.exactLots) for (const {slot, vip} of options) {
          if (fairStop || bought >= buyLimit || slot.is_bought || !selectedFairLots.has(String(slot.shop_lot_id))) continue;
          const allowedGroups = selectedFairSlotRules.get(String(slot.shop_lot_id));
          if (allowedGroups && !(vip ? allowedGroups.vip : allowedGroups.regular)) continue;
          const row = fairCatalog.find(value => value.lotId === String(slot.shop_lot_id));
          if (!row?.safe) continue;
          fairRunnerNote(`Лот найден. Покупка ${bought + 1}/${buyLimit}…`);
          try {
            await executeFairPurchase(row, slot, allowPremium);
            bought++; purchased = true; authRetries = 0; fairRunnerNote(`Куплено ${bought}/${buyLimit}`, 'ok');
          } catch (error) {
            if (/HTTP 401|unauthorized/i.test(error.message) && authRetries++ < 2) { playerDocument = await apiJson('/player/me', 'POST'); fairDocument = playerDocument; continue; }
            throw error;
          }
        }
        if (purchased) continue;
        if (!safeReroll(state.fair_reroll_cost, allowPremium)) throw new Error('Цена прокрутки изменилась и стала небезопасной');
        const rerollPlan = fairRerollCapacity(state, allowPremium, playerDocument);
        if (!rerollPlan.free && rerollPlan.count <= 0) {
          stopReason = either(`Остановка: валюта прокрутки закончилась или достигнут резерв${rerollPlan.problems.length ? ' · ' + rerollPlan.problems.join('; ') : ''}`,
            `Stopped: reroll currency is exhausted or reserve reached${rerollPlan.problems.length ? ' · ' + rerollPlan.problems.join('; ') : ''}`);
          fairRunnerNote(stopReason, 'warn');
          break;
        }
        fairRunnerNote(rerollPlan.free
          ? either(`Лота нет. Бесплатная прокрутка ${rerolls + 1}…`, `No matching lot. Free reroll ${rerolls + 1}…`)
          : either(`Лота нет. Прокрутка ${rerolls + 1} · доступно по балансу: ${rerollPlan.count}`, `No matching lot. Reroll ${rerolls + 1} · affordable now: ${rerollPlan.count}`));
        if (!isEventFairState(state)) {
          const rerollDecision = budgetDecision(state.fair_reroll_cost, 'fair', 1, playerDocument, {allowPremiumOverride:allowPremium});
          if (!rerollDecision.allowed) throw new Error(rerollDecision.problems.join('; '));
        }
        const rerollCost = state.fair_reroll_cost;
        const before = new Map(costParts(rerollCost).map(part => [part.id, walletAmount(part.id, playerDocument)]));
        const beforeSignature = fairRerollStateSignature(state);
        try {
          fairDocument = await apiJson('/fair/reroll', 'POST', {fair_id:selectedFairId});
          updateWalletFromResponse(fairDocument, rerollCost);
          for (const part of costParts(rerollCost)) appendExpense({section:'fair', lotId:`reroll:${selectedFairId}`, name:either('Прокрутка ярмарки','Fair reroll'),
            currencyId:part.id, amount:part.quantity, balanceBefore:before.get(part.id), balanceAfter:walletAmount(part.id, playerDocument), status:'ok', result:'rerolled'});
          rerolls++; authRetries = 0;
        }
        catch (error) {
          if (/HTTP 401|unauthorized/i.test(error.message) && authRetries++ < 2) { playerDocument = await apiJson('/player/me', 'POST'); fairDocument = playerDocument; continue; }
          if (fairRerollTimeoutError(error)) {
            fairRunnerNote(either('Прокрутка отвечает дольше обычного. Проверяю состояние без повторной траты…','Reroll is taking longer than usual. Verifying state without spending twice…'),'warn');
            const reconciled=await reconcileFairRerollTimeout(beforeSignature,before,rerollCost);
            playerDocument=reconciled.documentValue || playerDocument;
            fairDocument=playerDocument;
            if (reconciled.applied) {
              for (const part of costParts(rerollCost)) appendExpense({section:'fair', lotId:`reroll:${selectedFairId}`, name:either('Прокрутка ярмарки','Fair reroll'),
                currencyId:part.id, amount:part.quantity, balanceBefore:before.get(part.id), balanceAfter:walletAmount(part.id, playerDocument), status:'ok', result:'rerolled-timeout-reconciled'});
              rerolls++; authRetries = 0;
              fairRunnerNote(either('Прокрутка подтверждена по live-состоянию. Продолжаю.','Reroll confirmed from live state. Continuing.'),'ok');
            } else {
              authRetries = 0;
              fairRunnerNote(either('После тайм-аута Ярмарка и баланс не изменились. Повторяю прокрутку безопасно.','After the timeout the Fair and balance are unchanged. Retrying the reroll safely.'),'warn');
              continue;
            }
          } else {
            throw error;
          }
        }
        await gameRetryDelay(550);
      }
      if (fairStop || hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
      playerDocument = await hkAuthoritativePlayerRead('fair-complete');
      fairDocument = playerDocument;
      if (bought >= buyLimit) {
        hkRunner.finish(either('Цель Ярмарки достигнута','Fair target reached'));
        log(either(
          `Цель Ярмарки достигнута: основных покупок ${bought}/${buyLimit}, бонусных ${bonusBought}, прокруток ${rerolls}`,
          `Fair target reached: main purchases ${bought}/${buyLimit}, bonus purchases ${bonusBought}, rerolls ${rerolls}`
        ), 'ok');
      } else {
        const reason = stopReason || either('Ярмарка остановлена до достижения цели','Fair stopped before reaching the target');
        hkRunner.finish(reason);
        log(either(
          `${reason} Итог: основных покупок ${bought}/${buyLimit}, бонусных ${bonusBought}, прокруток ${rerolls}`,
          `${reason} Result: main purchases ${bought}/${buyLimit}, bonus purchases ${bonusBought}, rerolls ${rerolls}`
        ), 'warn');
      }
    } catch (error) {
      if (error?.name === 'AbortError') {
        hkRunner.reset();
        log(either(
          `Ярмарка остановлена. Итог: основных покупок ${bought}/${buyLimit}, бонусных ${bonusBought}, прокруток ${rerolls}`,
          `Fair stopped. Result: main purchases ${bought}/${buyLimit}, bonus purchases ${bonusBought}, rerolls ${rerolls}`
        ),'warn');
      } else {
        hkRunner.fail(error);
        log(either(
          `Аварийная остановка Ярмарки: ${error?.message || error}. Итог: основных покупок ${bought}/${buyLimit}, бонусных ${bonusBought}, прокруток ${rerolls}`,
          `Fair failed: ${error?.message || error}. Result: main purchases ${bought}/${buyLimit}, bonus purchases ${bonusBought}, rerolls ${rerolls}`
        ),'bad');
      }
    } finally { fairRunning = false; fairStop = false; renderFair(); }
  }

  function ordinaryShopGroup(lot) {
    const lotId = String(lot?.id || '').toLowerCase();
    // Each Resources card has one visible base lot plus three real hidden
    // package commands (_10, _50 and _100). They are separate shop_lot_id
    // values, not a quantity parameter on the base purchase.
    if (/^mf_shoplot_itempack_[1-5](?:_(?:10|50|100))?$/.test(lotId)) return 'resources';
    // Renovation contains the ten individual materials (two materials per tier).
    // The combined mf_shoplot_pit_remort_all pack is intentionally excluded.
    if (/^mf_shoplot_pit_remort_(?:beams|nails)_[1-5]$/.test(lotId)) return 'renovation';
    // Invest Deals contains the two daily building-helper offers only.
    if (/^mf_shoplot_building_helpers_offer_0[12]$/.test(lotId)) return 'invest';
    return '';
  }

  function quantitySelectOptions(maximum, selected) {
    const max = Math.max(0, Math.trunc(Number(maximum || 0)));
    const current = Math.min(max, Math.max(0, Math.trunc(Number(selected || 0))));
    const values = new Set([0, current, max]);
    for (let value = 1; value <= Math.min(max, 20); value++) values.add(value);
    for (const value of [25, 50, 100, 250, 500]) if (value <= max) values.add(value);
    return [...values].sort((a, b) => a - b).map(value => `<option value="${value}" ${value === current ? 'selected' : ''}>${value}</option>`).join('');
  }

  function captureActiveEventCode() {
    let code = '';
    const activeIcon = document.querySelector('.picture-counter.special-counter img[src*="/special_events/icons/timer_event_"]');
    const iconMatch = String(activeIcon?.getAttribute('src') || '').match(/timer_event_([^/?]+?)_icon(?:\.|\?)/i);
    if (iconMatch?.[1]) code = iconMatch[1].toLowerCase();
    // On a first installation the player may already be inside the current
    // event page. Use its visible cards only until the map icon has supplied
    // and persisted the authoritative current event code.
    if (!code && !activeEventCode) {
      const visibleCard = [...document.querySelectorAll('[data-lot-id^="mf_shoplot_"]')].find(element =>
        visible(element) && /^mf_shoplot_(?:daily_|finite_|infinite_)?event_[^_]+_/i.test(String(element.getAttribute('data-lot-id') || '')));
      const cardMatch = String(visibleCard?.getAttribute('data-lot-id') || '').match(/^mf_shoplot_(?:daily_|finite_|infinite_)?event_([^_]+)_/i);
      if (cardMatch?.[1]) code = cardMatch[1].toLowerCase();
    }
    if (code && code !== activeEventCode) {
      activeEventCode = code;
      save({activeEventCode:code});
      if (shopViewDocument) {
        shopRows = normalizeRegularShop();
        if (root && selectedShopSection === 'regular') renderShop();
      }
    }
    return activeEventCode;
  }

  function normalizeRegularShop(shopDocument = shopViewDocument, playerDoc = playerDocument) {
    const currentEventCode = captureActiveEventCode();
    const limits = new Map();
    const playerLimits = playerDoc?.shop_lot_limits || playerDoc?.player?.shop_lot_limits || [];
    for (const item of playerLimits) limits.set(String(item?.shop_lot_id || ''), Math.max(0, Number(item?.number_of_purchase || 0)));
    const shopLots = shopDocument?.shop_lots || [];
    const lotsById = new Map(shopLots.map(lot => [String(lot?.id || ''), lot]));
    return shopLots.flatMap(lot => {
      const rawView = lot?.lot_view || {};
      const lotId = String(lot.id || '');
      const currentEventLot = Boolean(currentEventCode) &&
        lotId.toLowerCase().includes(`_event_${currentEventCode}_`);
      const resourceMatch = lotId.match(/^(mf_shoplot_itempack_[1-5])(?:_(10|50|100))?$/i);
      const resourceBaseLot = resourceMatch ? lotsById.get(resourceMatch[1]) : null;
      const resourceBaseView = resourceBaseLot?.lot_view || {};
      const declaredMultiplier = Boolean(resourceMatch?.[2]) &&
        (resourceBaseView.multiplier_lots || []).map(String).includes(lotId);
      // Hidden multiplier lots contain only their resulting package quantity.
      // Reuse the visible parent card for its name/icon/content, while keeping
      // the child's own lot ID, cost and package quantity for the purchase.
      if (resourceMatch?.[2] && !declaredMultiplier) return [];
      const view = declaredMultiplier ? resourceBaseView : rawView;
      if (String(view.type || '').toLowerCase() === 'fair' || lot.external_cost) return [];
      const lotLimits = lot.limit || [];
      // The standard Resources and Renovation cards have no daily purchase
      // limit in the game. Keep only our explicitly allow-listed ordinary
      // lots when a server-side limit is absent.
      const unlimited = !lotLimits.length && (Boolean(ordinaryShopGroup(lot)) || currentEventLot);
      if (!lotLimits.length && !unlimited) return [];
      const playerLimit = lotLimits.find(value => String(value?.type || '').toUpperCase() === 'PLAYER');
      const sharedLimit = lotLimits.find(value => ['CLAN','GLOBAL'].includes(String(value?.type || '').toUpperCase()));
      const remainingValues = [];
      if (playerLimit) remainingValues.push(Math.max(0, Number(playerLimit.limit || 0) + Number(playerLimit.bonus || 0) - (limits.get(String(lot.id || '')) || 0)));
      if (sharedLimit) remainingValues.push(Math.max(0, Number(sharedLimit.limit || 0) + Number(sharedLimit.bonus || 0) - Number(sharedLimit.value || 0)));
      if (!remainingValues.length && !unlimited) return [];
      const bought = limits.get(lotId) || 0;
      const playerMaximum = playerLimit ? Math.max(0, Number(playerLimit.limit || 0) + Number(playerLimit.bonus || 0)) : 0;
      const remaining = unlimited ? Number.MAX_SAFE_INTEGER : Math.min(...remainingValues);
      const parts = costParts(lot.cost);
      const content = (view.content_view || [])[0] || {};
      const rewardId = String(content.id || '');
      const rewardQuantity = resourceMatch
        ? Math.max(0, Number(rawView.quantity || view.quantity || 0))
        : Math.max(0, Number(content.quantity || view.quantity || 0));
      const tab = String(view.tab || 'default').toLowerCase();
      // The shop catalog and the player's limit list both retain past events.
      // Include every internal lot of the active event: the updated game uses
      // daily_event, finite_event, event and infinite_event prefixes together.
      // If the current event cannot be identified, fail closed and show none.
      const section = ['clan','clan_2'].includes(tab) ? 'clan' : currentEventLot ? 'regular' : 'ordinary';
      const group = section === 'ordinary' ? ordinaryShopGroup(lot) : '';
      const clanGroup = section === 'clan' ? (sharedLimit ? 'shared' : 'personal') : '';
      if (section === 'ordinary' && !group) return [];
      const premium = premiumPurchase(lot.cost);
      const safe = parts.length > 0 && parts.every(part => part.quantity > 0 &&
        (part.kind === 'items' ? part.id.startsWith('item_') :
          ['cur_gold', 'cur_cap'].includes(part.id) || (section === 'clan' && part.id === 'cur_prem')));
      return [{lotId, name:String(view.name || rewardId || lotId), rewardName:String(content.name || content.caption || rewardId || ''), rewardId,
        rewardQuantity, resourceTier:resourceMatch ? Number(resourceMatch[1].slice(-1)) : 0,
        cost:lot.cost || {}, safe, affordable:canAffordCost(lot.cost || {}, playerDoc), premium, group,
        bought, maximum:bought + remaining, playerMaximum, remaining, unlimited, section, clanGroup,
        sharedPurchased:sharedLimit ? Math.max(0, Number(sharedLimit.value || 0)) : 0,
        sharedMaximum:sharedLimit ? Math.max(0, Number(sharedLimit.limit || 0) + Number(sharedLimit.bonus || 0)) : 0,
        icon:mediaUrl(view.icon_card || view.icon || content.icon_card || content.icon, rewardId)}];
    }).sort((a, b) => Number(b.remaining > 0) - Number(a.remaining > 0) ||
      (a.group === 'resources' && b.group === 'resources'
        ? a.resourceTier - b.resourceTier || a.rewardQuantity - b.rewardQuantity
        : a.lotId.localeCompare(b.lotId)));
  }

  // HK_CLAN_SHOP_ACTUAL_FACTS_V1
  function clanShopActualFactType(row) {
    if (row?.section !== 'clan' || row?.clanGroup !== 'shared') return '';
    const label = clean(String(gameText(row?.name || '') || '') + ' ' + String(row?.name || '') + ' ' + String(row?.rewardId || '') + ' ' + String(row?.lotId || '')).toLowerCase();
    if (/шар.{0,24}идол|идол.{0,24}шар|idol.{0,24}ball|ball.{0,24}idol|guru.{0,24}ball|ball.{0,24}guru/.test(label)) return 'idol_orbs';
    if (/s\s*\+.{0,24}бизнес|бизнес.{0,24}s\s*\+|s\s*\+.{0,24}business|business.{0,24}s\s*\+|splus.{0,24}business|business.{0,24}splus/.test(label)) return 'splus_businesses';
    return '';
  }

  const HK_CLAN_SHOP_PASSIVE_FACTS_REV='clan-shop-passive-facts-20260922-r1';
  const HK_CLAN_SHOP_PLAYER_ME_FACTS_REV='clan-shop-player-me-facts-20260922-r2';
  const CLAN_SHOP_FACT_TARGETS={
    mf_clan_shoplot_lvl20_bonus_hballs:{
      item_type:'idol_orbs',
      lot_name:'item h ball idol all',
      reward_id:'item_h_ball_idol_all'
    },
    mf_clan_shoplot_random_business_r3_lvl_15:{
      item_type:'splus_businesses',
      lot_name:'clan shoplot random business splus',
      reward_id:'item_bsn_r3t2_max_taphballs'
    }
  };

  function clanShopPlayerFactRows(documentValue = playerDocument) {
    const limits=documentValue?.shop_lot_limits || documentValue?.player?.shop_lot_limits || [];
    const byId=new Map((Array.isArray(limits)?limits:[]).map(row=>[
      String(row?.shop_lot_id || ''),
      Math.max(0,Number(row?.number_of_purchase || 0))
    ]));
    return Object.entries(CLAN_SHOP_FACT_TARGETS).map(([lotId,target])=>({
      lot_id:lotId,
      item_type:target.item_type,
      lot_name:target.lot_name,
      reward_id:target.reward_id,
      shared_purchased:0,
      shared_maximum:0,
      player_purchased:byId.get(lotId) || 0
    }));
  }

  function clanShopFactRows(sourceRows = shopRows, documentValue = playerDocument) {
    const merged=new Map(clanShopPlayerFactRows(documentValue).map(row=>[row.lot_id,{...row}]));
    for(const row of (Array.isArray(sourceRows)?sourceRows:[])){
      const itemType=clanShopActualFactType(row);
      if(!itemType) continue;
      const lotId=String(row.lotId || '');
      const current=merged.get(lotId) || {
        lot_id:lotId,
        item_type:itemType,
        lot_name:gameText(row.name || '') || String(row.name || ''),
        reward_id:String(row.rewardId || ''),
        shared_purchased:0,
        shared_maximum:0,
        player_purchased:Math.max(0,Number(row.bought || 0))
      };
      current.item_type=itemType;
      current.lot_name=gameText(row.name || '') || String(row.name || '') || current.lot_name;
      current.reward_id=String(row.rewardId || '') || current.reward_id;
      current.shared_purchased=Math.max(current.shared_purchased||0,Math.max(0,Number(row.sharedPurchased || 0)));
      current.shared_maximum=Math.max(current.shared_maximum||0,Math.max(0,Number(row.sharedMaximum || 0)));
      current.player_purchased=Math.max(current.player_purchased||0,Math.max(0,Number(row.bought || 0)));
      merged.set(lotId,current);
    }
    return [...merged.values()].sort((a,b)=>a.lot_id.localeCompare(b.lot_id));
  }

  async function reportClanShopActualFacts(sourceRows = shopRows, force = false) {
    const rows = clanShopFactRows(sourceRows);
    if (!rows.length || !licenseState.allowed) return;
    const fingerprint=JSON.stringify(rows.map(row=>[
      row.lot_id,row.item_type,row.shared_purchased,row.shared_maximum,row.player_purchased
    ]));
    if(!force && fingerprint===clanShopFactLastFingerprint) return;
    try {
      await licensedServerJson(CLAN_SHOP_FACT_API_BASE, '/clan-shop-facts/submit', {rows}, false, 'clan-shop-facts');
      clanShopFactLastFingerprint=fingerprint;
      recordDiagnostic('clan-shop-passive-facts',{rows:rows.length});
    } catch (error) {
      console.warn('[HK] Clan Shop actual facts sync failed', error);
    }
  }

  function scheduleClanShopActualFactsSync() {
    if (!playerDocument) return;
    if (clanShopFactSyncTimer) clearTimeout(clanShopFactSyncTimer);
    clanShopFactSyncTimer=setTimeout(() => {
      clanShopFactSyncTimer=null;
      if(!licenseState.allowed || !playerDocument) return;
      const passiveRows=shopViewDocument ? normalizeRegularShop(shopViewDocument,playerDocument) : [];
      void reportClanShopActualFacts(passiveRows,false);
    },900);
  }

  async function loadShop() {
    if (!requireLicense()) return;
    try {
      log(either('Считываю магазин…', 'Reading shop…'));
      playerDocument = await apiJson('/player/me', 'POST');
      shopViewDocument = await apiJson('/shop/view', 'GET');
      if(!localizationDocument){try{localizationDocument=await apiJson(`/localization/${language}`,'GET');}catch(_){}}
      shopRows = normalizeRegularShop();
      void reportClanShopActualFacts();
      selectedShopLots = new Set([...selectedShopLots].filter(id => shopRows.some(row => row.lotId === id && row.safe && row.remaining > 0)));
      selectedShopCounts = new Map([...selectedShopCounts].flatMap(([id, count]) => {
        const row = shopRows.find(value => value.lotId === id && value.safe && value.remaining > 0);
        const maximum = row ? shopPurchasableCount(row) : 0;
        return row && maximum > 0 ? [[id, Math.min(maximum, Math.max(0, Number(count || 0)))]] : [];
      }));
      renderShop();
      log(either(`Магазин считан: ${shopRows.length} лотов`, `Shop loaded: ${shopRows.length} lots`), 'ok');
    } catch (error) { log(`${either('Ошибка магазина', 'Shop error')}: ${error.message}`, 'bad'); }
  }

  function defaultShopPurchaseCount(row) {
    if (!row) return 0;
    const remaining = Math.max(0, Number(row.remaining || 0));
    if (isRenovationBatch(row)) return remaining >= renovationBatchMultiplier(row) ? renovationBatchMultiplier(row) : 0;
    return Math.min(remaining, 1);
  }

  function isRenovationBatch(row) {
    return row?.section === 'ordinary' && row?.group === 'renovation';
  }

  function renovationBatchMultiplier(row) {
    return Math.ceil(500 / Math.max(1, Number(row?.rewardQuantity || 0)));
  }

  function renovationBatchCount(row, count) {
    return Math.floor(Math.max(0, Number(count || 0)) / renovationBatchMultiplier(row));
  }

  function shopBudgetSection(row) {
    return row?.section === 'clan' ? 'clan' : 'shop';
  }

  function shopWalletPurchaseLimit(row, documentValue = playerDocument) {
    const parts=costParts(row?.cost);
    if(!parts.length)return 0;
    let limit=Number.MAX_SAFE_INTEGER;
    for(const part of parts){
      const quantity=Math.max(0,Number(part?.quantity||0));
      const balance=walletAmount(part?.id,documentValue);
      if(!(quantity>0)||balance===null)return 0;
      limit=Math.min(limit,Math.floor(Math.max(0,Number(balance||0))/quantity));
    }
    return Number.isFinite(limit)&&limit>0?Math.max(0,Math.trunc(limit)):0;
  }

  function shopPurchasableCount(row, documentValue = playerDocument) {
    if (!row?.safe) return 0;
    const walletLimit=shopWalletPurchaseLimit(row,documentValue);
    const lotLimit=row?.unlimited?walletLimit:Math.min(walletLimit,Math.max(0,Math.trunc(Number(row?.remaining||0))));
    if (!lotLimit) return 0;
    let low = 0, high = lotLimit;
    while (low < high) {
      const middle = Math.ceil((low + high + 1) / 2);
      if (budgetDecision(row.cost, shopBudgetSection(row), middle, documentValue).allowed) low = middle;
      else high = middle - 1;
    }
    return low;
  }

  function shopIsCapsSweep(row) {
    const parts=costParts(row?.cost);
    return row?.section==='ordinary'&&row?.group==='resources'&&parts.length===1&&parts[0]?.kind==='currencies'&&parts[0]?.id==='cur_cap'&&Number(parts[0]?.quantity||0)>0;
  }

  function shopDisplayName(row) {
    const candidates=[row?.name,row?.rewardName,row?.rewardId].map(value=>String(value||'')).filter(Boolean);
    for(const key of candidates){
      const localized=localizationDocument?.[key];
      if(typeof localized==='string'&&clean(localized))return clean(localized);
    }
    const value = gameText(row?.rewardName || '') || gameText(row?.rewardId || '') || gameText(row?.name || '') || String(row?.rewardId || row?.name || row?.lotId || '');
    return clean(value) || paymentLabel(row?.rewardId || row?.lotId || '');
  }

  function shopRowInActiveView(row) {
    if (row?.section !== selectedShopSection) return false;
    if (selectedShopSection === 'ordinary') return row.group === selectedShopGroup;
    if (selectedShopSection === 'clan') return row.clanGroup === selectedShopGroup;
    return true;
  }

  function shopSharedLimitText(row) {
    if (row?.section !== 'clan' || row?.clanGroup !== 'shared') return '';
    const clanBought=Math.max(0,Number(row.sharedPurchased||0)), clanMax=Math.max(0,Number(row.sharedMaximum||0));
    const playerBought=Math.max(0,Number(row.bought||0)), playerMax=Math.max(0,Number(row.playerMaximum||0));
    const clanText=clanMax>0 ? `${either('Клан','Clan')}: ${clanBought.toLocaleString(locale())}/${clanMax.toLocaleString(locale())}` : `${either('Клан','Clan')}: ${clanBought.toLocaleString(locale())}`;
    const playerText=playerMax>0 ? `${either('Вы','You')}: ${playerBought.toLocaleString(locale())}/${playerMax.toLocaleString(locale())}` : `${either('Вы','You')}: ${playerBought.toLocaleString(locale())}`;
    return clanText+' · '+playerText;
  }

  function shopAvailabilityText(row, maxCount = shopPurchasableCount(row)) {
    if (!row?.safe) return either('Заблокировано: неизвестная валюта или стоимость','Blocked: unknown currency or cost');
    if (Number(row?.remaining || 0) <= 0) return tr('boughtOut');
    if (maxCount <= 0) {
      const problem = budgetDecision(row.cost, shopBudgetSection(row), 1, playerDocument).problems[0];
      return problem || either('Недостаточно доступного баланса','Insufficient available balance');
    }
    if (shopIsCapsSweep(row)) return either('По текущим крышкам: до '+maxCount+' покупок','By current Caps: up to '+maxCount+' purchases');
    if (row.unlimited) return either('Можно купить сейчас: '+maxCount,'Can buy now: '+maxCount);
    if (maxCount < Number(row.remaining || 0)) return either('Можно купить: '+maxCount+' · осталось в лоте: '+row.remaining,'Can buy: '+maxCount+' · lot remaining: '+row.remaining);
    return tr('remaining',{n:row.remaining});
  }

  function renovationBatchMaximum(row) {
    return Math.floor(shopPurchasableCount(row) / renovationBatchMultiplier(row));
  }

  function shopWalletForecastHtml(parts) {
    const values = [...parts.values()].filter(part => part?.id).sort((a,b) => a.id.localeCompare(b.id));
    if (!values.length) return '';
    return '<div class="hk-wallet-forecast">' + values.map(part => {
      const balance = walletAmount(part.id);
      const spend = Math.max(0, Number(part.quantity || 0));
      const known = balance !== null;
      const after = known ? balance - spend : null;
      return '<div class="hk-wallet-row '+(known && after < 0 ? 'shortage' : '')+'">' +
        '<span class="hk-wallet-currency">'+fairIconHtml(paymentIcon(part), 'hk-price-icon')+'<b>'+escapeHtml(paymentLabel(part.id))+'</b></span>' +
        '<span>'+tr('balance')+': <b>'+(known ? balance.toLocaleString(locale()) : '—')+'</b> · '+tr('willSpend')+': <b>'+spend.toLocaleString(locale())+'</b> · '+tr('balanceAfter')+': <b>'+(known ? after.toLocaleString(locale()) : '—')+'</b></span>' +
      '</div>';
    }).join('') + '</div>';
  }

  function renderShop() {
    if (!shopCards || !shopSummary) return;
    if (!shopRows.length) {
      shopCards.innerHTML = `<p class="hk-muted">${tr('shopReadFirst')}</p>`;
      shopSummary.textContent = tr('selectedPurchases', {n:0});
      const buy = root?.querySelector('#hk-shop-buy'); if (buy) buy.disabled = true;
      return;
    }
    const groupBar = root?.querySelector('#hk-shop-groups');
    if (groupBar) {
      const groups = selectedShopSection === 'ordinary'
        ? [['resources','resourcesShop'],['renovation','renovationShop'],['invest','investShop']]
        : [];
      groupBar.style.display = groups.length ? '' : 'none';
      groupBar.innerHTML = groups.map(([id, label]) => `<button class="${selectedShopGroup === id ? 'active' : ''}" data-shop-group="${id}" data-i18n="${label}">${tr(label)}</button>`).join('');
      groupBar.querySelectorAll('[data-shop-group]').forEach(button => button.onclick = () => {
        selectedShopGroup = button.dataset.shopGroup; selectedShopLots.clear(); selectedShopCounts.clear(); renderShop();
      });
    }
    const visibleRows = shopRows.filter(shopRowInActiveView);
    shopCards.innerHTML = visibleRows.map(row => {
      const maximumCount = shopPurchasableCount(row);
      const selectable = maximumCount > 0 && (!isRenovationBatch(row) || renovationBatchMaximum(row) > 0);
      const count = selectable ? Math.min(maximumCount, Math.max(0, Number(selectedShopCounts.get(row.lotId) || 0))) : 0;
      const shownRewardQuantity = count && row.group === 'renovation' ? row.rewardQuantity * count : row.rewardQuantity;
      const selectedBatches = isRenovationBatch(row) ? renovationBatchCount(row, count) : 0;
      const maximumBatches = isRenovationBatch(row) ? renovationBatchMaximum(row) : 0;
      return `<div class="hk-shop-lot ${count ? 'selected' : ''} ${row.premium ? 'premium' : ''} ${shopIsCapsSweep(row) ? 'caps-sweep' : ''} ${selectable ? '' : 'locked'}">
        ${row.premium ? '<i class="hk-premium-mark">💎</i>' : ''}<label class="hk-shop-pick"><input type="checkbox" data-shop-lot="${escapeHtml(row.lotId)}" ${count ? 'checked' : ''} ${selectable ? '' : 'disabled'}>
        ${fairIconHtml(row.icon)}<span class="hk-shop-name">${escapeHtml(shopDisplayName(row))}</span><b>×${shownRewardQuantity.toLocaleString(locale())}</b><span class="hk-shop-cost">${costVisual(row.cost, count && row.group === 'renovation' ? count : 1)}</span></label>
        <small class="hk-shop-availability">${escapeHtml(shopAvailabilityText(row, maximumCount))}</small>
        ${row.section === 'clan' && row.clanGroup === 'shared' ? `<small class="hk-shop-shared-limits">${escapeHtml(shopSharedLimitText(row))}</small>` : ''}
        ${isRenovationBatch(row)
          ? `<label class="hk-shop-quantity"><span>${either('Пакетов ×500','×500 packages')}</span><select data-shop-batches="${escapeHtml(row.lotId)}" ${selectable ? '' : 'disabled'}>${Array.from({length:maximumBatches + 1}, (_, n) => `<option value="${n}" ${n === selectedBatches ? 'selected' : ''}>${n} × 500</option>`).join('')}</select></label>`
          : `<label class="hk-shop-quantity"><span>${tr('quantity')}</span><input data-shop-qty="${escapeHtml(row.lotId)}" type="number" inputmode="numeric" min="0" max="${maximumCount}" value="${count}" ${selectable ? '' : 'disabled'}><button type="button" data-shop-max="${escapeHtml(row.lotId)}" ${selectable ? '' : 'disabled'}>MAX</button></label>`}</div>`;
    }).join('') || `<p class="hk-muted">${tr('noLots')}</p>`;
    shopCards.querySelectorAll('[data-shop-lot]').forEach(input => input.onchange = () => {
      const id = input.dataset.shopLot;
      const row = visibleRows.find(value => value.lotId === id);
      const maximum = shopPurchasableCount(row);
      if(input.checked&&shopIsCapsSweep(row)){
        for(const other of visibleRows){
          if(other.lotId!==id&&shopIsCapsSweep(other)){selectedShopLots.delete(other.lotId);selectedShopCounts.delete(other.lotId);}
        }
      }
      const count = input.checked ? (shopIsCapsSweep(row)?maximum:Math.max(defaultShopPurchaseCount(row), Number(selectedShopCounts.get(id) || 0))) : 0;
      if (count && maximum > 0) { selectedShopLots.add(id); selectedShopCounts.set(id, Math.min(maximum, count)); }
      else { selectedShopLots.delete(id); selectedShopCounts.delete(id); }
      renderShop();
    });
    shopCards.querySelectorAll('[data-shop-qty]').forEach(input => input.onchange = () => {
      const id = input.dataset.shopQty;
      const row = visibleRows.find(value => value.lotId === id);
      const count = Math.min(shopPurchasableCount(row), Math.max(0, Math.trunc(Number(input.value || 0))));
      if (count) { selectedShopLots.add(id); selectedShopCounts.set(id, count); }
      else { selectedShopLots.delete(id); selectedShopCounts.delete(id); }
      renderShop();
    });
    shopCards.querySelectorAll('[data-shop-batches]').forEach(select => select.onchange = () => {
      const id = select.dataset.shopBatches;
      const row = visibleRows.find(value => value.lotId === id);
      const batches = Math.min(renovationBatchMaximum(row), Math.max(0, Math.trunc(Number(select.value || 0))));
      const count = batches * renovationBatchMultiplier(row);
      if (count) { selectedShopLots.add(id); selectedShopCounts.set(id, count); }
      else { selectedShopLots.delete(id); selectedShopCounts.delete(id); }
      renderShop();
    });
    shopCards.querySelectorAll('[data-shop-max]').forEach(button => button.onclick = () => {
      const id = button.dataset.shopMax;
      const row = visibleRows.find(value => value.lotId === id);
      const count = shopPurchasableCount(row);
      if (count) { selectedShopLots.add(id); selectedShopCounts.set(id, count); }
      else { selectedShopLots.delete(id); selectedShopCounts.delete(id); }
      renderShop();
    });
    const selected = visibleRows.filter(row => selectedShopLots.has(row.lotId) && shopPurchasableCount(row) > 0)
      .map(row => ({row, count:Math.min(shopPurchasableCount(row), Math.max(0, Number(selectedShopCounts.get(row.lotId) || 0)))})).filter(item => item.count > 0);
    const purchaseCount = selected.reduce((sum, item) => sum + (isRenovationBatch(item.row) ? renovationBatchCount(item.row, item.count) : item.count), 0);
    const totals = new Map();
    for (const row of visibleRows) for (const part of costParts(row.cost)) addProjectedCost(totals, part, 0);
    for (const {row, count} of selected) for (const part of costParts(row.cost)) addProjectedCost(totals, part, count);
    const spending = [...totals.values()].filter(part => part.quantity > 0);
    const totalVisual = spending.length ? spending.map(part => `${fairIconHtml(paymentIcon(part), 'hk-price-icon')}<b>${part.quantity.toLocaleString(locale())}</b>`).join(' ') : '0';
    shopSummary.innerHTML = `<b>${tr('selectedPurchases',{n:purchaseCount})}</b><br><small>${tr('maxCost')}: ${totalVisual}</small>${shopWalletForecastHtml(totals)}`;
    const buy = root?.querySelector('#hk-shop-buy'); if (buy) buy.disabled = shopRunning || !purchaseCount;
  }

  function shopLotDisplayName(row) {
    return String(gameText(row?.name) || row?.name || row?.rewardId || row?.lotId || either('Лот','Lot'));
  }

  function shopRateLimitError(error) {
    return error?.name === 'HKRateLimitError' || Number(error?.httpStatus) === 429;
  }

  async function shopBuyWithRateLimitResume(body, label = '') {
    let rateHits = 0;
    while (true) {
      if (hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
      await hkRunner.waitIfPaused();
      try {
        return await apiJson('/shop/buy', 'POST', body, true, 0);
      } catch (error) {
        if (!shopRateLimitError(error)) throw error;
        rateHits += 1;
        const waitMs = Math.max(
          1000,
          Number(error?.retryAfterMs || 0),
          gameApiCooldownRemainingMs(),
          GAME_API_429_FALLBACK_COOLDOWN_MS
        );
        const seconds = Math.ceil(waitMs / 1000);
        hkRunner.setStep(either(
          'Лимит игры · жду ' + seconds + ' сек.' + (label ? ' · ' + label : ''),
          'Game limit · waiting ' + seconds + ' sec.' + (label ? ' · ' + label : '')
        ));
        if (rateHits === 1 || rateHits % 3 === 0) {
          log(either(
            'Магазин: лимит 429. Жду ' + seconds + ' сек. и продолжу автоматически' + (label ? ' · ' + label : ''),
            'Shop: 429 rate limit. Waiting ' + seconds + ' sec. and resuming automatically' + (label ? ' · ' + label : '')
          ), 'warn');
        }
        recordDiagnostic('shop-rate-limit-resume',{label,rateHits,waitMs});
        await gameRetryDelay(waitMs);
      }
    }
  }

  async function buyRegularShop() {
    if (!requireLicense() || shopRunning) return;
    try {
      playerDocument = await apiJson('/player/me', 'POST');
      shopViewDocument = await apiJson('/shop/view', 'GET');
      shopRows = normalizeRegularShop();
    } catch (error) {
      log(either('Не удалось обновить магазин перед покупкой','Could not refresh the shop before purchase') + ': ' + (error?.message || error),'bad');
      return;
    }
    const plan = shopRows.filter(row => shopRowInActiveView(row) &&
      selectedShopLots.has(row.lotId) && row.safe && row.remaining > 0)
      .map(row => ({row, count:Math.min(shopPurchasableCount(row, playerDocument), Math.max(0, Number(selectedShopCounts.get(row.lotId) || 0)))})).filter(item => item.count > 0);
    if (!plan.length) return;
    const count = plan.reduce((sum, item) => sum + (isRenovationBatch(item.row) ? renovationBatchCount(item.row, item.count) : item.count), 0);
    const budgetSection = selectedShopSection === 'clan' ? 'clan' : 'shop';
    const projectedProblems = plan.flatMap(item => budgetDecision(item.row.cost, budgetSection, item.count, playerDocument).problems);
    if (projectedProblems.length) {
      alert(`${either('Покупка заблокирована единым бюджетом','Purchase blocked by unified budget')}:\n\n${[...new Set(projectedProblems)].join('\n')}`);
      return;
    }
    const crystalCost = plan.reduce((sum, item) => sum + costParts(item.row.cost)
      .filter(part => part.kind === 'currencies' && part.id === 'cur_prem').reduce((value, part) => value + part.quantity * item.count, 0), 0);
    if (!confirm(language === 'en'
      ? `Buy ${count} selected items?${crystalCost ? `\n\nCrystal cost: ${crystalCost.toLocaleString(locale())} 💎` : ''}\n\nPurchases are irreversible. External payments are blocked.`
      : `Выкупить выбранные товары: ${count}?${crystalCost ? `\n\nСтоимость: ${crystalCost.toLocaleString(locale())} 💎` : ''}\n\nПокупки необратимы. Внешняя оплата заблокирована.`)) return;
    if (hkRunner.running) { alert(either('Сначала завершите текущую задачу','Finish the current task first')); return; }
    hkRunner.start({title:either('Магазин','Shop'),total:count,step:either('Подготовка','Preparing'),pausable:true,stoppable:true});
    shopRunning = true; renderShop();
    let completed = 0;
    try {
      playerDocument = await apiJson('/player/me', 'POST');
      for (const {row, count:rowCount} of plan) {
        if (hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
        await hkRunner.waitIfPaused();
        hkRunner.setStep(either('Покупка товаров','Buying items'), completed, count);
        const requestCount = shopIsCapsSweep(row) ? shopPurchasableCount(row,playerDocument) : Math.min(rowCount,row.remaining);
        const before = new Map(costParts(row.cost).map(part => [part.id, walletAmount(part.id, playerDocument)]));
        const requestBody = {shop_lot_id:row.lotId, payment_type:'INTERNAL', lotName:row.name, lotDescription:''};
        let purchasedRow = 0;
        try {
          if (isRenovationBatch(row)) {
            const decision = budgetDecision(row.cost, budgetSection, requestCount, playerDocument);
            if (!decision.allowed) throw new Error(decision.problems.join('; '));
            const batchMultiplier = renovationBatchMultiplier(row);
            const batchCount = renovationBatchCount(row, requestCount);
            for (let batch = 0; batch < batchCount; batch += 1) {
              log(either(`Пакетная покупка ×500: ${batch + 1}/${batchCount}…`, `Batch purchase ×500: ${batch + 1}/${batchCount}…`));
              if (hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
              await hkRunner.waitIfPaused();
              hkRunner.setStep(either('Покупка товаров','Buying items'), completed, count);
              playerDocument = await shopBuyWithRateLimitResume({
                ...requestBody,
                collection_entity_id:row.rewardId,
                collection_count:batchMultiplier
              }, shopLotDisplayName(row));
              purchasedRow += batchMultiplier;
              completed += 1;
            }
          } else for (let index = 0; index < requestCount; index += 1) {
            const decision = budgetDecision(row.cost, budgetSection, 1, playerDocument);
            if (!decision.allowed) throw new Error(decision.problems.join('; '));
            if (index === 0 || (index + 1) % 25 === 0 || index + 1 === requestCount) {
              log(either(`Покупка по ×1: ${index + 1}/${requestCount}…`, `Buying ×1: ${index + 1}/${requestCount}…`));
            }
            // Start the next purchase immediately after the previous response.
            // Network retries are disabled because repeating an irreversible
            // request after a lost response could buy an extra copy.
            if (hkRunner.signal?.aborted) throw new DOMException('Aborted','AbortError');
            await hkRunner.waitIfPaused();
            hkRunner.setStep(either('Покупка: ','Buying: ') + shopLotDisplayName(row), completed, count);
            playerDocument = await shopBuyWithRateLimitResume(requestBody, shopLotDisplayName(row));
            purchasedRow += 1;
            completed += 1;
          }
        } finally {
          if (purchasedRow) for (const part of costParts(row.cost)) appendExpense({section:budgetSection, lotId:row.lotId, name:gameText(row.name) || row.name,
            currencyId:part.id, amount:part.quantity * purchasedRow, balanceBefore:before.get(part.id), balanceAfter:walletAmount(part.id, playerDocument), status:'ok', result:`purchased ${purchasedRow}/${requestCount}`});
        }
      }
      await hkAuthoritativePlayerRead('shop-complete');
      try { shopViewDocument = await apiJson('/shop/view', 'GET'); } catch (_) {}
      shopRows = normalizeRegularShop();
      void reportClanShopActualFacts();
      hkRunner.finish(either('Покупки завершены','Purchases completed'));
      selectedShopLots.clear();
      selectedShopCounts.clear();
      log(either(`Покупки завершены: ${completed}`, `Purchases completed: ${completed}`), 'ok');
    } catch (error) {
      if (error?.name === 'AbortError') { hkRunner.reset(); log(either('Магазин остановлен','Shop stopped'),'warn'); }
      else { hkRunner.fail(error); log(either('Остановка магазина','Shop stopped') + ': ' + (error?.message || error), 'bad'); }
    } finally {
      shopRunning = false;
      shopRows = normalizeRegularShop();
      renderShop();
    }
  }

  function dailyLabel(row) {
    return clean(`${gameText(row?.name || '')} ${row?.name || ''} ${row?.rewardId || ''}`).toLowerCase();
  }

  function dailyRecruitLot(row) {
    const label = dailyLabel(row);
    return /пополнени[ея]\s+рекрут|recruit\s+(?:replenishment|refill)|replenish(?:ment)?\s+recruit|нов(?:ые|ых)\s+рекрут|new\s+recruits?|салаг|rookies?/.test(label);
  }

  function dailyCartelLot(row) {
    const label = dailyLabel(row);
    return /пополнени[ея]\s+картел|cartel\s+(?:replenishment|refill)|replenish(?:ment)?\s+cartel/.test(label);
  }

  function excludedDailyClanLot(row) {
    if (row?.section !== 'clan' || row?.clanGroup !== 'personal') return false;
    const label = dailyLabel(row);
    const excludedByName = /хомячий\s+шар\s+идол|idol(?:s)?\s+hamster\s+ball|случайный\s+s\+?\s+бизнес|random\s+s\+?\s+business/.test(label);
    const excludedByCurrency = costParts(row.cost).some(part => {
      const currencyId = String(part.id || '').toLowerCase().replace(/[\s-]+/g, '_');
      return /pit_?rat_?tokens?/.test(currencyId);
    });
    return excludedByName || excludedByCurrency;
  }

  function mandatoryDailyClanLot(row) {
    // Recruit and cartel replenishment are obligatory personal clan lots.
    // Hamster balls and random S/S+ businesses remain excluded from Today.
    if (row?.section !== 'clan' || row?.clanGroup !== 'personal') return false;
    return dailyRecruitLot(row) || dailyCartelLot(row);
  }

  function clanSkillPointLot(row) {
    if (row?.section !== 'clan' || row?.clanGroup !== 'personal') return false;
    const label = clean(`${gameText(row?.name || '')} ${row?.name || ''}`).toLowerCase();
    return /очки\s+навыков(?:\s+клана)?|clan\s+skill\s+points?|skill\s+points?/.test(label);
  }

  function gamePeriodBounds(now = new Date()) {
    const dayStart = new Date(now);
    dayStart.setHours(21, 0, 0, 0);
    if (now < dayStart) dayStart.setDate(dayStart.getDate() - 1);
    const dayEnd = new Date(dayStart); dayEnd.setDate(dayEnd.getDate() + 1);
    const weekStart = new Date(dayStart);
    const daysSinceMonday = (weekStart.getDay() + 6) % 7;
    weekStart.setDate(weekStart.getDate() - daysSinceMonday);
    const weekEnd = new Date(weekStart); weekEnd.setDate(weekEnd.getDate() + 7);
    return {dayStart:dayStart.getTime(), dayEnd:dayEnd.getTime(), weekStart:weekStart.getTime(), weekEnd:weekEnd.getTime()};
  }

  function budgetDocument() {
    const stored = load().budget || {};
    const periods = gamePeriodBounds();
    return {currencies:{...(stored.currencies || {})}, periods, timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || ''};
  }

  function currencyBudget(id) {
    const value = budgetDocument().currencies[String(id)] || {};
    const premium = String(id) === 'cur_prem';
    return {
      reserve:Math.max(0, Number(value.reserve || 0)),
      dailyLimit:Math.max(0, Number(value.dailyLimit || 0)),
      weeklyLimit:Math.max(0, Number(value.weeklyLimit || 0)),
      allow:{shop:value.allow?.shop !== false, fair:value.allow?.fair !== false, clan:value.allow?.clan !== false},
      allowPremium:premium && value.allowPremium === true
    };
  }

  function saveCurrencyBudget(id, patch) {
    const budget = budgetDocument();
    budget.currencies[String(id)] = {...currencyBudget(id), ...patch,
      allow:{...currencyBudget(id).allow, ...(patch.allow || {})}};
    save({budget});
  }

  function expenseJournal() {
    return Array.isArray(load().expenseJournal) ? load().expenseJournal : [];
  }

  function budgetUsage(id, now = Date.now()) {
    const periods = gamePeriodBounds(new Date(now));
    const rows = expenseJournal().filter(row => row?.status === 'ok' && String(row.currencyId) === String(id));
    return {
      day:rows.filter(row => Number(row.time || 0) >= periods.dayStart).reduce((sum, row) => sum + Math.max(0, Number(row.amount || 0)), 0),
      week:rows.filter(row => Number(row.time || 0) >= periods.weekStart).reduce((sum, row) => sum + Math.max(0, Number(row.amount || 0)), 0)
    };
  }

  function appendExpense(entry) {
    const rows = [...expenseJournal(), {time:Date.now(), ...entry}].slice(-300);
    save({expenseJournal:rows});
  }

  function costSignature(cost) {
    return costParts(cost).filter(part => part.id && part.quantity > 0)
      .sort((a,b) => `${a.kind}:${a.id}`.localeCompare(`${b.kind}:${b.id}`))
      .map(part => `${part.kind}:${part.id}:${part.quantity}`).join('|');
  }

  function budgetDecision(cost, section, multiplier = 1, documentValue = playerDocument, options = {}) {
    const problems = [];
    for (const part of costParts(cost)) {
      const amount = Math.max(0, Number(part.quantity || 0) * multiplier);
      const rules = currencyBudget(part.id);
      const usage = budgetUsage(part.id);
      const balance = walletAmount(part.id, documentValue);
      if (balance === null) problems.push(`${paymentLabel(part.id)}: ${either('баланс не определён','balance is unknown')}`);
      if (rules.allow?.[section] === false) problems.push(`${paymentLabel(part.id)}: ${either('раздел запрещён','section is disabled')}`);
      if (part.id === 'cur_prem' && !rules.allowPremium && !options.allowPremiumOverride) problems.push(`${paymentLabel(part.id)}: ${either('алмазы запрещены','diamonds are disabled')}`);
      if (balance !== null && balance - amount < rules.reserve) problems.push(`${paymentLabel(part.id)}: ${either('нарушается остаток','minimum balance would be breached')}`);
      if (rules.dailyLimit > 0 && usage.day + amount > rules.dailyLimit) problems.push(`${paymentLabel(part.id)}: ${either('превышен дневной лимит','daily limit exceeded')}`);
      if (rules.weeklyLimit > 0 && usage.week + amount > rules.weeklyLimit) problems.push(`${paymentLabel(part.id)}: ${either('превышен недельный лимит','weekly limit exceeded')}`);
      if (balance !== null && balance < amount) problems.push(`${paymentLabel(part.id)}: ${either('недостаточно средств','insufficient balance')}`);
    }
    return {allowed:!problems.length, problems};
  }

  function discoveredCurrencyIds() {
    // Only universal currencies and currencies of the event that is active
    // right now belong in Today. Feature tokens and archived event balances
    // remain in the player's inventory, but must not clutter this screen.
    const ids = new Set(['cur_prem','cur_gold','cur_cap','item_invest_cur','item_business_dust','item_clan_cur']);
    const currentShopRows = dailyShopRows.length ? dailyShopRows : shopRows;
    for (const row of currentShopRows.filter(value => value?.safe && value.remaining > 0 && value.section === 'regular')) {
      for (const part of costParts(row.cost)) if (part.id) ids.add(part.id);
    }
    for (const state of visibleFairStates(playerDocument).filter(value => String(value?.id) === 'fair_event_base')) {
      for (const part of costParts(state?.fair_reroll_cost)) if (part.id) ids.add(part.id);
      for (const slot of state.fair_slots || []) {
        if (slot?.is_bought) continue;
        const row = fairCatalog.find(value => value.lotId === String(slot?.shop_lot_id || ''));
        for (const part of costParts(row?.cost)) if (part.id) ids.add(part.id);
      }
    }
    return [...ids].sort((a,b) => Number(a !== 'cur_prem') - Number(b !== 'cur_prem') || paymentLabel(a).localeCompare(paymentLabel(b), locale()));
  }

  function timestampFrom(value) {
    if (value == null) return null;
    const numberValue = Number(value);
    if (Number.isFinite(numberValue) && numberValue > 0) return numberValue < 1e12 ? numberValue * 1000 : numberValue;
    const parsed = Date.parse(String(value));
    return Number.isFinite(parsed) ? parsed : null;
  }

  function firstTimer(value) {
    const candidates = [value?.timer?.timestamp, value?.timestamp, value?.end, value?.ends_at, value?.finish_at, value?.expires_at, value?.expired_at];
    for (const candidate of candidates) { const result = timestampFrom(candidate); if (result && result > Date.now()) return result; }
    return null;
  }

  function countdownLabel(timestamp) {
    if (!timestamp) return '—';
    const seconds = Math.max(0, Math.floor((timestamp - Date.now()) / 1000));
    const days = Math.floor(seconds / 86400), hours = Math.floor(seconds % 86400 / 3600), minutes = Math.floor(seconds % 3600 / 60);
    return days ? `${days}${either('д','d')} ${hours}${either('ч','h')}` : `${hours}${either('ч','h')} ${minutes}${either('м','m')}`;
  }

  function dailyAdvertisement(documentValue = playerDocument) {
    const candidates = [
      documentValue?.advertisement, documentValue?.player?.advertisement,
      documentValue?.data?.advertisement, documentValue?.data?.player?.advertisement
    ];
    const wrapper = candidates.find(value => value && typeof value === 'object') || {};
    const raw = wrapper.$ && typeof wrapper.$ === 'object' ? wrapper.$ : wrapper;
    const card = [...document.querySelectorAll('.ribbon-ad-card[data-lot-id],.simple-ad-card[data-lot-id]')].find(visible);
    const lotId = String(raw.shop_lot_id ?? raw.lot_id ?? raw.lotId ?? raw.shopLotId ?? card?.dataset?.lotId ?? '');
    const watchedAt = Math.max(Number(sessionStorage.getItem('timestamp-ad') || 0), Number(localStorage.getItem('timestamp-ad') || 0));
    const cooldownUntil = watchedAt > 0 ? watchedAt + 1000 : 0;
    const timer = cooldownUntil > Date.now() ? {timestamp:cooldownUntil} : null;
    return {raw, lotId, type:String(raw.type || (card ? 'external' : '')).toLowerCase(), timer, available:!!lotId && !timer};
  }


  const DAILY_CANON_CLAN_IDS=new Set(['mf_clan_shoplot_recruits_lvl_5','mf_clan_shoplot_hballs_lvl_5','mf_clan_shoplot_recruits_lvl_10','mf_clan_shoplot_hballs_lvl_10','mf_clan_shoplot_recruits_lvl_15','mf_clan_shoplot_hballs_lvl_15','mf_clan_shoplot_recruits_lvl_20','mf_clan_shoplot_hballs_lvl_20']);
  const DAILY_CANON_INVEST_IDS=new Set(['mf_shoplot_building_helpers_offer_01','mf_shoplot_building_helpers_offer_02']);
