  const MODULE_LIVE_TTL_MS = 12000;
  const HK_MODULE_COOLDOWN_REV='module-live-cooldown-20260922-r1';
  const moduleLiveState = new Map();
  function moduleMutationBusy(){return !!(hkRunner.running||pitRunning||businessBusy||fairRunning||shopRunning||recipeRunning||bureauRunning||resourceBusy||mapScanning||dailyRunning||clanSkillScanning||growthBusy);}
  async function refreshModuleLive(page, {force=false} = {}) {
    const key = String(page || '');
    if (!key || key.startsWith('growth')) return null;
    if(moduleMutationBusy()){recordDiagnostic('module-live-read-deferred',{page:key});return null;}
    const existing = moduleLiveState.get(key) || {at:0,promise:null,blockedUntil:0,rateNoticeAt:0};
    const cooldownRemaining=gameApiCooldownRemainingMs();
    const blockedUntil=Math.max(Number(existing.blockedUntil||0),gameApiRateLimitUntil||0);
    if(cooldownRemaining>0||blockedUntil>Date.now()){
      const until=Math.max(blockedUntil,Date.now()+cooldownRemaining);
      existing.blockedUntil=until;
      moduleLiveState.set(key,existing);
      recordDiagnostic('module-live-read-rate-blocked',{page:key,remainingMs:Math.max(0,until-Date.now())});
      return null;
    }
    if (existing.promise) return existing.promise;
    if (!force && Date.now() - Number(existing.at || 0) < MODULE_LIVE_TTL_MS) return null;
    let liveReadOk=false;
    const task = (async () => {
      try {
        if (!licenseState.allowed) {
          const connected = await bootstrapLateGameConnection();
          if (!connected || !playerDocument) return null;
          await checkLicense(playerDocument.player || {}, true);
          if (!licenseState.allowed) return null;
        }
        if (key === 'daily') {const value=await refreshDailyTasks();liveReadOk=true;return value;}
        if (key === 'resources') {const value=await loadResources(false,{playerMaxAgeMs:RESOURCE_PLAYER_CACHE_MS});liveReadOk=true;return value;}
        if (key === 'fair') {const value=await loadFair();liveReadOk=true;return value;}
        if (key === 'shop') {const value=await loadShop();liveReadOk=true;return value;}
        if (key === 'recipes') {const value=await loadRecipes();liveReadOk=true;return value;}
        if (key === 'business') {
          playerDocument = await apiJson('/player/me','POST');
          await ensureRecipeMetadata();
          refreshBusinessData();
          liveReadOk=true;return playerDocument;
        }
        if (key === 'pit') {
          const results=await Promise.all([apiJson('/player/me','POST'),pitCanonLoadRewardLive()]);
          playerDocument=results[0];
          acceptPitDocument(`${apiBase}/player/me`,playerDocument);
          pitCanonRender();
          liveReadOk=true;return playerDocument;
        }
        if (key === 'bosses') {const value=await refreshBosses(false);liveReadOk=true;return value;}
        if (key === 'neighborhoods') {const value=await refreshNeighborhoodBattles(false);liveReadOk=!!value;return value;}
        if (key === 'wars') {const value=await refreshWars(false);liveReadOk=true;return value;}
        if (key === 'rats') {const value=await refreshRatHunt(false);liveReadOk=!!value;return value;}
        if (key === 'clan') {
          playerDocument = await apiJson('/player/me','POST');
          renderClanSkills();
          await refreshSharedClanSkills();
          maybeAutoScanClanSkills();
          liveReadOk=true;return playerDocument;
        }
        if (key === 'buildings') {const value=await refreshBuildings(false);liveReadOk=true;return value;}
        if (key === 'explore') {const value=await refreshExplore(false);liveReadOk=!!value;return value;}
        if (key === 'maps') {
          playerDocument = await apiJson('/player/me','POST');
          await loadMapIndex(false);
          liveReadOk=true;return playerDocument;
        }
        return null;
      } catch (error) {
        const rateLimited=error?.name==='HKRateLimitError'||Number(error?.httpStatus||0)===429;
        recordDiagnostic('module-live-read-error',{page:key,error:error?.message||error,rateLimited});
        if(rateLimited){
          const row=moduleLiveState.get(key)||{};
          row.blockedUntil=Math.max(Number(row.blockedUntil||0),Date.now()+Math.max(1000,Number(error?.retryAfterMs||gameApiCooldownRemainingMs()||GAME_API_429_FALLBACK_COOLDOWN_MS)));
          moduleLiveState.set(key,row);
        }else{
          log(`${either('Автообновление','Auto refresh')} ${key}: ${error?.message||error}`,'warn');
        }
        return null;
      } finally {
        const row = moduleLiveState.get(key) || {};
        row.at = liveReadOk ? Date.now() : Number(row.at||0); row.promise = null; moduleLiveState.set(key,row);
      }
    })();
    moduleLiveState.set(key,{...existing,promise:task});
    return task;
  }

  function renderRunnerState() {
    if (!root) return;
    const box=root.querySelector('#hk-runner'); if(!box)return;
    const state=hkRunner.state;
    const visibleState=state.status!=='idle',title=String(state.title||''),exploreRun=visibleState&&[either('Исследование · E3','Explore · E3'),either('Исследование','Explore')].includes(title),buildingsRun=visibleState&&title===either('Здания','Buildings'),resourcesRun=visibleState&&Object.keys(RESOURCE_BUILDING_TYPES).some(kind=>title===resourceTypeName(kind)),fairRun=visibleState&&title===either('Ярмарка','Fair'),businessesRun=visibleState&&title===either('Перестановка бизнесов','Business rearrangement'),hamstersRun=visibleState&&title===either('Хомяки','Hamsters'),generalsRun=visibleState&&title===either('Генералы','Generals'); box.classList.toggle('show',visibleState);
    box.classList.toggle('pit-run',visibleState&&title===either('Ямы','Pits'));
    box.classList.toggle('explore-run',exploreRun);
    box.classList.toggle('buildings-run',buildingsRun);
    box.classList.toggle('resources-run',resourcesRun);
    box.classList.toggle('fair-run',fairRun);
    box.classList.toggle('businesses-run',businessesRun);
    box.classList.toggle('hamsters-run',hamstersRun);
    box.classList.toggle('generals-run',generalsRun);
    if(!visibleState)return;
    const labels={running:either('Выполняется','Running'),paused:either('Пауза','Paused'),stopping:either('Остановка','Stopping'),done:either('Готово','Done'),error:either('Ошибка','Error')};
    const percent=state.total?Math.max(0,Math.min(100,(state.done/state.total)*100)):(state.status==='done'?100:0);
    root.querySelector('#hk-runner-title').textContent=state.title||either('Выполнение','Execution');
    const stateLabel=labels[state.status]||state.status;
    root.querySelector('#hk-runner-state').textContent=(buildingsRun||resourcesRun||fairRun||exploreRun||businessesRun||hamstersRun||generalsRun)&&state.total?`${stateLabel} · ${state.done}/${state.total}`:stateLabel;
    root.querySelector('#hk-runner-step').textContent=state.error||state.step||(state.total?`${state.done} / ${state.total}`:'');
    const runnerFill=root.querySelector('#hk-runner-fill');
    if(businessesRun||hamstersRun||generalsRun){runnerFill.style.width='100%';runnerFill.style.height=`${percent}%`;}else{runnerFill.style.width=`${percent}%`;runnerFill.style.height='100%';}
    const history=root.querySelector('#hk-runner-history');
    if(history){
      const rows=Array.isArray(state.history)?state.history:[];
      history.innerHTML=rows.map(row=>{
        if(exploreRun&&row.stageKey){const st=String(row.stageStatus||'pending'),icon=st==='done'?'✓':st==='running'?'▶':st==='skipped'?'—':st==='error'?'×':'○';return '<div class="hk-runner-history-row hk-runner-stage '+escapeHtml('stage-'+st)+'"><span class="hk-runner-stage-icon">'+icon+'</span><b>'+escapeHtml(row.text||'')+'</b></div>';}
        return '<div class="hk-runner-history-row '+escapeHtml(row.type||'')+'"><span>'+new Date(row.at||Date.now()).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',second:'2-digit'})+'</span><b>'+escapeHtml(row.text||'')+'</b></div>';
      }).join('');
      history.style.display=rows.length?'grid':'none';
      if(fairRun&&rows.length) history.scrollTop=history.scrollHeight;
    }
    const pause=root.querySelector('#hk-runner-pause'); const stop=root.querySelector('#hk-runner-stop');
    pause.textContent=state.status==='paused'?either('Продолжить','Continue'):either('Пауза','Pause');
    pause.disabled=!state.pausable||!['running','paused'].includes(state.status);
    stop.textContent=either('Остановить','Stop'); stop.disabled=!state.stoppable||!['running','paused'].includes(state.status);
  }

