  function startNetworkCapture() {
    try { installNetworkCapture(); }
    catch (_) { setTimeout(startNetworkCapture, 250); }
  }

  function startInterface() {
    hkStartupStage = document.body ? 'BODY' : 'WAIT_BODY';
    if (root?.isConnected && root.querySelector('#hk-fab')) {
      hideBootstrap();
      return;
    }
    if (root) {
      try { root.remove(); } catch (_) {}
      root = null;
      panel = null;
    }
    try {
      if (document.body) { hkStartupStage = 'RENDER'; renderUI(); }
    } catch (error) {
      try { root?.remove(); } catch (_) {}
      root = null;
      panel = null;
      showBootstrap(error?.message || error);
      setTimeout(startInterface, 500);
      return;
    }
    if (!root?.isConnected || !root.querySelector('#hk-fab')) setTimeout(startInterface, 250);
  }

  // HK_NATIVE_LOGIN_GATE_V1 login-gate-20260920-r1
  const HK_NATIVE_LOGIN_GATE_REV = 'login-gate-hotfix-20260920-r2';
  const HK_UI_PRELOGIN_REV = 'ui-prelogin-20260920-r3';
  const HK_LAUNCHER_HANDOFF_REV = 'launcher-handoff-20260920-r4';
  const HK_LATE_LOGIN_HANDOFF_REV = 'late-login-handoff-20260921-r1';
  const HK_LATE_LOGIN_RECOVERY_REV = 'late-login-recovery-20260926-r1';
  let hkNativeLoginRuntimeStarted = false;
  let hkLateLoginHandoffAttempts = 0;
  let hkLateLoginHandoffBusy = false;
  let hkLateLoginHandoffNextAt = 0;
  const hkLateLoginHandoffStartedAt = Date.now();

  function hkNativeGameLoginReady() {
    // PRELOGIN_ZERO_GAME_API_R1
    // Normal path: the native game itself made an authenticated /player/me and
    // our passive observer captured both the response and its bearer.
    return !!(playerDocument && apiHeaders.Authorization);
  }

  function hkPriorNativePlayerMeEvidence() {
    try {
      const allowedOrigins = new Set([new URL(GAME_API_FALLBACK).origin]);
      if (apiBase) allowedOrigins.add(new URL(apiBase).origin);
      for (const entry of performance.getEntriesByType('resource').slice().reverse()) {
        const url = new URL(String(entry?.name || ''), location.href);
        if (url.pathname === '/player/me' && allowedOrigins.has(url.origin)) return true;
      }
    } catch (_) {}
    return false;
  }

  async function hkTryLateLoginHandoff() {
    if (hkNativeGameLoginReady() || hkLateLoginHandoffBusy) return hkNativeGameLoginReady();
    const now=Date.now();
    if (now < hkLateLoginHandoffNextAt) return false;

    // A local 429 gate is not a failed login attempt. Do not burn through the
    // recovery loop while Game API is intentionally cooling down.
    const cooldown=Math.max(0,gameApiCooldownRemainingMs());
    if(cooldown>0){
      hkLateLoginHandoffNextAt=now+cooldown+250;
      hkStartupStage='WAIT_NATIVE_LOGIN';
      recordDiagnostic('late-login-handoff-cooldown',{revision:HK_LATE_LOGIN_RECOVERY_REV,cooldownMs:cooldown});
      return false;
    }

    restoreGameApiBaseFromPerformance();
    refreshStoredGameAuthorization();
    const token = currentGameBearer();
    const tokenReady = !!token && jwtExpiration(token) > Date.now() + 5000;
    const nativePlayerMeSeen = hkPriorNativePlayerMeEvidence();
    const nativeAuthParams = readNativeGameAuthParams();
    const storageFallbackReady =
      Date.now() - hkLateLoginHandoffStartedAt >= 2500 &&
      !!nativeAuthParams?.authType &&
      !!nativeAuthParams?.authData &&
      tokenReady;

    // We never create a game session here. Late handoff is allowed only after
    // evidence that the native game has already authenticated, then performs
    // one read-only /player/me to recover state missed by a late bookmarklet.
    if (!tokenReady || (!nativePlayerMeSeen && !storageFallbackReady)) return false;

    hkLateLoginHandoffBusy = true;
    hkLateLoginHandoffAttempts += 1;
    hkLateLoginHandoffNextAt = Date.now() + Math.min(8000,1500 + hkLateLoginHandoffAttempts*500);
    hkStartupStage = 'LATE_HANDOFF';
    bootstrapProblem='';
    showBootstrap();
    recordDiagnostic('late-login-handoff-attempt', {
      revision:HK_LATE_LOGIN_RECOVERY_REV,
      attempt:hkLateLoginHandoffAttempts,
      nativePlayerMeSeen,
      authSource:nativeAuthParams?.source || '',
      tokenFingerprint:diagnosticFingerprint(token),
    });
    try {
      const ok = await bootstrapLateGameConnection();
      const afterCooldown=Math.max(0,gameApiCooldownRemainingMs());
      if(!ok && afterCooldown>0) hkLateLoginHandoffNextAt=Date.now()+afterCooldown+250;
      recordDiagnostic('late-login-handoff-result', {ok, attempt:hkLateLoginHandoffAttempts, cooldownMs:afterCooldown});
      return !!ok && hkNativeGameLoginReady();
    } finally {
      hkLateLoginHandoffBusy = false;
      if (!hkNativeGameLoginReady()) hkStartupStage = 'WAIT_NATIVE_LOGIN';
    }
  }

  async function startAfterNativeGameLogin() {
    if (hkNativeLoginRuntimeStarted) return;
    if (!hkNativeGameLoginReady()) {
      hkStartupStage = 'WAIT_NATIVE_LOGIN';
      try {
        if (await hkTryLateLoginHandoff()) {
          setTimeout(startAfterNativeGameLogin, 0);
          return;
        }
      } catch (error) {
        recordDiagnostic('late-login-handoff-error',{error:error?.message || error});
      }
      setTimeout(startAfterNativeGameLogin, 500);
      return;
    }
    hkNativeLoginRuntimeStarted = true;
    startInterface();
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', startInterface, {once:true});
    setInterval(() => {
      // PRELOGIN_ZERO_GAME_API_R1: observe only; never create/refresh the
      // native session and never bootstrap /player/me ourselves.
      refreshStoredGameAuthorization();
      const token=currentGameBearer();
      const ok=!!token && jwtExpiration(token)>Date.now()+5000;
      setHealth('auth', ok, ok ? 'авторизация активна' : 'ожидаю вход игры');
      if (ok && licenseState.publicCollectorAuthSync) maybeSyncPublicCollectorAuthorization(token).catch(() => {});
    }, 30000);
    setInterval(captureActiveEventCode, 1500);
    setTimeout(() => hkGameBridge.discover(false), 1500);
    setInterval(() => { if (!hkGameBridge.ready) hkGameBridge.discover(false); }, 30000);
    setInterval(() => { if (playerDocument) checkLicense(playerDocument.player || {}, true); }, LICENSE_RECHECK_MS);
    setInterval(() => { if (hkRunner.running||autoRoutineLeaseHold) void syncPublicCollectorActivity(true,autoRoutineLeaseHold?'auto-routine':String(hkRunner.state.title||'automation'),true); }, PUBLIC_COLLECTOR_ACTIVITY_HEARTBEAT_MS);
    recordDiagnostic('native-login-gate-open',{revision:'prelogin-zero-game-api-r1'});
  }

  // HK Puzzle Solver v3 embedded only in the common HK userscript.
  // It remains DOM-only. Number hints are always passive; optional battle
  // auto-click is local, default-off, and is NOT published to the standalone
